function loadNavPerms() {
  // Priority 1: D1-sourced perms loaded at login (window._gwNavPerms)
  if (window._gwNavPerms) return window._gwNavPerms;
  // Priority 2: localStorage cache (written at login as offline fallback)
  try {
    const saved = JSON.parse(localStorage.getItem(NAV_PERMS_KEY) || 'null');
    if (saved && typeof saved === 'object') return { ...DEFAULT_NAV_PERMS, ...saved };
  } catch(e) {}
  // Priority 3: hardcoded defaults (used before login completes)
  return structuredClone(DEFAULT_NAV_PERMS);
}
function saveNavPerms(perms) {
  // Update the in-memory D1 cache
  window._gwNavPerms = perms;
  // Also persist to localStorage as offline fallback
  try { localStorage.setItem(NAV_PERMS_KEY, JSON.stringify(perms)); } catch(_) {}
  // Persist to D1 (fire-and-forget)
  if (window._d1Ready) {
    fetch('/api/nav-perms', {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'include',
      body: JSON.stringify({ perms })
    }).catch(e => console.warn('[NavPerms] D1 save failed:', e.message));
  }
}
function canViewTab(viewName) {
  let rep = window.getCurrentRep ? window.getCurrentRep() : null;
  // ── Mobile bootstrap guard ────────────────────────────────────────────────
  // getCurrentRep() relies on localStorage + REPS array hydration, which may
  // not be complete yet on first load. Fall back to _d1SessionRep (set
  // immediately when the session cookie is verified) so canViewTab() never
  // incorrectly returns false for authenticated users on mobile.
  if (!rep && window._d1SessionRep) {
    const d1 = window._d1SessionRep;
    rep = { id: d1.id, role: d1.role || 'admin', name: d1.name };
  }
  if (!rep) return false;
  // Admin always has full access (no permission gate for admin role)
  if (rep.role === 'admin') return true;
  const perms = loadNavPerms();
  // Check cached/D1-sourced perms first, then always supplement with DEFAULT_NAV_PERMS
  // so newly-added views are never blocked by a stale cached permission set.
  const cachedAllowed  = perms[rep.role] || [];
  const defaultAllowed = DEFAULT_NAV_PERMS[rep.role] || [];
  if (cachedAllowed.includes(viewName) || defaultAllowed.includes(viewName)) return true;
  // For custom roles not in DEFAULT_NAV_PERMS, check D1-sourced role permissions
  if (window._gwRoles) {
    const roleDef = window._gwRoles.find(r => r.id === rep.role);
    if (roleDef && roleDef.permissions && Array.isArray(roleDef.permissions.views)) {
      return roleDef.permissions.views.includes(viewName);
    }
  }
  return false;
}
window.loadNavPerms = loadNavPerms;
window.saveNavPerms = saveNavPerms;
window.DEFAULT_NAV_PERMS = DEFAULT_NAV_PERMS;

function escapeHtml(str=''){
  return String(str).replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
}
function nl2br(str=''){ return escapeHtml(str).replace(/\n/g,'<br>'); }
function uid(prefix='id'){ return `${prefix}_${Date.now()}_${Math.random().toString(16).slice(2,8)}`; }
function todayISO(){ return new Date().toISOString().slice(0,10); }
function prettyDate(dateStr){ if(!dateStr) return 'Not set'; const d = new Date(`${dateStr}T12:00:00`); return d.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}); }
function list(items){ return `<ul class="list">${items.map(i=>`<li>${escapeHtml(i)}</li>`).join('')}</ul>`; }
function badge(text, cls=''){ return `<span class="badge ${cls}">${escapeHtml(text)}</span>`; }
function statusCssClass(status){
  const map = {
    'New Lead':'new-lead','Contacted':'contacted',
    'Discovery Scheduled':'discovery','Discovery Complete':'discovery','Site Walk':'discovery',
    'Proposal / Estimate Sent':'proposal','Proposal Sent':'proposal',
    'Follow-Up':'follow-up','Negotiation':'negotiation','Verbal Approval':'verbal',
    'Sold / Activation':'sold','Closed Lost':'lost'
  };
  return map[status] || 'pending';
}
function estCommission(opp){
  // Delegate to the master engine (COMM-08: no page-level hardcoded math)
  if (typeof window.estimateCommission === 'function') {
    const rep = window.getCurrentRep ? window.getCurrentRep() : null;
    const planId = rep?.commissionPlan || 'ryan';
    const result = window.estimateCommission({
      planId,
      workType:   opp?.workType   || 'landscape',
      leadSource: opp?.leadSource || 'company_lead',
      jobValue:   Number(opp?.jobValue || 0),
      collected:  !!opp?.collected,
      approved:   !!opp?.commissionApproved
    });
    return result.amount;
  }
  // Fallback before reps.js loads
  const val = Number(opp?.jobValue || 0);
  if (!val) return 0;
  const rates = { landscape:.06, maintenance_onetime:.04, maintenance_recurring:.20, hardscape:.06, drainage:.06, design_build:.06 };
  return val * (rates[opp?.workType] || .06);
}
// Toast type icons (inline SVG, 16×16, stroke-based)
const _toastIcons = {
  success: '<svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 8l3.5 3.5L13 4.5"/></svg>',
  error:   '<svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 4l8 8M12 4l-8 8"/></svg>',
  warning: '<svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M8 3L1.5 13.5h13L8 3z"/><line x1="8" y1="7" x2="8" y2="10"/><circle cx="8" cy="12.5" r=".5" fill="currentColor" stroke="none"/></svg>',
  info:    '<svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="8" cy="8" r="6.5"/><line x1="8" y1="7.5" x2="8" y2="11.5"/><circle cx="8" cy="5" r=".5" fill="currentColor" stroke="none"/></svg>'
};
const _toastVariants = ['toast-success','toast-error','toast-warning','toast-info'];

function showToast(message, typeOrDuration){
  if (!toastEl) return;

  // Resolve arguments: showToast(msg) | showToast(msg, 4000) | showToast(msg, 'success')
  let type = null, duration = null;
  if (typeof typeOrDuration === 'string' && _toastVariants.includes('toast-' + typeOrDuration)) {
    type = typeOrDuration;
  } else if (typeof typeOrDuration === 'number') {
    duration = typeOrDuration;
  }

  // Clear variant classes from previous toast
  _toastVariants.forEach(cls => toastEl.classList.remove(cls));

  // Apply variant class and icon
  if (type) {
    toastEl.classList.add('toast-' + type);
    toastEl.innerHTML = '<span class="toast-icon">' + _toastIcons[type] + '</span><span>' + message + '</span>';
  } else {
    toastEl.textContent = message;
  }

  toastEl.hidden = false;

  // Clear any previous timer
  if (toastEl._hideTimer) clearTimeout(toastEl._hideTimer);

  // Auto-hide: longer messages get more time, min 2.5s max 6s
  const ms = duration || Math.min(6000, Math.max(2500, message.length * 50));
  toastEl._hideTimer = setTimeout(() => {
    toastEl.hidden = true;
    _toastVariants.forEach(cls => toastEl.classList.remove(cls));
  }, ms);

  // Click anywhere on toast to dismiss immediately
  toastEl.onclick = () => {
    toastEl.hidden = true;
    clearTimeout(toastEl._hideTimer);
    _toastVariants.forEach(cls => toastEl.classList.remove(cls));
  };
  toastEl.style.cursor = 'pointer';
}
function copyText(text, btnEl){
  const doFeedback = () => {
    showToast('Copied to clipboard!');
    if(btnEl){
      const orig = btnEl.textContent;
      btnEl.textContent = 'Copied!';
      btnEl.classList.add('btn-copied');
      setTimeout(()=>{ btnEl.textContent=orig; btnEl.classList.remove('btn-copied'); }, 2000);
    }
  };
  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(text).then(doFeedback).catch(()=>{
      fallbackCopy(text); doFeedback();
    });
  } else { fallbackCopy(text); doFeedback(); }
}
function fallbackCopy(text){
  const ta = document.createElement('textarea');
  ta.value = text; ta.style.position='fixed'; ta.style.opacity='0';
  document.body.appendChild(ta); ta.select();
  try { document.execCommand('copy'); } catch(e){}
  document.body.removeChild(ta);
}
// ══════════════════════════════════════════════════════════════════════════════
// NAV HISTORY TRAIL  — breadcrumb strip shown below the topbar
// Max 8 unique entries; deduplicates adjacent; persists to sessionStorage.
// ══════════════════════════════════════════════════════════════════════════════
(function _initGwTrail(){
  const SS_KEY = 'gwNavHistory';
  const MAX    = 8;

  // Restore from sessionStorage on page load
  try {
    const saved = sessionStorage.getItem(SS_KEY);
    window._gwNavHistory = saved ? JSON.parse(saved) : [];
  } catch(e) {
    window._gwNavHistory = [];
  }

  window._gwPushTrail = function(viewName){
    const hist = window._gwNavHistory;
    // Skip system / modal-style views that shouldn't pollute the trail
    const skipList = ['today']; // 'today' is home — always accessible, skip trail for it
    // Deduplicate adjacent: don't push same view twice in a row
    if (hist.length && hist[hist.length - 1] === viewName) return;
    // Remove any earlier occurrence of this view (bubble to end)
    const idx = hist.indexOf(viewName);
    if (idx !== -1) hist.splice(idx, 1);
    hist.push(viewName);
    // Trim to max
    if (hist.length > MAX) hist.splice(0, hist.length - MAX);
    window._gwNavHistory = hist;
    try { sessionStorage.setItem(SS_KEY, JSON.stringify(hist)); } catch(e){}
    window._gwRenderTrail(viewName);
  };

  window._gwRenderTrail = function(currentView){
    const trail = document.getElementById('gw-trail');
    if (!trail) return;
    const hist  = window._gwNavHistory || [];

    // Build label map (same as the one inside show())
    const labels = {
      // Workspace top-level
      gwDashboard:'Dashboard', gwSales:'Sales', gwFinancial:'Financial',
      gwOperations:'Operations', gwLearning:'Learning', gwAdmin:'Admin',
      // Dashboard workspace tabs
      today:'My Day', myDashboard:'My Day', teamView:'Team',
      revenueAdmin:'Business Pulse', salesReports:'Business Pulse',
      financialReports:'Financial Snapshot', opsReports:'Operations Snapshot',
      teamReports:'Team',
      // Sales workspace tabs
      pipeline:'Pipeline', lead:'Leads', clients:'Clients', properties:'Properties',
      estimates:'Estimates', proposals:'Proposals', communications:'Communications',
      automations:'Sequences', templates:'Templates', sequences:'Sequences',
      talkTracks:'Talk Tracks', playbooks:'Playbooks', aiAssist:'AI Assist',
      campaigns:'Sequences', process:'Playbooks',
      forms:'Playbooks', scripts:'Talk Tracks', emailTemplates:'Templates',
      objections:'Talk Tracks', calculator:'Pricing Tools', ai:'AI Assist',
      // Financial workspace tabs
      financialHub:'Overview', invoices:'Invoices',
      payments:'Payments', deposits:'Deposits', statements:'Statements',
      financialActivity:'Activity', statement:'Statement',
      // Operations workspace tabs
      scheduleBoard:'Schedule', dispatchBoard:'Dispatch',
      recurringServices:'Recurring Services', crewView:'Crew View',
      workOrderList:'Work Orders', workOrderDetail:'Work Order',
      assetsHub:'Assets',
      assetList:'Assets', assetDetail:'Asset', maintenanceQueue:'Assets',
      inventoryList:'Assets', materialAllocation:'Assets',
      toolsConsumables:'Assets', timeTracker:'Time', opsHub:'Operations',
      // Admin workspace tabs
      settings:'Settings', userManagement:'Employees', integrations:'Settings',
      pricing:'Services & Pricing',
      manager:'Workflow', systemConfig:'Settings',
      systemTemplates:'Workflow', approvalQueue:'Workflow',
      auditLog:'Audit', portalAdmin:'Client Portal',
      automationCenter:'Workflow', fieldMode:'Field Preview',
      // Platform Admin
      gwTenants:'Tenants', gwLeads:'Sales Pipeline', gwSupport:'Support',
      gwDemos:'Demo Requests', gwPricing:'Pricing Plans',
      gwAnnounce:'Announcements', gwBilling:'Billing',
      gwPlatformSettings:'Platform Settings', superAdmin:'Platform Overview',
    };

    // Hide bar if only 1 item (nothing to navigate back to)
    if (hist.length < 2) {
      trail.style.display = 'none';
      return;
    }
    trail.style.display = 'flex';

    // Previous view for the ← Back button
    const prevIdx = hist.length - 2;
    const prevView = hist[prevIdx];
    const prevLabel = labels[prevView] || prevView;

    let html = '';

    // ← Back button (jump to previous)
    html += `<button class="gw-trail-back" onclick="show('${prevView}')" title="Back to ${prevLabel}">` +
      `<svg width="12" height="12" viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="7.5,2 3.5,6 7.5,10"/></svg>` +
      `${prevLabel}</button>`;

    // Separator
    html += `<span class="gw-trail-sep"></span>`;

    // History pills (oldest → newest / current)
    hist.forEach((v, i) => {
      const lbl  = labels[v] || v;
      const isActive = (v === currentView);
      if (i > 0) html += `<span class="gw-trail-chevron">›</span>`;
      if (isActive) {
        html += `<span class="gw-trail-pill gw-trail-pill--active" title="${lbl}">${lbl}</span>`;
      } else {
        html += `<button class="gw-trail-pill" onclick="show('${v}')" title="${lbl}">${lbl}</button>`;
      }
    });

    trail.innerHTML = html;

    // Auto-scroll so current (rightmost) pill is visible
    requestAnimationFrame(() => { trail.scrollLeft = trail.scrollWidth; });
  };
})();

// ══════════════════════════════════════════════════════════════════════════════
// WORKSPACE HUB FUNCTIONS — 5-workspace navigation model
// Each function renders the workspace shell with internal tab subnav.
// Legacy view names route into these via aliases in show().
// ══════════════════════════════════════════════════════════════════════════════

// ════════════════════════════════════════════════════════════════════════════
// SIDEBAR NAV TREE — v3 clean rebuild
// Config: { id, label }          → regular item
//         { id, label, sub:true }→ permanently-visible indented child
// ════════════════════════════════════════════════════════════════════════════

const _gwWsNameToId = {
  Dashboard: 'gwDashboard',
  Sales: 'gwSales',
  Financial: 'gwFinancial',
  Operations: 'gwOperations',
  Learning: 'gwLearning',
  Admin: 'gwAdmin',
};

// Render a flat tab config into the sidebar panel.
// sub:true items are treated identically to regular items — everything is flat.
// Dividers are ignored. No chevrons, no accordion groups.
// ── Mobile tab allow-lists — only these tabs show in the side-nav on phones ──
// Everything else still works if navigated to directly; it just won't clutter
// the mobile nav. Keep lists small: only what you'd realistically use in the field.
const _GW_MOBILE_TABS = {
  Dashboard:   ['today','fieldDashboard'],
  Sales:       ['pipeline','lead','clients','estimates','communications'],
  Financial:   ['financialHub','invoices','gwReviews','gwStripe'],
  Operations:  ['scheduleBoard','dispatchBoard','workOrderList','timeTracker','assetsHub'],
  Learning:    ['academy'],
  Admin:       ['settings','userManagement'],
};

function _gwSetHeader(wsName, tabsConfig, activeTabId) {
  const wsId = _gwWsNameToId[wsName] || null;
  if (!wsId) return;
  const panel = document.getElementById('gw-subtabs-' + wsId);
  if (!panel) return;

  const isMob    = window.innerWidth <= 768;
  const allowed  = isMob ? (_GW_MOBILE_TABS[wsName] || null) : null;

  let html = '';
  tabsConfig.forEach(t => {
    if (t.divider) return;
    if (allowed && !allowed.includes(t.id)) return; // hide on mobile
    const activeClass = t.id === activeTabId ? ' nav-subtab--active' : '';
    html += `<button class="nav-subtab${activeClass}" data-tab="${t.id}" onclick="show('${t.id}')">${t.label}</button>`;
  });
  panel.innerHTML = html;
}

function _gwClearHeader() { /* no-op — panels stay rendered */ }

// ── Dashboard workspace ───────────────────────────────────────────────────────
function gwDashboard(tab) {
  tab = tab || 'today';
  const rep = window.getCurrentRep ? window.getCurrentRep() : null;
  const _gwFieldRoles = window._GW_FIELD_ROLES || ['foreman','laborer','field_supervisor'];
  const isField = rep && _gwFieldRoles.includes(rep.role);

  // Field roles: fieldDashboard is their ONLY home — no My Day / Overview / Business Pulse / Financial tabs
  if (isField) {
    _gwSetHeader('Dashboard', [
      {id:'fieldDashboard', label:'Dashboard'},
    ], 'fieldDashboard');
    (typeof window.fieldDashboard === 'function') ? window.fieldDashboard() : _gwTabStub('Field Dashboard');
    return;
  }

  // Non-field roles: full dashboard tab set
  if (!tab || tab === 'gwDashboard' || tab === 'fieldDashboard') tab = 'today';
  const dashTabs = [
    {id:'today',           label:'My Day'},
    {id:'salesReports',    label:'Business Pulse'},
    {id:'financialReports',label:'Financial Snapshot'},
    {id:'opsReports',      label:'Operations Snapshot'},
  ];
  _gwSetHeader('Dashboard', dashTabs, tab);
  if (tab === 'today')            today();
  else if (tab === 'salesReports')    (typeof salesReports==='function') ? salesReports() : _gwTabStub('Business Pulse');
  else if (tab === 'financialReports')(typeof financialReports==='function') ? financialReports() : _gwTabStub('Financial Snapshot');
  else if (tab === 'opsReports')      (typeof opsReports==='function') ? opsReports() : _gwTabStub('Operations Snapshot');
  else today();
}
window.gwDashboard = gwDashboard;

// ── Sales workspace ───────────────────────────────────────────────────────────
// Communications hub tabs — Templates / Sequences / Talk Tracks / Playbooks /
// AI Assist are merged into the single Communications page as internal tabs.
const _GW_COMMS_HUB_TABS = ['communications','templates','sequences','talkTracks','playbooks','aiAssist'];

function gwSales(tab) {
  tab = tab || 'pipeline';
  _gwSetHeader('Sales', [
    {id:'pipeline',       label:'Pipeline'},
    {id:'lead',           label:'Leads'},
    {id:'clients',        label:'Clients'},
    {id:'properties',     label:'Properties'},
    {id:'teamView',       label:'Team'},
    {id:'estimates',      label:'Estimates'},
    {id:'communications', label:'Communications'},
  ], _GW_COMMS_HUB_TABS.includes(tab) ? 'communications' : (tab === 'proposals' ? 'estimates' : tab));
  if (tab === 'pipeline')            pipeline();
  else if (tab === 'lead')           lead();
  else if (tab === 'clients')        clients();
  else if (tab === 'teamView')       (typeof teamView==='function') ? teamView() : _gwTabStub('Team');
  else if (tab === 'estimates')      (typeof estimates==='function') ? estimates() : ((typeof estimateDetail==='function') ? estimateDetail() : _gwTabStub('Estimates'));
  else if (tab === 'proposals')      (typeof proposals==='function') ? proposals() : _gwTabStub('Proposals');
  else if (_GW_COMMS_HUB_TABS.includes(tab)) communicationsHub(tab);
  else if (tab === 'gwRecords')      lead();
  else pipeline();
}
window.gwSales = gwSales;

// ── Communications Hub ─────────────────────────────────────────────────────────
// One page for all client-facing messaging tools: the message inbox plus
// Templates, Sequences, Talk Tracks, Playbooks, and the AI Assistant.
// Each section keeps its original render function; the hub injects a persistent
// tab bar above whatever the section renders (survives view.innerHTML wipes via
// the _gwPendingSubHeader re-injection hook).
function communicationsHub(section) {
  section = _GW_COMMS_HUB_TABS.includes(section) ? section : (window._commsHubTab || 'communications');
  window._commsHubTab = section;

  const _gi = (n) => (typeof gwIcon === 'function') ? gwIcon(n, 14, 'currentColor') : '';
  // Only show sections the current role can access (admin sees all).
  // `alts` covers legacy permission keys still used in role configs.
  const _canSee = (t) => (typeof canViewTab !== 'function') ||
    canViewTab(t.id) || (t.alts || []).some(a => canViewTab(a));
  const HUB_TABS = [
    {id:'communications', label:'Inbox',       icon:_gi('comms')},
    {id:'templates',      label:'Templates',   icon:_gi('note'),       alts:['emailTemplates']},
    {id:'sequences',      label:'Sequences',   icon:_gi('automation'), alts:['automations','campaigns']},
    {id:'talkTracks',     label:'Talk Tracks', icon:_gi('call'),       alts:['scripts','objections']},
    {id:'playbooks',      label:'Playbooks',   icon:_gi('book'),       alts:['process','forms']},
    {id:'aiAssist',       label:'AI Assist',   icon:_gi('robot'),      alts:['ai']},
  ].filter(_canSee);

  // Persistent hub tab bar — re-injected after each innerHTML write so the
  // section functions (which own view.innerHTML) can't wipe it.
  const barHtml = `<div class="gw-sub-tabs" id="gw-sub-header" role="tablist" style="display:flex;gap:6px;flex-wrap:wrap;margin:0 0 18px;padding:6px;background:var(--gw-surface-2,#EDF2F0);border:1px solid var(--gw-line,var(--line,#DCE5E0));border-radius:12px">${
    HUB_TABS.map(t => `<button class="gw-sub-tab${t.id===section?' gw-sub-tab--active':''}" role="tab" data-tab="${t.id}"
      onclick="show('${t.id}')"
      style="display:inline-flex;align-items:center;gap:6px;border:none;border-radius:8px;padding:8px 14px;font-size:13px;font-weight:${t.id===section?'700':'500'};cursor:pointer;transition:background .12s,color .12s;${
        t.id===section
          ? 'background:var(--gw-card,#fff);color:var(--gw-ink,#0F1C14);box-shadow:0 1px 4px rgba(31,42,43,.10)'
          : 'background:transparent;color:var(--gw-text-muted,var(--muted,#6F7E6A))'
      }">${t.icon}${t.label}</button>`).join('')
  }</div>`;
  window._gwPendingSubHeader = barHtml;
  window._gwActiveSubTabs = {fn:'communicationsHub', sub:section};

  // Keep sidebar/workspace chrome in sync (all hub sections highlight Communications)
  _gwSetHeader('Sales', [
    {id:'pipeline',       label:'Pipeline'},
    {id:'lead',           label:'Leads'},
    {id:'clients',        label:'Clients'},
    {id:'properties',     label:'Properties'},
    {id:'teamView',       label:'Team'},
    {id:'estimates',      label:'Estimates'},
    {id:'communications', label:'Communications'},
  ], 'communications');
  activateNav('communications');

  // Render the selected section — each fn writes view.innerHTML; the patched
  // setter re-injects the hub bar at the top automatically.
  if (section === 'communications')  (typeof communicationsBoard==='function') ? communicationsBoard() : _gwTabStub('Communications');
  else if (section === 'templates')  (typeof templates==='function') ? templates() : _gwTabStub('Templates');
  else if (section === 'sequences')  (typeof sequences==='function') ? sequences() : _gwTabStub('Sequences');
  else if (section === 'talkTracks') (typeof talkTracks==='function') ? talkTracks() : _gwTabStub('Talk Tracks');
  else if (section === 'playbooks')  (typeof playbooks==='function') ? playbooks() : _gwTabStub('Playbooks');
  else if (section === 'aiAssist')   (typeof ai==='function') ? ai() : _gwTabStub('AI Assist');

  // These functions set _currentView/activateNav to their own ids — override
  // back to the hub so nav highlighting and hash restore stay consistent.
  window._currentView = section === 'communications' ? 'communications' : section;
  activateNav('communications');
  try { history.replaceState(null, '', '#' + (section === 'communications' ? 'communications' : section)); } catch(e) {}
}
window.communicationsHub = communicationsHub;

// gwRecords — backward-compat shim
function gwRecords(sub) {
  sub = sub || 'lead';
  window._gwPendingSubHeader = null;
  window._gwActiveSubTabs = null;
  show(sub === 'properties' ? 'properties' : sub === 'clients' ? 'clients' : 'lead');
}
window.gwRecords = gwRecords;

