window.saveClientForm = function(existingId) {
  const val = id => (document.getElementById(id)?.value||'').trim();
  const name = val('clf-name');
  if (!name) { showToast('Name is required'); return; }
  const tags = val('clf-tags').split(',').map(t=>t.trim()).filter(Boolean);
  const list = loadClients();
  if (existingId) {
    const idx = list.findIndex(x => x.id === existingId);
    if (idx < 0) return;
    Object.assign(list[idx], {
      name, firstName:val('clf-first'), lastName:val('clf-last'),
      type:val('clf-type'), status:val('clf-status'),
      email:val('clf-email'), phone:val('clf-phone'), mobile:val('clf-mobile'),
      street:val('clf-street'), city:val('clf-city'), state:val('clf-state'), zip:val('clf-zip'),
      tags, notes:val('clf-notes'), homeworksId:val('clf-hwid'), since:val('clf-since'),
      updatedAt:new Date().toISOString()
    });
  } else {
    list.push({
      id:clientId(), name, firstName:val('clf-first'), lastName:val('clf-last'),
      company:'', type:val('clf-type'), status:val('clf-status'),
      email:val('clf-email'), phone:val('clf-phone'), mobile:val('clf-mobile'),
      street:val('clf-street'), street2:'', city:val('clf-city'), state:val('clf-state'), zip:val('clf-zip'),
      since:val('clf-since'), tags, notes:val('clf-notes'), homeworksId:val('clf-hwid'),
      properties:[], createdAt:new Date().toISOString(), updatedAt:new Date().toISOString()
    });
  }
  saveClients(list);
  document.getElementById('clientFormModal')?.remove();
  showToast(existingId ? 'Client updated' : 'Client added');
  show('clients', existingId || undefined);
};

window.deleteClient = function(id) {
  if (!confirm('Delete this client? This cannot be undone.')) return;
  const list = loadClients().filter(x => x.id !== id);
  // Update localStorage cache without triggering a save-all to D1
  localStorage.setItem(CLIENTS_KEY, JSON.stringify(list));
  // Delete from D1 via write engine (logged, retried on failure)
  _d1DeleteClient(id);
  document.getElementById('clientFormModal')?.remove();
  showToast('Client deleted');
  show('clients');
};

// ── Client detail view ──────────────────────────────────────────────────────
function clientDetail(id) {
  const list = loadClients();
  const c = list.find(x => x.id === id);
  if (!c) { show('clients'); return; }

  // Linked pipeline opportunities
  const linkedOpps = state.opportunities.filter(o =>
    o.clientId === c.id || (o.client||'').toLowerCase() === (c.name||'').toLowerCase()
  );

  const addr = [c.street, c.street2, c.city, c.state, c.zip].filter(Boolean).join(', ');
  const tagHtml = (c.tags||[]).map(t => `<span class="cl-tag">${escapeHtml(t)}</span>`).join('');

  const propertiesHtml = (c.properties||[]).length ? c.properties.map(p => `
    <div class="cl-property-card">
      <div class="cl-property-label">${escapeHtml(p.label||'Property')}</div>
      <div class="cl-property-addr">${escapeHtml([p.street,p.street2,p.city,p.state,p.zip].filter(Boolean).join(', '))}</div>
      ${p.notes ? `<div class="cl-property-notes">${escapeHtml(p.notes)}</div>` : ''}
      <button class="cl-property-delete" onclick="deleteProperty('${c.id}','${p.id}')">Remove</button>
    </div>`).join('') : `<p class="muted" style="font-size:13px">No additional properties. The primary address above is the main service location.</p>`;

  const oppsHtml = linkedOpps.length ? linkedOpps.map(o => {
    const _repO = (window.REPS||[]).find(r => r.id === o.repId);
    const _repPill = _repO
      ? `<span style="font-size:10px;font-weight:600;color:${_repO.color||'#6F7E6A'};background:${_repO.color||'#6F7E6A'}18;border:1px solid ${_repO.color||'#6F7E6A'}40;border-radius:20px;padding:1px 7px;white-space:nowrap;flex-shrink:0">${escapeHtml(_repO.name)}</span>`
      : `<span style="font-size:10px;font-weight:600;color:#8B6914;background:#8B691418;border:1px solid rgba(139,105,20,.25);border-radius:20px;padding:1px 7px;white-space:nowrap;flex-shrink:0">${gwIcon('warning',16)} Unassigned</span>`;
    return `<button class="mini-row" onclick="show('pipeline','${o.id}')">
      <strong>${escapeHtml(o.client||'Unnamed')}</strong>
      <span class="status-chip ${statusCssClass(o.status||'')}" style="font-size:10px">${escapeHtml(o.status||'New Lead')}</span>
      <em>${escapeHtml(o.project||o.serviceLine||'Opportunity')}</em>
      <span style="display:flex;align-items:center;gap:5px;margin-left:auto;flex-shrink:0">
        ${_repPill}
        ${o.nextFollowUp ? `<span style="font-size:10px;color:#5C6B58">${prettyDate(o.nextFollowUp)}</span>` : ''}
      </span>
    </button>`;
  }).join('')
  : `<p class="muted" style="font-size:13px">No pipeline opportunities linked to this client yet.</p>`;

  view.innerHTML = `
    <div class="pl-page-header" style="margin-bottom:14px">
      <div class="pl-page-title">
        <button class="cl-back-btn" onclick="show('clients')">← Clients</button>
        <h1 class="pl-title" style="margin-top:4px">${escapeHtml(c.name)}</h1>
        <span class="pl-subtitle">${clientTypeBadge(c.type)} ${clientStatusDot(c.status)} ${escapeHtml(c.status||'Active')}${c.since?' · Since '+escapeHtml(c.since):''}</span>
      </div>
      <div class="pl-page-actions">
        <button class="primary-btn small" onclick="show('lead')">+ New Opportunity</button>
        <button class="secondary-btn small" onclick="showClientForm('${c.id}')">Edit</button>
      </div>
    </div>

    <div class="grid grid-2 mt">
      <!-- Contact card -->
      <section class="card">
        <div class="section-head"><h2>Contact Info</h2></div>
        <dl class="cl-dl">
          ${c.email  ? `<dt>Email</dt><dd><button class="cl-link" style="background:none;border:none;padding:0;cursor:pointer;font-size:inherit" onclick="_gwOpenMessageModal({type:'email',to:'${escapeHtml(c.email)}',toName:'${escapeHtml(c.name||'')}'})">\${escapeHtml(c.email)}</button></dd>` : ''}
          ${c.phone  ? `<dt>Phone</dt><dd>${escapeHtml(c.phone)}</dd>` : ''}
          ${c.mobile ? `<dt>Mobile</dt><dd>${escapeHtml(c.mobile)}</dd>` : ''}
          ${addr     ? `<dt>Address</dt><dd>${escapeHtml(addr)}</dd>` : ''}
          ${c.homeworksId ? `<dt>Homeworks ID</dt><dd style="color:#6F7E6A;font-size:12px">${escapeHtml(c.homeworksId)}</dd>` : ''}
        </dl>
        ${tagHtml ? `<div style="margin-top:10px;display:flex;gap:6px;flex-wrap:wrap">${tagHtml}</div>` : ''}
        ${c.notes ? `<div class="cl-notes-block">${escapeHtml(c.notes)}</div>` : ''}
      </section>

      <!-- Pipeline opportunities -->
      <section class="card">
        <div class="section-head">
          <h2>Pipeline</h2>
          <span class="badge ${linkedOpps.length?'':'neutral-badge'}">${linkedOpps.length} opp${linkedOpps.length===1?'':'s'}</span>
        </div>
        ${oppsHtml}
        ${linkedOpps.length ? `<div style="margin-top:10px"><button class="secondary-btn small" onclick="show('lead')">+ New Opportunity</button></div>` : ''}
      </section>
    </div>

    <!-- Properties -->
    <section class="card mt">
      <div class="section-head">
        <h2>Service Properties</h2>
        <button class="secondary-btn small" onclick="showAddProperty('${c.id}')">+ Add Property</button>
      </div>
      <div class="cl-properties-grid">${propertiesHtml}</div>
    </section>
  `;
}

// ═══════════════════════════════════════════════════════════════════════════════
// CUSTOMER DETAIL PAGE — Full CRM customer record
// show('customerDetail', clientId) — also accepts '__byname__ClientName'
// ═══════════════════════════════════════════════════════════════════════════════
async function customerDetail(clientId) {
  view.innerHTML = `<div style="padding:40px;text-align:center;color:var(--gw-text-muted)">
    <div class="sb-spinner"></div><p style="margin-top:12px">Loading customer…</p></div>`;

  // ── Resolve by name if needed ─────────────────────────────────────────────
  let resolvedId = clientId;
  if (clientId && clientId.startsWith('__byname__')) {
    const name = clientId.slice(10);
    try {
      const r = await fetch('/api/clients', { credentials:'include' });
      const d = await r.json();
      const found = (d.data || d).find(c => (c.name||'').toLowerCase() === name.toLowerCase());
      if (found) resolvedId = found.id;
      else {
        view.innerHTML = `<div style="padding:32px;text-align:center"><p>Customer "${escapeHtml(name)}" not found.</p><button class="rp-btn" onclick="show('clients')">← Back to Clients</button></div>`;
        return;
      }
    } catch(e) { resolvedId = null; }
  }

  // ── Fetch all data in parallel ────────────────────────────────────────────
  let client = null, workOrders = [], customerNotes = [];
  try {
    const [cr, wr, nr] = await Promise.all([
      fetch(`/api/customers/${resolvedId}`, { credentials:'include' }).then(r=>r.json()),
      fetch(`/api/work-orders?client_id=${resolvedId}&limit=200`, { credentials:'include' }).then(r=>r.json()),
      fetch(`/api/customers/${resolvedId}/notes`, { credentials:'include' }).then(r=>r.json()),
    ]);
    client = cr.data || cr;
    workOrders = wr.data || [];
    customerNotes = nr.data || [];
  } catch(e) {
    // Fallback to localStorage
    client = (loadClients()||[]).find(c => c.id === resolvedId);
  }

  // If D1 returned null/empty, try localStorage as fallback
  if (!client || !client.name) {
    const local = (loadClients()||[]).find(c => c.id === resolvedId);
    if (local) client = { ...local, ...(client||{}) };
  }

  if (!client) {
    view.innerHTML = `<div style="padding:32px;text-align:center"><p>Customer not found.</p><button class="rp-btn" onclick="show('clients')">← Clients</button></div>`;
    return;
  }

  // ── Derived stats ─────────────────────────────────────────────────────────
  const addr = [client.street||client.address, client.city, client.state, client.zip].filter(Boolean).join(', ');
  const totalRevenue  = workOrders.filter(w=>w.status==='completed').reduce((s,w)=>s+(Number(w.amount_actual)||Number(w.amount_est)||0),0);
  const totalJobs     = workOrders.length;
  const completedJobs = workOrders.filter(w=>w.status==='completed').length;
  const inProgressJobs= workOrders.filter(w=>w.status==='in-progress').length;
  const scheduledJobs = workOrders.filter(w=>w.status==='scheduled').length;
  const linkedOpps    = (state.opportunities||[]).filter(o =>
    o.clientId === client.id || (o.client||'').toLowerCase() === (client.name||'').toLowerCase()
  );
  const tags = (client.tags||[]);
  // Avatar bg — cycle through a few nice colors based on first char
  const avatarColors = ['#2D7A55','#3b82f6','#8b5cf6','#f59e0b','#ef4444','#06b6d4','#ec4899'];
  const avatarBg = avatarColors[(client.name||'A').charCodeAt(0) % avatarColors.length];

  // ── Helper: build a job row ───────────────────────────────────────────────
  function _cdWoRow(wo) {
    const statusCls = _p6WOStatusClass(wo.status);
    const amt = Number(wo.amount_actual)||Number(wo.amount_est)||0;
    return `<div class="cd-wo-row" onclick="_sbOpenVisitModal('${wo.id}')" style="cursor:pointer" title="Open job ${escapeHtml(wo.wo_number||wo.id)}">
      <span class="cd-wo-num">${escapeHtml(wo.wo_number||wo.id)}</span>
      <span class="cd-wo-title">${escapeHtml(wo.title||wo.type||'Job')}</span>
      <span class="cd-wo-date">${wo.scheduled_date ? _p5FmtDate(wo.scheduled_date) : '—'}</span>
      <span class="ops-ready-badge ${statusCls}" style="font-size:10px">${_p6WOStatusLabel(wo.status)}</span>
      <span class="cd-wo-amt">${amt ? '$'+amt.toFixed(2) : '—'}</span>
    </div>`;
  }
  window._cdWoRow = _cdWoRow; // expose for _cdJobTab

  const woRows = workOrders.slice(0,20).map(_cdWoRow).join('')
    || `<p class="sb-empty-note" style="padding:12px 0">No jobs yet. <button class="stmt-link" onclick="_cdNewJobForClient('${client.id}','${escapeHtml(client.name||'')}')">Schedule first job →</button></p>`;

  const oppRows = linkedOpps.slice(0,6).map(o => `
    <div class="cd-opp-row" onclick="show('pipeline','${o.id}')" style="cursor:pointer">
      <span class="cd-opp-proj">${escapeHtml(o.project||o.serviceLine||'Opportunity')}</span>
      <span class="status-chip ${statusCssClass(o.status||'')}" style="font-size:10px">${escapeHtml(o.status||'New Lead')}</span>
      <span class="cd-opp-val">${o.budget ? '$'+Number(o.budget).toLocaleString() : '—'}</span>
    </div>`).join('') || `<p class="sb-empty-note" style="padding:12px 0">No pipeline opportunities yet.</p>`;

  const notesHtml = customerNotes.map((n,i)=>`
    <div class="cd-note-item" data-note-id="${n.id||i}">
      <div class="cd-note-body">${escapeHtml(n.note||n.body||'')}</div>
      <div class="cd-note-meta">${escapeHtml(n.created_by||'Admin')} · ${n.created_at ? new Date(n.created_at).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}) : ''}</div>
    </div>`).join('') || '';

  // ── Render ────────────────────────────────────────────────────────────────
  view.innerHTML = `
  <div class="cd-shell">

    <!-- ══ Page Header ══ -->
    <div class="cd-page-header">
      <div class="cd-page-header-left">
        <button class="rp-btn cd-back-btn" onclick="show('clients')">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M19 12H5M12 5l-7 7 7 7"/></svg>
          Clients
        </button>
        <div class="cd-title-block" style="display:flex;align-items:center;gap:14px">
          <div class="cd-avatar" style="background:${avatarBg}">${(client.name||'?').charAt(0).toUpperCase()}</div>
          <div>
            <h1 class="cd-name">${escapeHtml(client.name||'Customer')}</h1>
            <div class="cd-sub">
              ${clientTypeBadge(client.type)}
              ${client.status ? `<span style="font-size:11px;color:var(--gw-text-muted)">${escapeHtml(client.status)}</span>` : ''}
              ${client.since||client.created_at ? `<span class="cd-since">Since ${_p5FmtDate(client.since||client.created_at)}</span>` : ''}
            </div>
          </div>
        </div>
      </div>
      <div class="cd-page-header-actions">
        ${client.phone||client.mobile ? `
        <a class="rp-btn" href="tel:${escapeHtml(client.phone||client.mobile||'')}" title="Call ${escapeHtml(client.phone||client.mobile||'')}">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 16.92v3a2 2 0 01-2.18 2 19.79 19.79 0 01-8.63-3.07A19.5 19.5 0 013.07 10.81 19.79 19.79 0 01.01 2.18 2 2 0 012 0h3a2 2 0 012 1.72c.127.96.361 1.903.7 2.81a2 2 0 01-.45 2.11L6.09 7.91a16 16 0 006 6l1.27-1.27a2 2 0 012.11-.45c.907.339 1.85.573 2.81.7A2 2 0 0122 14v2.92z"/></svg>
          Call
        </a>
        <button class="rp-btn" onclick="_cdSendSms('${escapeHtml(client.phone||client.mobile||'')}')">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15a2 2 0 01-2 2H7l-4 4V5a2 2 0 012-2h14a2 2 0 012 2z"/></svg>
          SMS
        </button>` : ''}
        ${client.email ? `
        <button class="rp-btn" onclick="_gwOpenMessageModal({type:'email',to:'${escapeHtml(client.email)}',toName:'${escapeHtml(client.name||'')}'})" title="Email ${escapeHtml(client.email)}">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,12 2,6"/></svg>
          Email
        </button>` : ''}
        <button class="rp-btn" onclick="window.print()">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 6 2 18 2 18 9"/><path d="M6 18H4a2 2 0 01-2-2v-5a2 2 0 012-2h16a2 2 0 012 2v5a2 2 0 01-2 2h-2"/><rect x="6" y="14" width="12" height="8"/></svg>
          Print
        </button>
        <button class="rp-btn" onclick="_cdEditClient('${client.id}')">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
          Edit
        </button>
        <button class="rp-btn" style="color:var(--gw-danger,#dc2626)" onclick="_cdDeleteClient('${client.id}')">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14H6L5 6"/><path d="M10 11v6M14 11v6"/></svg>
          Delete
        </button>
      </div>
    </div>

    <!-- ══ Stats Bar ══ -->
    <div class="cd-stats-bar">
      <div class="cd-stat">
        <span class="cd-stat-val cd-stat-val--green">$${totalRevenue.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</span>
        <span class="cd-stat-lbl">Total Revenue</span>
      </div>
      <div class="cd-stat">
        <span class="cd-stat-val">${totalJobs}</span>
        <span class="cd-stat-lbl">Total Jobs</span>
      </div>
      <div class="cd-stat">
        <span class="cd-stat-val cd-stat-val--blue">${inProgressJobs}</span>
        <span class="cd-stat-lbl">In Progress</span>
      </div>
      <div class="cd-stat">
        <span class="cd-stat-val">${scheduledJobs}</span>
        <span class="cd-stat-lbl">Scheduled</span>
      </div>
      <div class="cd-stat">
        <span class="cd-stat-val cd-stat-val--green">${completedJobs}</span>
        <span class="cd-stat-lbl">Completed</span>
      </div>
      <div class="cd-stat">
        <span class="cd-stat-val">${linkedOpps.length}</span>
        <span class="cd-stat-lbl">Opportunities</span>
      </div>
    </div>

    <!-- ══ Body: Left + Right ══ -->
    <div class="cd-body">

      <!-- ── LEFT COLUMN ── -->
      <div class="cd-left">

        <!-- Contact Info -->
        <section class="cd-section">
          <div class="cd-section-head">
            <h2 class="cd-section-title">Contact Info</h2>
            <button class="rp-btn-sm" onclick="_cdEditClient('${client.id}')">Edit</button>
          </div>
          <div class="cd-info-grid">
            ${client.phone||client.mobile ? `<div class="cd-info-row">
              <span class="cd-info-lbl">Phone</span>
              <a class="cd-info-val cd-link" href="tel:${escapeHtml(client.phone||client.mobile||'')}">${escapeHtml(client.phone||client.mobile||'')}</a>
            </div>` : ''}
            ${client.mobile && client.phone && client.mobile!==client.phone ? `<div class="cd-info-row">
              <span class="cd-info-lbl">Mobile</span>
              <a class="cd-info-val cd-link" href="tel:${escapeHtml(client.mobile)}">${escapeHtml(client.mobile)}</a>
            </div>` : ''}
            ${client.email ? `<div class="cd-info-row">
              <span class="cd-info-lbl">Email</span>
              <button class="cd-info-val cd-link" style="background:none;border:none;padding:0;cursor:pointer;font-size:13px" onclick="_gwOpenMessageModal({type:'email',to:'${escapeHtml(client.email)}',toName:'${escapeHtml(client.name||'')}'})"}>${escapeHtml(client.email)}</button>
            </div>` : ''}
            ${client.email2 ? `<div class="cd-info-row">
              <span class="cd-info-lbl">CC Email</span>
              <button class="cd-info-val cd-link" style="background:none;border:none;padding:0;cursor:pointer;font-size:13px" onclick="_gwOpenMessageModal({type:'email',to:'${escapeHtml(client.email2)}',toName:'${escapeHtml(client.name||'')}'})"}>${escapeHtml(client.email2)}</button>
            </div>` : ''}
            ${addr ? `<div class="cd-info-row">
              <span class="cd-info-lbl">Address</span>
              <a class="cd-info-val cd-link" href="https://maps.google.com/?q=${encodeURIComponent(addr)}" target="_blank" rel="noopener">${escapeHtml(addr)}</a>
            </div>` : ''}
            ${client.type ? `<div class="cd-info-row">
              <span class="cd-info-lbl">Type</span>
              <span class="cd-info-val">${clientTypeBadge(client.type)}</span>
            </div>` : ''}
            ${client.company && client.company!==client.name ? `<div class="cd-info-row">
              <span class="cd-info-lbl">Company</span>
              <span class="cd-info-val">${escapeHtml(client.company)}</span>
            </div>` : ''}
          </div>
          ${tags.length ? `<div class="cd-tags" style="margin-top:12px;display:flex;flex-wrap:wrap;gap:6px">
            ${tags.map(t=>`<span class="cl-tag">${escapeHtml(t)}</span>`).join('')}
            <button class="cd-tag-add-btn" onclick="_cdAddTag('${client.id}')">+ Tag</button>
          </div>` : `<button class="cd-tag-add-btn" style="margin-top:10px" onclick="_cdAddTag('${client.id}')">+ Add Tag</button>`}
        </section>

        <!-- Internal Notes -->
        <section class="cd-section">
          <div class="cd-section-head">
            <h2 class="cd-section-title">
              Customer Notes
              <span style="font-size:10px;font-weight:400;opacity:.6;margin-left:4px">(internal — never shown to client)</span>
            </h2>
          </div>
          <div id="cd-customer-notes" style="display:flex;flex-direction:column;gap:8px;margin-bottom:14px">
            ${notesHtml || '<p class="sb-empty-note">No notes yet. Add context about this customer, preferences, gate codes, etc.</p>'}
          </div>
          <textarea id="cd-note-input" class="rp-input" rows="3"
            placeholder="Gate code, dog on property, preferred schedule, special instructions…"
            style="resize:vertical;margin-bottom:8px"></textarea>
          <button class="rp-btn rp-btn--primary" onclick="_cdSaveNote('${client.id}')">+ Save Note</button>
        </section>

        <!-- Jobs -->
        <section class="cd-section">
          <div class="cd-section-head">
            <h2 class="cd-section-title">Jobs</h2>
            <button class="rp-btn-sm" onclick="_cdNewJobForClient('${client.id}','${escapeHtml(client.name||'')}')">+ Schedule Job</button>
          </div>
          <div class="cd-tab-bar" id="cd-jobs-tabs">
            <button class="cd-tab active" data-filter="all"    onclick="_cdJobTab(this,'all')">All (${totalJobs})</button>
            <button class="cd-tab"         data-filter="scheduled"   onclick="_cdJobTab(this,'scheduled')">Scheduled (${scheduledJobs})</button>
            <button class="cd-tab"         data-filter="in-progress" onclick="_cdJobTab(this,'in-progress')">In Progress (${inProgressJobs})</button>
            <button class="cd-tab"         data-filter="completed"   onclick="_cdJobTab(this,'completed')">Completed (${completedJobs})</button>
          </div>
          <div id="cd-jobs-list">${woRows}</div>
          ${workOrders.length >= 20 ? `
          <div style="text-align:center;padding:10px 0">
            <button class="rp-btn-sm" onclick="_cdLoadMoreJobs('${client.id}')">Load more jobs</button>
          </div>` : ''}
        </section>

        <!-- Pipeline Opportunities -->
        <section class="cd-section">
          <div class="cd-section-head">
            <h2 class="cd-section-title">Pipeline</h2>
            <button class="rp-btn-sm" onclick="show('lead')">+ New Opportunity</button>
          </div>
          ${oppRows}
        </section>

        <!-- Service Properties -->
        <section class="cd-section">
          <div class="cd-section-head">
            <h2 class="cd-section-title">Properties</h2>
            <button class="rp-btn-sm" onclick="showAddProperty('${client.id}')">+ Add Property</button>
          </div>
          ${(client.properties||[]).length ? (client.properties||[]).map(p=>`
            <div class="cd-property-row">
              <div>
                <div style="font-weight:600;font-size:13px">${escapeHtml(p.label||'Property')}</div>
                <div style="font-size:12px;color:var(--gw-text-muted)">${escapeHtml([p.street,p.city,p.state,p.zip].filter(Boolean).join(', '))}</div>
                ${p.notes ? `<div style="font-size:11px;color:var(--gw-text-muted);margin-top:2px">${escapeHtml(p.notes)}</div>` : ''}
              </div>
              <a href="https://maps.google.com/?q=${encodeURIComponent([p.street,p.city,p.state,p.zip].filter(Boolean).join(', '))}"
                 target="_blank" rel="noopener" class="rp-btn-sm" style="font-size:11px">
                 <svg width="10" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7z"/><circle cx="12" cy="9" r="2.5"/></svg>
                 Map
              </a>
            </div>`).join('') : `<p class="sb-empty-note">No additional properties. Primary address is the main service location.</p>`}
        </section>

      </div>

      <!-- ── RIGHT COLUMN ── -->
      <div class="cd-right">

        <!-- Activity Timeline -->
        <section class="cd-section">
          <div class="cd-section-head">
            <h2 class="cd-section-title">Activity Timeline</h2>
          </div>
          <div id="cd-timeline" class="cd-timeline">
            ${workOrders.length ? workOrders.slice(0,10).map(wo=>`
              <div class="cd-timeline-item" onclick="_sbOpenVisitModal('${wo.id}')" style="cursor:pointer" title="Open job ${escapeHtml(wo.wo_number||wo.id)}">
                <div class="cd-tl-dot ${_p6WOStatusClass(wo.status)}"></div>
                <div class="cd-tl-content">
                  <div class="cd-tl-title">${escapeHtml(wo.wo_number||'Job')} — ${escapeHtml(wo.title||wo.type||'Service')}</div>
                  <div class="cd-tl-meta">
                    ${wo.scheduled_date ? _p5FmtDate(wo.scheduled_date) : ''}
                    ${wo.scheduled_date ? ' · ' : ''}
                    <span class="ops-ready-badge ${_p6WOStatusClass(wo.status)}" style="font-size:10px">${_p6WOStatusLabel(wo.status)}</span>
                  </div>
                  ${Number(wo.amount_est)||Number(wo.amount_actual) ? `<div class="cd-tl-amt">$${(Number(wo.amount_actual)||Number(wo.amount_est)||0).toFixed(2)}</div>` : ''}
                </div>
                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="opacity:.3;flex-shrink:0"><path d="M9 18l6-6-6-6"/></svg>
              </div>`).join('')
            : '<p class="sb-empty-note">No activity yet.</p>'}
          </div>
        </section>

        <!-- Quick Actions -->
        <section class="cd-section">
          <div class="cd-section-head">
            <h2 class="cd-section-title">Quick Actions</h2>
          </div>
          <div style="display:flex;flex-direction:column;gap:8px">
            <button class="cd-quick-btn" onclick="_cdNewJobForClient('${client.id}','${escapeHtml(client.name||'')}')">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
              <span>Schedule a Job</span>
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="opacity:.4;margin-left:auto"><path d="M9 18l6-6-6-6"/></svg>
            </button>
            <button class="cd-quick-btn" onclick="show('lead')">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="16"/><line x1="8" y1="12" x2="16" y2="12"/></svg>
              <span>New Opportunity</span>
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="opacity:.4;margin-left:auto"><path d="M9 18l6-6-6-6"/></svg>
            </button>
            ${client.phone||client.mobile ? `
            <button class="cd-quick-btn" onclick="_cdSendSms('${escapeHtml(client.phone||client.mobile||'')}')">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15a2 2 0 01-2 2H7l-4 4V5a2 2 0 012-2h14a2 2 0 012 2z"/></svg>
              <span>Send SMS</span>
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="opacity:.4;margin-left:auto"><path d="M9 18l6-6-6-6"/></svg>
            </button>` : ''}
            ${client.email ? `
            <button class="cd-quick-btn" onclick="_gwOpenMessageModal({type:'email',to:'${escapeHtml(client.email)}',toName:'${escapeHtml(client.name||'')}'})"}>
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,12 2,6"/></svg>
              <span>Send Email</span>
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="opacity:.4;margin-left:auto"><path d="M9 18l6-6-6-6"/></svg>
            </button>` : ''}
            <button class="cd-quick-btn" onclick="_cdSendPortalLink('${client.id}')">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M18 13v6a2 2 0 01-2 2H5a2 2 0 01-2-2V8a2 2 0 012-2h6"/><polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/></svg>
              <span>Send Portal Link</span>
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="opacity:.4;margin-left:auto"><path d="M9 18l6-6-6-6"/></svg>
            </button>
          </div>
        </section>

        <!-- Customer Portal -->
        <section class="cd-section">
          <div class="cd-section-head">
            <h2 class="cd-section-title">Customer Portal</h2>
          </div>
          <p style="font-size:13px;color:var(--gw-text-muted);margin:0 0 14px;line-height:1.5">
            One-click link lets this client view their jobs, photos, invoices, and pay online — all without logging in.
          </p>
          <div id="cd-portal-url-block" style="background:var(--gw-bg-app,#f4f6f8);border:1px solid var(--gw-border);border-radius:8px;padding:10px 14px;font-size:12px;color:var(--gw-text-muted);word-break:break-all;margin-bottom:12px;font-family:monospace">
            ${location.origin}/portal?client=${client.id}
          </div>
          <div style="display:flex;gap:8px">
            <button class="rp-btn rp-btn--primary" style="flex:1" onclick="_cdSendPortalLink('${client.id}')">
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"/><path d="M5 15H4a2 2 0 01-2-2V4a2 2 0 012-2h9a2 2 0 012 2v1"/></svg>
              Copy Link
            </button>
            ${client.phone||client.mobile ? `
            <button class="rp-btn" onclick="_cdSharePortalViaSms('${client.id}','${escapeHtml(client.phone||client.mobile||'')}')">
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15a2 2 0 01-2 2H7l-4 4V5a2 2 0 012-2h14a2 2 0 012 2z"/></svg>
              SMS
            </button>` : ''}
            ${client.email ? `
            <button class="rp-btn" onclick="_gwOpenMessageModal({type:'email',to:'${escapeHtml(client.email)}',toName:'${escapeHtml(client.name||'')}',subject:'Your Customer Portal',body:'Hi ${escapeHtml(client.name||'')},\\n\\nHere is a link to access your customer portal:\\n'+location.origin+'/portal?client=${client.id}'})">
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,12 2,6"/></svg>
              Email
            </button>` : ''}
          </div>
        </section>

      </div>
    </div>
  </div>`;

  // Store current client and work orders for tab/handler access
  window._cdCurrentClient = client;
  window._cdCurrentClientWOs = workOrders;
}
window.customerDetail = customerDetail;

// ══════════════════════════════════════════════════════════════════════════════
// UNIVERSAL IN-APP MESSAGE COMPOSE MODAL
// _gwOpenMessageModal({ type, to, toName, subject, body, clientId })
// type = 'email' | 'sms'
// Never opens mailto: or sms: — always stays inside the app
// ══════════════════════════════════════════════════════════════════════════════
window._gwOpenMessageModal = function(opts = {}) {
  const existing = document.getElementById('gw-message-modal');
  if (existing) existing.remove();

  const type     = opts.type || 'email';
  const toAddr   = opts.to || '';
  const toName   = opts.toName || '';
  const subject  = opts.subject || '';
  const bodyText = opts.body || '';
  const isEmail  = type === 'email';
  const isSms    = type === 'sms';

  // Check if Gmail is connected (for live send) vs log-only
  const googleConnected = (typeof isGoogleConnected === 'function') && isGoogleConnected();
  const fromEmail = (typeof getGoogleUserEmail === 'function') ? getGoogleUserEmail() : '';

  const emailStatusBanner = isEmail ? `
    <div style="padding:8px 12px;border-radius:7px;font-size:12px;display:flex;align-items:center;gap:8px;margin-bottom:12px;
      ${googleConnected
        ? 'background:#2D7A5515;border:1px solid #2D7A5535;color:#2D7A55'
        : 'background:#f5f0e015;border:1px solid #d4a01740;color:#92650a'}">
      <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,12 2,6"/></svg>
      ${googleConnected
        ? `Sending from <strong style="margin-left:4px">${escapeHtml(fromEmail)}</strong> via Gmail`
        : `Gmail not connected — email will be <strong style="margin:0 4px">logged only</strong>.
           <button onclick="show('integrations')" style="background:rgba(146,101,10,.15);border:1px solid rgba(146,101,10,.3);border-radius:5px;padding:1px 8px;font-size:11px;font-weight:700;cursor:pointer;color:inherit">Connect →</button>`}
    </div>` : '';

  const modal = document.createElement('div');
  modal.id = 'gw-message-modal';
  modal.style.cssText = 'position:fixed;inset:0;z-index:10000;display:flex;align-items:flex-end;justify-content:center;background:rgba(0,0,0,.45);backdrop-filter:blur(2px)';
  modal.innerHTML = `
    <div id="gw-message-panel" style="
      width:100%;max-width:600px;
      background:var(--gw-bg-surface,#fff);
      border-radius:18px 18px 0 0;
      box-shadow:0 -8px 40px rgba(0,0,0,.18);
      display:flex;flex-direction:column;
      max-height:90vh;
      animation:gwSlideUp .22s cubic-bezier(.22,1,.36,1)">

      <!-- Header -->
      <div style="display:flex;align-items:center;justify-content:space-between;padding:16px 20px 12px;border-bottom:1px solid var(--gw-border,#e2e8f0);flex-shrink:0">
        <div style="display:flex;align-items:center;gap:10px">
          <!-- Type toggle -->
          <div style="display:flex;gap:2px;background:var(--gw-bg-app,#f4f6f8);border-radius:8px;padding:3px">
            <button id="gwm-tab-email" onclick="_gwMsgTab('email')" style="padding:5px 12px;border-radius:6px;border:none;font-size:12px;font-weight:700;cursor:pointer;transition:all .15s;
              ${isEmail ? 'background:#fff;color:var(--gw-pine-500,#2D7A55);box-shadow:0 1px 4px rgba(0,0,0,.1)' : 'background:transparent;color:var(--gw-text-muted,#64748b)'}">
              ${gwIcon('email',13)} Email
            </button>
            <button id="gwm-tab-sms" onclick="_gwMsgTab('sms')" style="padding:5px 12px;border-radius:6px;border:none;font-size:12px;font-weight:700;cursor:pointer;transition:all .15s;
              ${isSms ? 'background:#fff;color:var(--gw-pine-500,#2D7A55);box-shadow:0 1px 4px rgba(0,0,0,.1)' : 'background:transparent;color:var(--gw-text-muted,#64748b)'}">
              ${gwIcon('message',13)} SMS
            </button>
          </div>
          <span id="gwm-type-label" style="font-size:14px;font-weight:700;color:var(--gw-text,#1e293b)">
            ${isEmail ? 'New Email' : 'New SMS'}
          </span>
        </div>
        <button onclick="document.getElementById('gw-message-modal')?.remove()" style="background:none;border:none;font-size:20px;color:var(--gw-text-muted,#64748b);cursor:pointer;line-height:1;padding:4px 8px">×</button>
      </div>

      <!-- Body -->
      <div style="flex:1;overflow-y:auto;padding:16px 20px;display:flex;flex-direction:column;gap:10px">
        ${emailStatusBanner}

        <!-- To field -->
        <div>
          <label style="font-size:11px;font-weight:700;color:var(--gw-text-muted,#64748b);text-transform:uppercase;letter-spacing:.04em;display:block;margin-bottom:4px">
            ${isEmail ? 'To' : 'Phone Number'}
          </label>
          <input id="gwm-to" class="rp-input" type="${isEmail ? 'email' : 'tel'}"
            placeholder="${isEmail ? 'email@example.com' : '+1 (555) 000-0000'}"
            value="${escapeHtml(toAddr)}" style="width:100%">
        </div>

        <!-- Name (display only) -->
        ${toName ? `<div style="font-size:12px;color:var(--gw-text-muted,#64748b);margin-top:-6px">To: <strong>${escapeHtml(toName)}</strong></div>` : ''}

        <!-- Subject (email only) -->
        <div id="gwm-subject-row" style="${isEmail ? '' : 'display:none'}">
          <label style="font-size:11px;font-weight:700;color:var(--gw-text-muted,#64748b);text-transform:uppercase;letter-spacing:.04em;display:block;margin-bottom:4px">Subject</label>
          <input id="gwm-subject" class="rp-input" type="text" placeholder="Subject line…" value="${escapeHtml(subject)}" style="width:100%">
        </div>

        <!-- Message body -->
        <div style="flex:1">
          <label style="font-size:11px;font-weight:700;color:var(--gw-text-muted,#64748b);text-transform:uppercase;letter-spacing:.04em;display:block;margin-bottom:4px">Message</label>
          <textarea id="gwm-body" class="rp-input" rows="7"
            placeholder="${isEmail ? 'Write your email…' : 'Type your SMS message (max 160 chars per segment)…'}"
            style="width:100%;resize:vertical;min-height:120px">${escapeHtml(bodyText)}</textarea>
          <div id="gwm-sms-counter" style="${isSms ? 'text-align:right;font-size:11px;color:var(--gw-text-muted,#64748b);margin-top:3px' : 'display:none'}"></div>
        </div>

        <!-- SMS note -->
        <div id="gwm-sms-note" style="${isSms ? 'font-size:12px;color:var(--gw-text-muted,#64748b);background:var(--gw-bg-app,#f4f6f8);border-radius:7px;padding:8px 12px' : 'display:none'}">
          <strong>SMS will be logged</strong> in this customer's Communications tab. Sending via carrier requires a Twilio integration (Admin → Integrations).
        </div>
      </div>

      <!-- Footer -->
      <div style="padding:14px 20px;border-top:1px solid var(--gw-border,#e2e8f0);display:flex;justify-content:space-between;align-items:center;flex-shrink:0;gap:10px">
        <div style="font-size:12px;color:var(--gw-text-muted,#64748b)" id="gwm-status"></div>
        <div style="display:flex;gap:8px">
          <button class="rp-btn" onclick="document.getElementById('gw-message-modal')?.remove()">Cancel</button>
          <button class="rp-btn rp-btn--primary" id="gwm-send-btn" onclick="_gwMsgSend()">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg>
            ${isEmail ? (googleConnected ? 'Send Email' : 'Log Email') : 'Log SMS'}
          </button>
        </div>
      </div>
    </div>`;

  document.body.appendChild(modal);

  // SMS character counter
  const bodyEl = document.getElementById('gwm-body');
  const counter = document.getElementById('gwm-sms-counter');
  if (bodyEl && counter) {
    const updateCounter = () => {
      const len = bodyEl.value.length;
      const segs = Math.ceil(len / 160) || 1;
      counter.textContent = `${len} chars · ${segs} segment${segs>1?'s':''}`;
    };
    bodyEl.addEventListener('input', updateCounter);
    updateCounter();
  }

  // Close on backdrop click
  modal.addEventListener('click', e => { if (e.target === modal) modal.remove(); });

  // Store current type
  window._gwMsgCurrentType = type;
};

// Tab switcher
window._gwMsgTab = function(newType) {
  window._gwMsgCurrentType = newType;
  const isEmail = newType === 'email';
  const googleConnected = (typeof isGoogleConnected === 'function') && isGoogleConnected();

  // Update tab buttons
  const eTab = document.getElementById('gwm-tab-email');
  const sTab = document.getElementById('gwm-tab-sms');
  const activeStyle = 'background:#fff;color:var(--gw-pine-500,#2D7A55);box-shadow:0 1px 4px rgba(0,0,0,.1)';
  const inactiveStyle = 'background:transparent;color:var(--gw-text-muted,#64748b)';
  if (eTab) eTab.style.cssText = eTab.style.cssText.replace(/background:[^;]+;color:[^;]+;box-shadow:[^;]+|background:[^;]+;color:[^;]+/, isEmail ? activeStyle : inactiveStyle);
  if (sTab) sTab.style.cssText = sTab.style.cssText.replace(/background:[^;]+;color:[^;]+;box-shadow:[^;]+|background:[^;]+;color:[^;]+/, !isEmail ? activeStyle : inactiveStyle);

  // Toggle UI
  const subjectRow = document.getElementById('gwm-subject-row');
  const smsNote    = document.getElementById('gwm-sms-note');
  const smsCounter = document.getElementById('gwm-sms-counter');
  const toInput    = document.getElementById('gwm-to');
  const bodyEl     = document.getElementById('gwm-body');
  const sendBtn    = document.getElementById('gwm-send-btn');
  const label      = document.getElementById('gwm-type-label');

  if (subjectRow) subjectRow.style.display = isEmail ? '' : 'none';
  if (smsNote)    smsNote.style.display    = isEmail ? 'none' : '';
  if (smsCounter) smsCounter.style.display = isEmail ? 'none' : 'block';
  if (toInput)    toInput.type             = isEmail ? 'email' : 'tel';
  if (toInput)    toInput.placeholder      = isEmail ? 'email@example.com' : '+1 (555) 000-0000';
  if (bodyEl)     bodyEl.placeholder       = isEmail ? 'Write your email…' : 'Type your SMS message…';
  if (label)      label.textContent        = isEmail ? 'New Email' : 'New SMS';
  if (sendBtn)    sendBtn.innerHTML        = `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg> ${isEmail ? (googleConnected ? 'Send Email' : 'Log Email') : 'Log SMS'}`;
};

// Send/log handler
window._gwMsgSend = async function() {
  const type    = window._gwMsgCurrentType || 'email';
  const to      = document.getElementById('gwm-to')?.value?.trim() || '';
  const subject = document.getElementById('gwm-subject')?.value?.trim() || '';
  const body    = document.getElementById('gwm-body')?.value?.trim() || '';
  const status  = document.getElementById('gwm-status');
  const sendBtn = document.getElementById('gwm-send-btn');
  const isEmail = type === 'email';

  if (!to) { showToast(isEmail ? 'Enter an email address' : 'Enter a phone number', 'error'); return; }
  if (!body) { showToast('Message body is required', 'error'); return; }

  if (sendBtn) { sendBtn.disabled = true; sendBtn.innerHTML = `${gwIcon('send',13)} Sending…`; }
  if (status)  status.textContent = '';

  try {
    if (isEmail) {
      const googleConnected = (typeof isGoogleConnected === 'function') && isGoogleConnected();
      if (googleConnected) {
        if (!subject) { showToast('Add a subject line before sending', 'error'); if(sendBtn){sendBtn.disabled=false;sendBtn.innerHTML='Send Email';} return; }
        const htmlBody = body.replace(/\n/g, '<br>');
        if (typeof gmailSendEmail === 'function') {
          await gmailSendEmail({ to, subject, body: htmlBody });
        }
        showToast('Email sent via Gmail', 'success');
      } else {
        showToast('Email logged (connect Gmail in Integrations to send live)', 'info');
      }
      // Log to comms state
      if (!state.communications) state.communications = [];
      state.communications.push({ id: uid('comm'), type:'email', direction:'out', to, subject, body, ts: new Date().toISOString(), sentBy: (window.getCurrentRep?.()?.name || 'Rep'), gmailSent: googleConnected });
      saveState();
    } else {
      // SMS — log it (live send requires Twilio integration)
      showToast('SMS logged in Communications', 'info');
      if (!state.communications) state.communications = [];
      state.communications.push({ id: uid('comm'), type:'sms', direction:'out', to, body, ts: new Date().toISOString(), sentBy: (window.getCurrentRep?.()?.name || 'Rep') });
      saveState();
    }
    document.getElementById('gw-message-modal')?.remove();
  } catch(e) {
    showToast('Failed: ' + (e.message || 'Unknown error'), 'error');
    if (sendBtn) { sendBtn.disabled = false; sendBtn.innerHTML = isEmail ? 'Send Email' : 'Log SMS'; }
  }
};

// ── Customer Detail handlers ──────────────────────────────────────────────────
window._cdJobTab = function(btn, filter) {
  document.querySelectorAll('#cd-jobs-tabs .cd-tab').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  const wos = window._cdCurrentClientWOs || [];
  const filtered = filter==='all' ? wos : wos.filter(w=>w.status===filter);
  const rowFn = window._cdWoRow || function(wo) {
    const statusCls = _p6WOStatusClass(wo.status);
    const amt = Number(wo.amount_actual)||Number(wo.amount_est)||0;
    return `<div class="cd-wo-row" onclick="_sbOpenVisitModal('${wo.id}')" style="cursor:pointer">
      <span class="cd-wo-num">${escapeHtml(wo.wo_number||wo.id)}</span>
      <span class="cd-wo-title">${escapeHtml(wo.title||wo.type||'Job')}</span>
      <span class="cd-wo-date">${wo.scheduled_date ? _p5FmtDate(wo.scheduled_date) : '—'}</span>
      <span class="ops-ready-badge ${statusCls}" style="font-size:10px">${_p6WOStatusLabel(wo.status)}</span>
      <span class="cd-wo-amt">${amt ? '$'+amt.toFixed(2) : '—'}</span>
    </div>`;
  };
  const rows = filtered.slice(0,20).map(rowFn).join('')
    || '<p class="sb-empty-note" style="padding:12px 0">No jobs in this category.</p>';
  const list = document.getElementById('cd-jobs-list');
  if (list) list.innerHTML = rows;
};

// Open new visit modal pre-filled with client info
window._cdNewJobForClient = function(clientId, clientName) {
  _sbOpenNewVisit(null, null, clientId, clientName);
};

// Share portal link via SMS
window._cdSharePortalViaSms = function(clientId, phone) {
  const link = `${location.origin}/portal?client=${clientId}`;
  const msg = `Hi! Here's a link to your customer portal where you can view your jobs, photos, and invoices: ${link}`;
  _gwOpenMessageModal({ type:'sms', to: phone, body: msg });
};

// Load more jobs (fetches from D1 with offset)
window._cdLoadMoreJobs = async function(clientId) {
  const existing = window._cdCurrentClientWOs || [];
  const offset = existing.length;
  try {
    const r = await fetch(`/api/work-orders?client_id=${clientId}&limit=50&offset=${offset}`, { credentials:'include' });
    const d = await r.json();
    const more = d.data || [];
    if (!more.length) { showToast('No more jobs to load','info'); return; }
    window._cdCurrentClientWOs = [...existing, ...more];
    // Re-render the active tab
    const activeTab = document.querySelector('#cd-jobs-tabs .cd-tab.active');
    if (activeTab) window._cdJobTab(activeTab, activeTab.dataset.filter || 'all');
  } catch(e) { showToast('Failed to load more jobs','error'); }
};

window._cdSaveNote = async function(clientId) {
  const inp = document.getElementById('cd-note-input');
  const note = inp?.value?.trim();
  if (!note) { showToast('Please enter a note','error'); return; }
  try {
    const r = await fetch(`/api/customers/${clientId}/notes`, {
      method:'POST', credentials:'include',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify({ note })
    });
    const d = await r.json();
    if (!d.ok) throw new Error(d.error);
    const container = document.getElementById('cd-customer-notes');
    const empty = container?.querySelector('.sb-empty-note');
    if (empty) empty.remove();
    const item = document.createElement('div');
    item.className = 'cd-note-item';
    item.innerHTML = `<div class="cd-note-body">${escapeHtml(note)}</div>
      <div class="cd-note-meta">Just now</div>`;
    container?.appendChild(item);
    if (inp) inp.value = '';
    showToast('Note saved','success');
  } catch(e) {
    showToast('Failed to save note','error');
  }
};

window._cdEditClient = function(clientId) {
  showClientForm(clientId);
};

window._cdDeleteClient = async function(clientId) {
  if (!confirm('Delete this customer? This cannot be undone.')) return;
  try {
    await fetch(`/api/clients/${clientId}`,{method:'DELETE',credentials:'include'});
    showToast('Customer deleted','success');
    show('clients');
  } catch(e) { showToast('Failed to delete','error'); }
};

window._cdAddTag = function(clientId) {
  const tag = prompt('Enter tag:');
  if (!tag?.trim()) return;
  const c = window._cdCurrentClient;
  if (!c) return;
  c.tags = c.tags || [];
  if (!c.tags.includes(tag.trim())) c.tags.push(tag.trim());
  fetch(`/api/clients/${clientId}`,{method:'PUT',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({tags:c.tags})})
    .then(()=>showToast('Tag added','success'));
  const container = document.querySelector('.cd-tags') || document.querySelector('.cd-tag-add-btn')?.parentElement;
  const addBtn = container?.querySelector('.cd-tag-add-btn');
  if (container && addBtn) {
    const span = document.createElement('span');
    span.className = 'cl-tag';
    span.textContent = tag.trim();
    container.insertBefore(span, addBtn);
  }
};

window._cdSendSms = function(phone, prefillBody) {
  if (!phone) { showToast('No phone number on file','error'); return; }
  _gwOpenMessageModal({ type:'sms', to: phone, body: prefillBody||'' });
};

window._cdSendPortalLink = function(clientId) {
  const link = `${location.origin}/portal?client=${clientId}`;
  navigator.clipboard?.writeText(link)
    .then(()=>showToast('Portal link copied to clipboard','success'))
    .catch(()=>showToast('Portal link: '+link,'info'));
};

// ── Add property modal ──────────────────────────────────────────────────────
window.showAddProperty = function(clientId) {
  const existing = document.getElementById('addPropertyModal');
  if (existing) existing.remove();
  const modal = document.createElement('div');
  modal.id = 'addPropertyModal';
  modal.className = 'cl-modal-overlay';
  modal.innerHTML = `
    <div class="cl-modal" style="max-width:480px">
      <div class="cl-modal-header">
        <h3>Add Service Property</h3>
        <button class="cl-modal-close" onclick="document.getElementById('addPropertyModal').remove()">&times;</button>
      </div>
      <div class="cl-modal-body">
        <div class="cl-form-grid">
          <label class="cl-form-label full"><span>Label</span>
            <input id="prop-label" class="cl-input" placeholder="e.g. Main Residence, Rental Property, Back Lot">
          </label>
          <label class="cl-form-label full"><span>Street</span>
            <input id="prop-street" class="cl-input" placeholder="123 Service Rd">
          </label>
          <label class="cl-form-label"><span>City</span>
            <input id="prop-city" class="cl-input" placeholder="Vienna">
          </label>
          <label class="cl-form-label" style="display:grid;grid-template-columns:80px 1fr;gap:8px">
            <div><span>State</span><input id="prop-state" class="cl-input" value="VA" maxlength="2"></div>
            <div><span>Zip</span><input id="prop-zip" class="cl-input" placeholder="22180"></div>
          </label>
          <label class="cl-form-label full"><span>Notes</span>
            <textarea id="prop-notes" class="cl-input" rows="2" placeholder="Gate code, access notes, service area…"></textarea>
          </label>
        </div>
      </div>
      <div class="cl-modal-footer">
        <button class="secondary-btn small" onclick="document.getElementById('addPropertyModal').remove()">Cancel</button>
        <button class="primary-btn small" onclick="saveProperty('${clientId}')">Add Property</button>
      </div>
    </div>
  `;
  document.body.appendChild(modal);
  document.getElementById('prop-label').focus();
};

window.saveProperty = function(clientId) {
  const val = id => (document.getElementById(id)?.value||'').trim();
  const list = loadClients();
  const c = list.find(x => x.id === clientId);
  if (!c) return;
  c.properties = c.properties || [];
  c.properties.push({
    id: propId(),
    label: val('prop-label') || 'Property',
    street: val('prop-street'), street2: '',
    city: val('prop-city'), state: val('prop-state'), zip: val('prop-zip'),
    notes: val('prop-notes')
  });
  c.updatedAt = new Date().toISOString();
  saveClients(list);
  document.getElementById('addPropertyModal')?.remove();
  showToast('Property added');
  show('clients', clientId);
};

window.deleteProperty = function(clientId, propIdToDelete) {
  if (!confirm('Remove this property?')) return;
  const list = loadClients();
  const c = list.find(x => x.id === clientId);
  if (!c) return;
  c.properties = (c.properties||[]).filter(p => p.id !== propIdToDelete);
  c.updatedAt = new Date().toISOString();
  saveClients(list);
  showToast('Property removed');
  show('clients', clientId);
};

