            + '<input type="hidden" name="clientIsNew" id="lf-client-is-new" value="1">'
          + '</div>'
          + '<label class="lf-field">'
            + '<span class="lf-label">Phone</span>'
            + '<input name="phone" id="lf-phone" type="tel" class="lf-input" placeholder="(555) 000-0000">'
          + '</label>'
