window.superAdmin = superAdmin;

// ── Platform-owner vs tenant post-login routing ───────────────────────────────
// On every page load, determine session identity and route to the correct view.
// IMPORTANT: We await window._d1BootstrapReady before calling show() so that
// the bootstrapD1Auth() in the inline <script> has already:
//   - verified the session cookie
//   - called /api/auth/bootstrap (hydrated REPS, _gwRoles, _gwNavPerms, _gwPipelineStages)
//   - updated the sidebar footer with the real user's name/role
// This eliminates the race condition where show('today') fires before getCurrentRep()
// returns a valid rep, causing canViewTab() to return false and show "Access Restricted".
(async function _initialRoute() {
  // Wait for bootstrapD1Auth() to finish (max 8s safety timeout)
  if (window._d1BootstrapReady) {
    try {
      await Promise.race([
        window._d1BootstrapReady,
        new Promise(r => setTimeout(() => r({ authed: false, timeout: true }), 8000))
      ]);
    } catch(e) { /* ignore — proceed anyway */ }
  }

  // After bootstrap, d1Rep is already in window._d1SessionRep
  const d1Rep = window._d1SessionRep;

  const isPlatformAdmin = d1Rep &&
    (d1Rep.is_super_admin === 1 || d1Rep.is_super_admin === true) &&
    d1Rep.company_id === 'groundwork_platform';

  if (isPlatformAdmin) {
    // ── Platform Admin mode ──────────────────────────────────────────────────
    const platformNav = document.getElementById('platformAdminNav');
    if (platformNav) platformNav.style.display = '';
    document.querySelectorAll('.tenant-nav').forEach(el => {
      el.style.display = 'none';
    });
    const brandSubtitle = document.querySelector('.brand-subtitle');
    if (brandSubtitle) brandSubtitle.textContent = 'Platform Admin';
    // Update sidebar footer for platform admin
    try {
      const footer = document.querySelector('.sidebar-footer');
      if (footer) {
        const logoutAction = `fetch('/api/auth/logout',{method:'POST'}).finally(()=>{window.location.href='/'});`;
        footer.innerHTML = `
          <div style="width:32px;height:32px;border-radius:50%;background:rgba(77,138,134,.45);border:1px solid rgba(77,138,134,.6);color:#fff;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:800;flex-shrink:0;cursor:pointer;letter-spacing:-.01em" onclick="${logoutAction}" title="Sign out">TG</div>
          <div style="min-width:0;flex:1">
            <strong style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;display:block;font-size:13px;color:#ffffff">Tyler Johnson</strong>
            <span style="font-size:11px;color:rgba(255,255,255,.50)">Platform Owner</span>
          </div>`;
      }
    } catch(e) {}
    show('superAdmin');
  } else if (d1Rep) {
    // ── Standard authenticated tenant flow ───────────────────────────────────
    // Bootstrap complete: REPS hydrated, _gwNavPerms set, getCurrentRep() works.
    if (typeof window._refreshAdminNav === 'function') window._refreshAdminNav();
    // Tailor the +New dropdown to the logged-in user's role
    if (typeof window._gwBuildNewMenu === 'function') window._gwBuildNewMenu();
    // Field roles (foreman, laborer) land on fieldDashboard on ALL screen sizes
    if (typeof window._gwShouldStartFieldMode === 'function' && window._gwShouldStartFieldMode()) {
      show('fieldDashboard');
    } else {
      // ── Onboarding check: admin only, runs once on first login ────────────
      // gwCheckOnboarding() fetches /api/company/branding and shows wizard
      // if onboarding_completed===0. It resolves immediately for non-admins
      // or returning users, adding no perceptible delay.
      if (d1Rep.role === 'admin' && typeof window.gwCheckOnboarding === 'function') {
        try { await window.gwCheckOnboarding(); } catch(e) { /* non-blocking */ }
      }
      // ── Notification bell: init for all authenticated users ───────────────
      if (typeof window.gwNotifInit === 'function') {
        try { window.gwNotifInit(); } catch(e) { /* non-blocking */ }
      }
      // ── Hash-based restore: reload stays on the same page ──────────────────
      const _hashView = (location.hash || '').replace(/^#/, '').trim();
      // Only restore if hash looks like a valid view name and user has access
      const _hashValid = _hashView && /^[a-zA-Z][a-zA-Z0-9_]+$/.test(_hashView)
        && typeof canViewTab === 'function' && canViewTab(_hashView);
      // ── Flush any queued mobile nav tap that arrived before bootstrap ────────
      // If the user tapped a bottom-nav button before _d1SessionRep was set,
      // _gwPendingMobileNav captured it. Honour that intent now (overrides hash).
      const _pendingNav = window._gwPendingMobileNav;
      window._gwPendingMobileNav = null;
      if (_pendingNav && typeof canViewTab === 'function' && canViewTab(_pendingNav.viewName)) {
        show(_pendingNav.viewName, _pendingNav.param);
      } else {
        show(_hashValid ? _hashView : 'gwDashboard');
      }
    }
  } else {
    // ── No session (unauthenticated) — show login screen ────────────────────
    if (typeof window.renderLoginScreen === 'function') {
      window.renderLoginScreen();
    }
  }
})();

// ══════════════════════════════════════════════════════════════════════════════
//  CALL COMPANION  — floating overlay while on a call
//  Opens a non-blocking, draggable side panel with:
//    • Stage guide questions & checklist for the lead's current stage
//    • All 6 process steps quick-reference
//    • Live transcript recorder with AI-assisted next-steps summary
// ══════════════════════════════════════════════════════════════════════════════
window.openCallCompanion = function(oppId) {
  const o = (state && state.opportunities || []).find(x => x.id === oppId);
  if (!o) { console.warn('[CallCompanion] Opportunity not found:', oppId); return; }

  // Remove any existing companion
  document.getElementById('gw-call-companion')?.remove();

  const currentStageNum = Math.max(1, (window.getPipelineStages ? window.getPipelineStages() : []).indexOf(o.status) + 1);
  const stagesData   = (window.AVALON_DATA && window.AVALON_DATA.stages) || [];
  const checklists   = (window.AVALON_DATA && window.AVALON_DATA.checklists) || [];
  const sp           = (window.AVALON_DATA && window.AVALON_DATA.salesProcess) || {};
  const steps        = sp.steps || [];
  const stepColors   = ['#1A4740','#2D7A55','#8B6914','#8B3A2A','#B8744F','#4D8A86'];
  const maxStage     = stagesData.length ? Math.max(...stagesData.map(s=>s.id)) : 1;

  // ── Size presets (S / M / L) + custom drag-resize ──────────────────────────
  const CC_SIZES = { S:{w:340,h:320}, M:{w:440,h:460}, L:{w:580,h:600} };
  let ccSize   = localStorage.getItem('gw-cc-size') || 'M';
  if (!CC_SIZES[ccSize]) ccSize = 'M';
  let ccCustom = null; // {w,h} once user drag-resizes
  try { const c = JSON.parse(localStorage.getItem('gw-cc-custom-size')||'null'); if (c && c.w) ccCustom = c; } catch(e){}

  // ── Which stage is currently displayed in the Stage Guide tab ─────────────
  let ccStageView = currentStageNum;

  // ── Build stage guide content for any stage number ─────────────────────────
  function ccStageBody(n) {
    const sd = stagesData.find(s => s.id === n) || {};
    const cl = checklists.find(c => c.stage === n);

    const qHtml = (sd.questions || []).length
      ? sd.questions.map(q => `<div class="gw-cc-q">${escapeHtml(q)}</div>`).join('')
      : '<div class="gw-cc-empty">No discovery questions for this stage.</div>';

    const clPrefix = `cc-cl-${n}-${oppId}`;
    let clHtml = '<div class="gw-cc-empty">No checklist for this stage.</div>';
    if (cl) {
      const done = cl.items.filter((_, i) => localStorage.getItem(`${clPrefix}-${i}`) === '1').length;
      const pct  = cl.items.length ? Math.round(done / cl.items.length * 100) : 0;
      clHtml = `
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px">
          <div class="gw-cc-section-label" style="margin:0">${escapeHtml(cl.title)}</div>
          <span id="gw-cc-cl-count" style="font-size:10.5px;font-weight:800;color:#2D7A55">${done}/${cl.items.length}</span>
        </div>
        <div style="height:4px;background:#E8E4DC;border-radius:99px;margin-bottom:10px;overflow:hidden">
          <div id="gw-cc-cl-bar" style="height:100%;width:${pct}%;background:#2D7A55;border-radius:99px;transition:width .25s"></div>
        </div>
        ${cl.items.map((item, i) => {
          const key = `${clPrefix}-${i}`;
          const checked = localStorage.getItem(key) === '1';
          return `<label class="gw-cc-check-row${checked?' gw-cc-check-done':''}">
            <input type="checkbox" data-key="${key}" data-total="${cl.items.length}" data-prefix="${clPrefix}" ${checked?'checked':''} onchange="(function(el){
              localStorage.setItem(el.dataset.key, el.checked?'1':'0');
              el.closest('label').classList.toggle('gw-cc-check-done', el.checked);
              var total = Number(el.dataset.total)||0, done = 0;
              for (var i=0;i<total;i++) if (localStorage.getItem(el.dataset.prefix+'-'+i)==='1') done++;
              var cnt=document.getElementById('gw-cc-cl-count'); if(cnt) cnt.textContent = done+'/'+total;
              var bar=document.getElementById('gw-cc-cl-bar'); if(bar) bar.style.width = (total?Math.round(done/total*100):0)+'%';
            })(this)">
            <span>${escapeHtml(item)}</span>
          </label>`;
        }).join('')}`;
    }

    const rfHtml = (sd.redFlags || []).length
      ? `<div style="margin-top:14px"><div class="gw-cc-section-label" style="color:#C97B6A">Red Flags to Watch</div>
          ${sd.redFlags.map(f => `<div class="gw-cc-rf">${escapeHtml(f)}</div>`).join('')}</div>`
      : '';

    const isCurrent = n === currentStageNum;
    return `
      <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:8px">
        <span style="font-size:11px;font-weight:800;color:#2D7A55;text-transform:uppercase;letter-spacing:.06em">Stage ${n}: ${escapeHtml(sd.title || '')}</span>
        ${isCurrent
          ? '<span style="font-size:9px;font-weight:800;color:#fff;background:#2D7A55;border-radius:99px;padding:2px 8px;text-transform:uppercase;letter-spacing:.05em">Current</span>'
          : `<button type="button" onclick="gwCCStageGo(${currentStageNum})" style="font-size:9px;font-weight:800;color:#8B6914;background:#8B691415;border:1px solid #8B691430;border-radius:99px;padding:2px 8px;cursor:pointer;text-transform:uppercase;letter-spacing:.05em">Viewing other stage — back to current</button>`}
      </div>
      <div style="font-size:11px;color:#5E6E6F;margin-bottom:12px;line-height:1.55">${escapeHtml(sd.purpose || '')}</div>
      <div class="gw-cc-section-label">Discovery Questions</div>
      ${qHtml}
      ${rfHtml}
      <div style="margin-top:14px">${clHtml}</div>`;
  }

  // ── Steps tab ───────────────────────────────────────────────────────────────
  const stepsHtml = steps.map((s, i) => `
    <div class="gw-cc-step" style="border-left:3px solid ${stepColors[i]||'#4D8A86'}">
      <div style="font-size:10px;font-weight:800;color:${stepColors[i]||'#4D8A86'};text-transform:uppercase;letter-spacing:.05em">Step ${s.num}</div>
      <div style="font-size:12px;font-weight:700;color:var(--gds-ink,#1F2A2B);margin:2px 0">${escapeHtml(s.title)}</div>
      <div style="font-size:11px;color:var(--gw-muted,#5E6E6F)">${escapeHtml(s.tagline||'')}</div>
      ${(s.cbrQuestions||[]).slice(0,3).map(q=>`<div class="gw-cc-q" style="margin-top:4px;font-size:11px">${escapeHtml(q)}</div>`).join('')}
    </div>`).join('');

  // ── Post-call output generators ─────────────────────────────────────────────
  const CC_GENS = [
    { id:'summary_email', label:'Summary + Next Steps Email',            desc:'Client-ready recap email with clear next steps' },
    { id:'full_package',  label:'Summary + SOW + Budget + Next Steps',   desc:'Full follow-up: recap, scope of work, X–Y budget range, next steps' },
    { id:'sow_budget',    label:'SOW + X–Y Budget Only',                 desc:'Scope of work with a working budget range — no email wrapper' },
    { id:'client_recap',  label:'Client Thank-You Recap',                desc:'Short, warm thank-you email confirming what you heard' },
    { id:'handoff_note',  label:'Internal Handoff Note',                 desc:'Structured note for your team / production handoff' },
  ];
  const genBtnsHtml = CC_GENS.map(g => `
    <button type="button" class="gw-cc-gen-btn" onclick="gwCCGenerate('${oppId}','${g.id}')" title="${escapeHtml(g.desc)}">
      <span style="font-weight:700">${escapeHtml(g.label)}</span>
      <span style="font-size:10px;color:#7C8A85;font-weight:500;display:block;margin-top:1px">${escapeHtml(g.desc)}</span>
    </button>`).join('');

  const panel = document.createElement('div');
  panel.id = 'gw-call-companion';
  panel.innerHTML = `
    <div id="gw-cc-drag-handle" style="display:flex;align-items:center;justify-content:space-between;padding:12px 14px;background:linear-gradient(135deg,#0f2d1f,#1a3a2a);border-radius:14px 14px 0 0;cursor:grab;user-select:none">
      <div style="display:flex;align-items:center;gap:8px;min-width:0">
        <div style="width:8px;height:8px;border-radius:50%;background:#4ade80;box-shadow:0 0 6px #4ade80;animation:gw-cc-pulse 1.5s infinite;flex-shrink:0"></div>
        <span style="font-size:12px;font-weight:800;color:#fff;letter-spacing:.02em;white-space:nowrap">Call Companion</span>
        <span style="font-size:10px;color:#4ade8090;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escapeHtml(o.client||'Lead')}</span>
      </div>
      <div style="display:flex;align-items:center;gap:5px;flex-shrink:0">
        <div style="display:flex;gap:2px;background:#ffffff12;border-radius:7px;padding:2px" title="Panel size">
          ${['S','M','L'].map(sz => `<button type="button" id="gw-cc-size-${sz}" onclick="gwCCSetSize('${sz}')"
            style="background:${sz===ccSize?'#ffffff28':'transparent'};border:none;color:#fff;border-radius:5px;width:20px;height:18px;cursor:pointer;font-size:9px;font-weight:800;line-height:1">${sz}</button>`).join('')}
        </div>
        <button type="button" id="gw-cc-min-btn" onclick="gwCCMinToggle()" title="Minimise / restore"
          style="background:#ffffff18;border:none;color:#fff;border-radius:6px;width:22px;height:22px;cursor:pointer;font-size:12px;display:flex;align-items:center;justify-content:center">&#8212;</button>
        <button type="button" onclick="document.getElementById('gw-call-companion').remove()" title="Close"
          style="background:#f8717130;border:none;color:#f87171;border-radius:6px;width:22px;height:22px;cursor:pointer;font-size:13px;display:flex;align-items:center;justify-content:center">&times;</button>
      </div>
    </div>

    <div id="gw-cc-body">
      <!-- Tab bar -->
      <div style="display:flex;border-bottom:1px solid #E0DDD5;background:#fff">
        ${['stage','steps','transcript'].map((t,i)=>`
          <button type="button" id="gw-cc-tab-${t}" onclick="gwCCTab('${t}')"
            style="flex:1;padding:9px 4px;font-size:11px;font-weight:700;border:none;cursor:pointer;border-bottom:2px solid ${i===0?'#2D7A55':'transparent'};color:${i===0?'#2D7A55':'#5E6E6F'};background:transparent;transition:all .15s">
            ${t==='stage'?'Stage Guide':t==='steps'?'All Steps':'Transcript'}
          </button>`).join('')}
      </div>

      <!-- Tab: Stage Guide -->
      <div id="gw-cc-panel-stage" class="gw-cc-scroll" style="padding:12px">
        <div style="display:flex;align-items:center;gap:6px;margin-bottom:10px">
          <button type="button" class="gw-cc-nav-btn" id="gw-cc-stage-prev">&#9664;</button>
          <select id="gw-cc-stage-select" onchange="gwCCStageGo(Number(this.value))"
            style="flex:1;padding:6px 8px;border:1px solid #E0DDD5;border-radius:8px;font-size:11.5px;font-weight:700;color:#1F2A2B;background:#FAFAF8;cursor:pointer">
            ${stagesData.map(s => `<option value="${s.id}">Stage ${s.id} — ${escapeHtml(s.title||'')}${s.id===currentStageNum?' (current)':''}</option>`).join('')}
          </select>
          <button type="button" class="gw-cc-nav-btn" id="gw-cc-stage-next">&#9654;</button>
        </div>
        <div id="gw-cc-stage-body"></div>
      </div>

      <!-- Tab: All Steps -->
      <div id="gw-cc-panel-steps" class="gw-cc-scroll" style="display:none;padding:12px">
        ${stepsHtml || '<div class="gw-cc-empty">No process steps found.</div>'}
      </div>

      <!-- Tab: Transcript -->
      <div id="gw-cc-panel-transcript" class="gw-cc-scroll" style="display:none;padding:12px">
        <div style="margin-bottom:8px;display:flex;align-items:center;gap:8px;flex-wrap:wrap">
          <button type="button" id="gw-cc-rec-btn" onclick="gwCCRecToggle('${oppId}')"
            style="padding:7px 14px;background:#2D7A55;border:none;border-radius:8px;color:#fff;font-size:11px;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:5px">
            <span id="gw-cc-rec-dot" style="width:8px;height:8px;border-radius:50%;background:#4ade80;display:inline-block"></span>
            <span id="gw-cc-rec-label">Start Recording</span>
          </button>
          <span id="gw-cc-rec-timer" style="font-size:11px;color:#5E6E6F;font-weight:600"></span>
        </div>
        <div style="font-size:10px;color:#9CA3A3;margin-bottom:8px">Transcription happens in your browser — nothing is sent externally during recording.</div>
        <textarea id="gw-cc-transcript-ta" rows="7" placeholder="Transcript will appear here as you speak. You can also type notes manually…"
          style="width:100%;border:1px solid #E0DDD5;border-radius:9px;padding:9px 11px;font-size:12px;resize:vertical;box-sizing:border-box;color:#1F2A2B;background:#FAFAF8;line-height:1.6"></textarea>
        <div style="display:flex;gap:8px;margin-top:8px;flex-wrap:wrap">
          <button type="button" onclick="gwCCSaveTranscript('${oppId}')"
            style="padding:7px 14px;background:#2D7A55;border:none;border-radius:8px;color:#fff;font-size:11px;font-weight:700;cursor:pointer">
            Save to Call Log
          </button>
          <button type="button" onclick="document.getElementById('gw-cc-transcript-ta').value=''"
            style="padding:7px 12px;background:#F5F2EC;border:1px solid #E0DDD5;border-radius:8px;color:#5E6E6F;font-size:11px;font-weight:700;cursor:pointer">
            Clear
          </button>
        </div>

        <!-- Post-call generators -->
        <div style="margin-top:14px;padding-top:12px;border-top:1px dashed #E0DDD5">
          <div class="gw-cc-section-label">Generate From This Call</div>
          <div style="display:flex;flex-direction:column;gap:6px">${genBtnsHtml}</div>
        </div>

        <div id="gw-cc-summary-out" style="display:none;margin-top:12px;padding:12px;background:#EAF1EE;border:1px solid #2D7A5530;border-radius:10px">
          <div id="gw-cc-summary-title" style="font-size:11px;font-weight:800;color:#1A4740;margin-bottom:8px;text-transform:uppercase;letter-spacing:.05em">Generated Output</div>
          <div id="gw-cc-summary-text" style="font-size:12px;color:#1F2A2B;line-height:1.7;white-space:pre-wrap"></div>
          <div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap">
            <button type="button" onclick="navigator.clipboard.writeText(document.getElementById('gw-cc-summary-text').textContent).then(()=>window.showToast&&window.showToast('Copied!'))"
              style="padding:6px 12px;background:#2D7A55;border:none;border-radius:7px;color:#fff;font-size:11px;font-weight:700;cursor:pointer">
              Copy
            </button>
            <button type="button" onclick="gwCCSaveNote('${oppId}')"
              style="padding:6px 12px;background:#F5F2EC;border:1px solid #E0DDD5;border-radius:7px;color:#5E6E6F;font-size:11px;font-weight:700;cursor:pointer">
              Save as Note
            </button>
          </div>
        </div>
      </div>
    </div>

    <div id="gw-cc-resize-grip" title="Drag to resize"
      style="position:absolute;left:0;bottom:0;width:18px;height:18px;cursor:nesw-resize;display:flex;align-items:flex-end;justify-content:flex-start;padding:3px;opacity:.45">
      <svg width="10" height="10" viewBox="0 0 10 10"><path d="M1 9L9 1M1 5L5 1" stroke="#5E6E6F" stroke-width="1.4" stroke-linecap="round"/></svg>
    </div>

    <style>
      #gw-call-companion { position:fixed;bottom:24px;right:24px;width:440px;max-width:95vw;border-radius:14px;box-shadow:0 20px 60px rgba(0,0,0,.25),0 4px 16px rgba(0,0,0,.15);z-index:9800;background:#fff;border:1px solid #E0DDD5;font-family:inherit }
      #gw-call-companion .gw-cc-scroll { overflow-y:auto;max-height:460px }
      .gw-cc-section-label { font-size:10px;font-weight:800;color:#5E6E6F;text-transform:uppercase;letter-spacing:.06em;margin-bottom:6px;display:block }
      .gw-cc-q { font-size:11.5px;color:#1F2A2B;padding:6px 9px;background:#F5F2EC;border-radius:7px;margin-bottom:5px;line-height:1.5 }
      .gw-cc-rf { font-size:11.5px;color:#7A2E20;padding:6px 9px;background:#FAE8E430;border-radius:7px;margin-bottom:5px;line-height:1.5 }
      .gw-cc-empty { font-size:12px;color:#9CA3A3;font-style:italic;padding:8px 0 }
      .gw-cc-step { padding:10px;background:#FAFAF8;border-radius:8px;margin-bottom:8px }
      .gw-cc-check-row { display:flex;align-items:flex-start;gap:10px;padding:8px 10px;background:#FAFAF8;border:1px solid #EEEAE2;border-radius:8px;margin-bottom:6px;cursor:pointer;font-size:12px;color:#1F2A2B;line-height:1.5;transition:background .12s }
      .gw-cc-check-row:hover { background:#F3F0E9 }
      .gw-cc-check-row input { margin-top:2px;accent-color:#2D7A55;flex-shrink:0;width:14px;height:14px }
      .gw-cc-check-done { opacity:.55 }
      .gw-cc-check-done span { text-decoration:line-through }
      .gw-cc-nav-btn { background:#F5F2EC;border:1px solid #E0DDD5;border-radius:8px;width:28px;height:28px;cursor:pointer;font-size:9px;color:#5E6E6F;display:flex;align-items:center;justify-content:center;flex-shrink:0;transition:all .12s }
      .gw-cc-nav-btn:hover { background:#2D7A55;border-color:#2D7A55;color:#fff }
      .gw-cc-gen-btn { text-align:left;padding:8px 11px;background:#FAFAF8;border:1px solid #E0DDD5;border-radius:9px;cursor:pointer;font-size:11.5px;color:#1F2A2B;line-height:1.35;transition:all .12s }
      .gw-cc-gen-btn:hover { border-color:#2D7A55;background:#EAF1EE }
      @keyframes gw-cc-pulse { 0%,100%{opacity:1} 50%{opacity:.4} }
    </style>`;

  document.body.appendChild(panel);

  // ── Apply size (preset or custom) ───────────────────────────────────────────
  function applySize() {
    const dim = ccCustom || CC_SIZES[ccSize];
    panel.style.width = Math.min(dim.w, window.innerWidth - 20) + 'px';
    panel.querySelectorAll('.gw-cc-scroll').forEach(el => el.style.maxHeight = dim.h + 'px');
    ['S','M','L'].forEach(sz => {
      const b = document.getElementById('gw-cc-size-' + sz);
      if (b) b.style.background = (!ccCustom && sz === ccSize) ? '#ffffff28' : 'transparent';
    });
  }
  applySize();

  window.gwCCSetSize = function(sz) {
    if (!CC_SIZES[sz]) return;
    ccSize = sz; ccCustom = null;
    localStorage.setItem('gw-cc-size', sz);
    localStorage.removeItem('gw-cc-custom-size');
    applySize();
  };

  // ── Minimise toggle (collapse to header bar) ────────────────────────────────
  let ccMinimised = false;
  window.gwCCMinToggle = function() {
    ccMinimised = !ccMinimised;
    const body = document.getElementById('gw-cc-body');
    const grip = document.getElementById('gw-cc-resize-grip');
    const btn  = document.getElementById('gw-cc-min-btn');
    if (body) body.style.display = ccMinimised ? 'none' : '';
    if (grip) grip.style.display = ccMinimised ? 'none' : '';
    if (btn)  btn.innerHTML = ccMinimised ? '&#9633;' : '&#8212;';
    const handle = document.getElementById('gw-cc-drag-handle');
    if (handle) handle.style.borderRadius = ccMinimised ? '14px' : '14px 14px 0 0';
  };

  // ── Stage navigation ────────────────────────────────────────────────────────
  window._ccStageView = ccStageView;
  window.gwCCStageGo = function(n) {
    n = Math.max(1, Math.min(maxStage, Number(n) || 1));
    ccStageView = n;
    window._ccStageView = n;
    const body = document.getElementById('gw-cc-stage-body');
    if (body) body.innerHTML = ccStageBody(n);
    const sel = document.getElementById('gw-cc-stage-select');
    if (sel) sel.value = String(n);
    const prev = document.getElementById('gw-cc-stage-prev');
    const next = document.getElementById('gw-cc-stage-next');
    if (prev) prev.style.opacity = n <= 1 ? '.35' : '1';
    if (next) next.style.opacity = n >= maxStage ? '.35' : '1';
  };
  // Wire prev/next (avoid template-literal escaping issues by binding here)
  document.getElementById('gw-cc-stage-prev').onclick = () => gwCCStageGo(ccStageView - 1);
  document.getElementById('gw-cc-stage-next').onclick = () => gwCCStageGo(ccStageView + 1);
  gwCCStageGo(currentStageNum);

  // ── Make draggable ──────────────────────────────────────────────────────────
  (function(){
    const handle = document.getElementById('gw-cc-drag-handle');
    let dragging = false, startX, startY, origRight, origBottom;
    handle.addEventListener('mousedown', e => {
      if (e.target.closest('button')) return; // don't drag from buttons
      dragging = true;
      startX = e.clientX; startY = e.clientY;
      const rect = panel.getBoundingClientRect();
      origRight  = window.innerWidth  - rect.right;
      origBottom = window.innerHeight - rect.bottom;
      handle.style.cursor = 'grabbing';
      e.preventDefault();
    });
    document.addEventListener('mousemove', e => {
      if (!dragging) return;
      const dx = e.clientX - startX, dy = e.clientY - startY;
      panel.style.right  = Math.max(0, origRight  - dx) + 'px';
      panel.style.bottom = Math.max(0, origBottom - dy) + 'px';
    });
    document.addEventListener('mouseup', () => { dragging = false; handle.style.cursor = 'grab'; });
  })();

  // ── Custom drag-resize (bottom-left grip; panel anchored bottom-right) ─────
  (function(){
    const grip = document.getElementById('gw-cc-resize-grip');
    let resizing = false, startX, startY, origW, origH;
    grip.addEventListener('mousedown', e => {
      resizing = true;
      startX = e.clientX; startY = e.clientY;
      origW = panel.getBoundingClientRect().width;
      const firstScroll = panel.querySelector('.gw-cc-scroll');
      origH = firstScroll ? parseInt(firstScroll.style.maxHeight || '460', 10) : 460;
      e.preventDefault(); e.stopPropagation();
    });
    document.addEventListener('mousemove', e => {
      if (!resizing) return;
      const w = Math.max(300, Math.min(window.innerWidth - 20, origW + (startX - e.clientX)));
      const h = Math.max(220, Math.min(window.innerHeight - 140, origH + (e.clientY - startY)));
      ccCustom = { w: Math.round(w), h: Math.round(h) };
      panel.style.width = ccCustom.w + 'px';
      panel.querySelectorAll('.gw-cc-scroll').forEach(el => el.style.maxHeight = ccCustom.h + 'px');
      ['S','M','L'].forEach(sz => { const b = document.getElementById('gw-cc-size-'+sz); if (b) b.style.background = 'transparent'; });
    });
    document.addEventListener('mouseup', () => {
      if (resizing && ccCustom) { try { localStorage.setItem('gw-cc-custom-size', JSON.stringify(ccCustom)); } catch(e){} }
      resizing = false;
    });
  })();

  // ── Tab switching ───────────────────────────────────────────────────────────
  window.gwCCTab = function(tab) {
    ['stage','steps','transcript'].forEach(t => {
      const p = document.getElementById('gw-cc-panel-'+t);
      const b = document.getElementById('gw-cc-tab-'+t);
      if (p) p.style.display = t === tab ? 'block' : 'none';
      if (b) {
        b.style.borderBottomColor = t === tab ? '#2D7A55' : 'transparent';
        b.style.color             = t === tab ? '#2D7A55' : '#5E6E6F';
      }
    });
  };

  // ── Transcript recorder (Web Speech API) ────────────────────────────────────
  let _ccRecognition = null, _ccRecording = false, _ccTimerInterval = null, _ccSeconds = 0;

  window.gwCCRecToggle = function(oid) {
    const btn   = document.getElementById('gw-cc-rec-btn');
    const dot   = document.getElementById('gw-cc-rec-dot');
    const label = document.getElementById('gw-cc-rec-label');
    const timer = document.getElementById('gw-cc-rec-timer');
    const ta    = document.getElementById('gw-cc-transcript-ta');
    if (!ta) return;

    if (!_ccRecording) {
      // Start
      const SpeechRec = window.SpeechRecognition || window.webkitSpeechRecognition;
      if (!SpeechRec) {
        window.showToast && window.showToast('Speech recognition not supported in this browser — try Chrome');
        return;
      }
      _ccRecognition = new SpeechRec();
      _ccRecognition.continuous     = true;
      _ccRecognition.interimResults = true;
      _ccRecognition.lang           = 'en-US';

      _ccRecognition.onresult = (e) => {
        let final = '';
        for (let i = e.resultIndex; i < e.results.length; i++) {
          if (e.results[i].isFinal) final += e.results[i][0].transcript + ' ';
        }
        if (final) ta.value += final;
      };
      _ccRecognition.onerror = (e) => {
        if (e.error !== 'no-speech') window.showToast && window.showToast('Mic error: ' + e.error);
      };
      _ccRecognition.onend = () => {
        if (_ccRecording) _ccRecognition.start(); // auto-restart on silence
      };
      _ccRecognition.start();
      _ccRecording = true;
      _ccSeconds = 0;
      _ccTimerInterval = setInterval(() => {
        _ccSeconds++;
        const m = Math.floor(_ccSeconds/60), s = _ccSeconds%60;
        if (timer) timer.textContent = `${m}:${s<10?'0'+s:s}`;
      }, 1000);
      if (btn)   btn.style.background = '#C97B6A';
      if (dot)   { dot.style.background = '#f87171'; }
      if (label) label.textContent = 'Stop Recording';
      window.showToast && window.showToast('Recording started');

    } else {
      // Stop
      _ccRecording = false;
      if (_ccRecognition) { try { _ccRecognition.stop(); } catch(e){} _ccRecognition = null; }
      clearInterval(_ccTimerInterval);
      if (btn)   btn.style.background = '#2D7A55';
      if (dot)   dot.style.background = '#4ade80';
      if (label) label.textContent = 'Start Recording';
      window.showToast && window.showToast('Recording stopped — pick a generator below to turn the call into an email, SOW, or note');
    }
  };

  // ── Save transcript as a communication log entry ────────────────────────────
  window.gwCCSaveTranscript = function(oid) {
    const ta = document.getElementById('gw-cc-transcript-ta');
    if (!ta || !ta.value.trim()) { window.showToast && window.showToast('Nothing to save yet'); return; }
    const transcript = ta.value.trim();
    const ts         = new Date().toISOString();
    const rep        = window.getCurrentRep ? window.getCurrentRep() : null;
    const entry = {
      id:        'comm_' + Date.now(),
      oppId:     oid,
      type:      'call',
      direction: 'in',
      ts,
      body:      '[TRANSCRIPT]\n' + transcript,
      sentBy:    rep ? rep.name : 'Unknown',
      files:     []
    };
    if (!state.communications) state.communications = [];
    state.communications.unshift(entry);
    saveState();
    fetch('/api/opportunities/' + oid + '/comms', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'include',
      body: JSON.stringify({ type:'call', direction:'in', body: entry.body, ts })
    }).catch(() => {});
    window.showToast && window.showToast('Transcript saved to call log');
  };

  // ── Generate output from transcript (AI with local fallback) ────────────────
  window.gwCCGenerate = function(oid, kind) {
    const ta  = document.getElementById('gw-cc-transcript-ta');
    const out = document.getElementById('gw-cc-summary-out');
    const txt = document.getElementById('gw-cc-summary-text');
    const ttl = document.getElementById('gw-cc-summary-title');
    if (!ta || !ta.value.trim()) { window.showToast && window.showToast('Record or type a transcript first'); return; }
    if (!out || !txt) return;

    const opp        = (state && state.opportunities || []).find(x => x.id === oid);
    const transcript = ta.value.trim();
    const gen        = CC_GENS.find(g => g.id === kind);

    out.style.display = 'block';
    if (ttl) ttl.textContent = gen ? gen.label : 'Generated Output';
    txt.textContent = 'Generating…';
    out.scrollIntoView({ behavior:'smooth', block:'nearest' });

    const prompt = gwCCBuildPrompt(kind, transcript, opp);
    fetch('/api/ai/chat', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'include',
      body: JSON.stringify({ messages: [{ role: 'user', content: prompt }], model: 'gpt-4o-mini' })
    })
    .then(r => r.json())
    .then(j => { txt.textContent = (j.ok && j.data) ? j.data : gwCCLocalGen(kind, transcript, opp); })
    .catch(() => { txt.textContent = gwCCLocalGen(kind, transcript, opp); });
  };

  // ── Save generated output as a note on the opportunity ──────────────────────
  window.gwCCSaveNote = function(oid) {
    const txt = document.getElementById('gw-cc-summary-text');
    const ttl = document.getElementById('gw-cc-summary-title');
    if (!txt || !txt.textContent.trim() || txt.textContent === 'Generating…') return;
    const noteBody = (ttl ? ttl.textContent : 'Call Output') + '\n\n' + txt.textContent.trim();
    const ts       = new Date().toISOString();
    const note     = { id: 'note_' + Date.now(), oppId: oid, body: noteBody, createdAt: ts };
    if (!state.notes) state.notes = [];
    state.notes.unshift(note);
    const opp = (state && state.opportunities || []).find(x => x.id === oid);
    if (opp) opp.updatedAt = ts;
    saveState();
    fetch('/api/opportunities/' + oid + '/notes', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'include',
      body: JSON.stringify({ body: noteBody })
    }).catch(() => {});
    window.showToast && window.showToast('Saved as note');
  };
};

// ── Call Companion: shared prompt + local generation helpers ─────────────────
function gwCCBudgetRange(opp) {
  const raw = opp && opp.budget;
  if (raw == null || raw === '') return '$[X] – $[Y]';
  const num = Number(String(raw).replace(/[^0-9.]/g, ''));
  if (isNaN(num) || num <= 0) return String(raw); // already a text range like "10k-15k"
  const lo = Math.round(num * 0.9  / 100) * 100;
  const hi = Math.round(num * 1.15 / 100) * 100;
  return '$' + lo.toLocaleString() + ' – $' + hi.toLocaleString();
}

function gwCCBuildPrompt(kind, transcript, opp) {
  const ctx = [
    'Client: '  + (opp && opp.client  || 'Unknown'),
    'Project: ' + (opp && (opp.project || opp.serviceLine) || 'Landscaping project'),
    'Stage: '   + (opp && opp.status  || 'Unknown'),
    'Budget: '  + gwCCBudgetRange(opp),
  ].join('\n');
  const base = `You are a sales assistant for a premium landscaping company. Use ONLY details from the transcript — never invent specifics.\n\n${ctx}\n\nTRANSCRIPT:\n${transcript.slice(0, 4000)}\n\n`;
  switch (kind) {
    case 'summary_email':
      return base + 'Write a client-ready follow-up email: 1) SUBJECT line, 2) warm greeting, 3) 2-3 sentence summary of the call, 4) clear NEXT STEPS as a short bullet list with suggested timing, 5) friendly sign-off.';
    case 'full_package':
      return base + 'Write a complete follow-up email containing: 1) SUBJECT line, 2) short call summary, 3) SCOPE OF WORK section as a bullet list drawn from what was discussed, 4) WORKING BUDGET RANGE section presenting the range ' + gwCCBudgetRange(opp) + ' with a one-line disclaimer that final pricing follows the site assessment, 5) NEXT STEPS bullets with timing, 6) sign-off.';
    case 'sow_budget':
      return base + 'Produce (NOT an email): 1) SCOPE OF WORK — organised bullet list of all work discussed, grouped by area if possible, 2) WORKING BUDGET RANGE — present ' + gwCCBudgetRange(opp) + ' with brief assumptions, 3) EXCLUSIONS / OPEN QUESTIONS — anything unclear from the call.';
    case 'client_recap':
      return base + 'Write a short, warm thank-you email (under 120 words): thank them for their time, reflect back the 2-3 most important things you heard (their goals and concerns), and confirm the single next step.';
    case 'handoff_note':
      return base + 'Write an INTERNAL handoff note for the team (not client-facing): CLIENT SNAPSHOT, KEY PAIN POINTS, SCOPE DISCUSSED, BUDGET SIGNALS, RED FLAGS / RISKS, NEXT ACTIONS with owner suggestions.';
    default:
      return base + 'Summarise the call and list clear next steps.';
  }
}

function gwCCLocalGen(kind, transcript, opp) {
  const client   = opp && opp.client || '[Client Name]';
  const project  = opp && (opp.project || opp.serviceLine) || 'your landscaping project';
  const budget   = gwCCBudgetRange(opp);
  const sents    = transcript.split(/[.!?]+/).map(s => s.trim()).filter(s => s.length > 15);
  const summary  = sents.slice(0, 3).join('. ') + (sents.length ? '.' : '');
  const points   = sents.slice(0, 6).map(s => '• ' + (s.length > 110 ? s.slice(0, 110) + '…' : s));
  const rep      = (window.getCurrentRep && window.getCurrentRep()) || {};
  const repName  = rep.name || '[Your Name]';
  const NEXT     = ['• Site assessment / follow-up visit — propose 2 time options', '• Send this recap within 24 hours', '• Update lead stage and next follow-up date in the CRM'];

  switch (kind) {
    case 'summary_email':
      return `SUBJECT: Great speaking with you — recap & next steps\n\nHi ${client},\n\nThank you for taking the time to talk today about ${project}. Here's a quick recap of what we covered:\n\n${summary || '(Add call summary)'}\n\nNEXT STEPS\n${NEXT.join('\n')}\n\nIf I missed anything or you'd like to adjust the plan, just reply here.\n\nBest,\n${repName}`;
    case 'full_package':
      return `SUBJECT: ${project} — recap, scope & working budget\n\nHi ${client},\n\nThanks again for the conversation today. Here's where we stand:\n\nCALL SUMMARY\n${summary || '(Add call summary)'}\n\nSCOPE OF WORK (as discussed)\n${points.join('\n') || '• (Pull scope items from the transcript)'}\n\nWORKING BUDGET RANGE\nBased on what we discussed, projects like this typically land in the ${budget} range. Final pricing follows our on-site assessment.\n\nNEXT STEPS\n${NEXT.join('\n')}\n\nBest,\n${repName}`;
    case 'sow_budget':
      return `SCOPE OF WORK — ${client} / ${project}\n${points.join('\n') || '• (Pull scope items from the transcript)'}\n\nWORKING BUDGET RANGE\n${budget}\nAssumes standard site access and conditions; final pricing follows the on-site assessment.\n\nEXCLUSIONS / OPEN QUESTIONS\n• Confirm property access and utility markouts\n• Confirm material selections and finish level\n• (Add anything left unresolved on the call)`;
    case 'client_recap':
      return `SUBJECT: Thank you, ${client}!\n\nHi ${client},\n\nThank you for your time today — I really enjoyed learning about your plans for ${project}. What stood out to me most:\n\n${points.slice(0, 3).join('\n') || '• (Key things you heard)'}\n\nOur next step: I'll follow up with scheduling for the site visit. Talk soon!\n\nWarm regards,\n${repName}`;
    case 'handoff_note':
      return `INTERNAL HANDOFF NOTE — ${client}\n\nCLIENT SNAPSHOT\n${client} · ${project} · Stage: ${opp && opp.status || '—'}\n\nKEY POINTS FROM CALL\n${points.join('\n') || '• (Key points)'}\n\nBUDGET SIGNALS\n${budget}\n\nRED FLAGS / RISKS\n• (Review transcript for objections, timing pressure, decision-maker gaps)\n\nNEXT ACTIONS\n${NEXT.join('\n')}\n\n— Logged by ${repName}`;
    default:
      return `SUMMARY\n${summary || '(No summary available — add more transcript content)'}\n\nNEXT STEPS\n${NEXT.join('\n')}`;
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// PHASE 5 — CUSTOMER + MONEY LOOP
// Estimate Detail · Invoice Detail · Account Statement ·
// Communications Board · Automation Manager · Financial Hub
// ═══════════════════════════════════════════════════════════════════════════

// ── Helpers shared across Phase 5 views ──────────────────────────────────
function _p5Money(v){
  const n=Number(v||0);
  return isNaN(n)?'—':'$'+n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
}
function _p5FmtDate(d){
  if(!d) return '—';
  try{ return new Date(d).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}); }
  catch(e){ return d; }
}
function _p5Initials(name){
  return (name||'?').split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase();
}

// ── ESTIMATE DETAIL ───────────────────────────────────────────────────────
function estimateDetail(id){
  // Pull from state or create demo
  const opp = id ? state.opportunities.find(o=>o.id===id) : null;
  const estNum = 'EST-' + String(opp ? opp.id : '0001').slice(-4).toUpperCase();
  const clientName = opp ? (opp.client||'Client') : 'Sample Client';
  const jobVal     = opp ? Number(opp.jobValue||0) : 5400;
  const deposit    = Math.round(jobVal * 0.30);
  const remaining  = jobVal - deposit;
  const status     = opp ? (opp.status==='Sold / Activation'?'approved':(opp.estimateStatus||'draft')) : 'draft';
  const badgeClass = {draft:'est-badge--draft',sent:'est-badge--sent',approved:'est-badge--approved',declined:'est-badge--declined',expired:'est-badge--expired'}[status]||'est-badge--draft';
  const badgeLabel = status.charAt(0).toUpperCase()+status.slice(1);
  const backTo     = opp ? `show('pipeline','${opp.id}')` : "show('financialHub')";
  const backLabel  = opp ? 'Lead' : 'Financial Hub';

  const lineItems = opp ? [
    { name: opp.serviceLine||opp.project||'Service', qty:1, unit: jobVal - deposit, desc: opp.project||'' },
    { name: 'Deposit (30%)', qty:1, unit: deposit, desc: 'Required at contract signing' }
  ] : [
    { name: 'Installation — Full System', qty:1, unit:3800, desc:'Labor and materials included' },
    { name: 'Premium Control Panel Upgrade', qty:1, unit:1200, desc:'Smart home integration' },
    { name: 'Annual Monitoring Plan', qty:1, unit:400, desc:'24/7 professional monitoring' }
  ];

  const lineRows = lineItems.map(l=>`
    <tr>
      <td><div style="font-weight:600">${escapeHtml(l.name)}</div><div class="est-line-desc">${escapeHtml(l.desc||'')}</div></td>
      <td style="text-align:center">${l.qty}</td>
      <td>${_p5Money(l.unit)}</td>
      <td>${_p5Money(l.qty*l.unit)}</td>
    </tr>`).join('');

  const subtotal = lineItems.reduce((a,l)=>a+l.qty*l.unit,0);
  const tax      = 0;
  const total    = subtotal + tax;

  view.innerHTML = `
  <div class="rp-shell">
    <div class="rp-command" id="rpCommandBar">
      <button class="rp-command-back" onclick="${backTo}">
        <svg width="13" height="13" viewBox="0 0 14 14" fill="none"><path d="M9 11L4 7l5-4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>
        ${backLabel}
      </button>
      <div class="rp-command-identity">
        <div class="rp-command-avatar">${_p5Initials(clientName)}</div>
        <span class="rp-command-name">${escapeHtml(clientName)}</span>
        <div class="rp-command-meta">
          <span class="est-badge ${badgeClass}" style="font-size:10px;padding:2px 8px">${badgeLabel}</span>
          <span style="font-size:12px;font-weight:700;color:var(--gw-action)">${_p5Money(total)}</span>
        </div>
      </div>
      <div class="rp-command-actions">
        ${status==='draft'?`<button class="rp-btn rp-btn--primary" style="padding:6px 13px;font-size:12.5px" onclick="showToast('Estimate sent to client','success')">Send to Client</button>`:''}
        ${status==='sent'?`<button class="rp-btn rp-btn--primary" style="padding:6px 13px;font-size:12.5px;background:var(--gw-pine-500)" onclick="showToast('Estimate approved','success')">Mark Approved</button>`:''}
      </div>
    </div>

    <div style="background:var(--gw-surface);border-bottom:1px solid var(--gw-border);padding:0 24px">
      <div class="est-header-band" style="border-bottom:none;padding-left:0;padding-right:0">
        <div class="est-number">${estNum}</div>
        <div class="est-title">Estimate for ${escapeHtml(clientName)}</div>
        <div class="est-meta-row">
          <span class="est-badge ${badgeClass}">${badgeLabel}</span>
          <span>Created ${_p5FmtDate(opp?opp.createdAt:new Date().toISOString())}</span>
          ${opp&&opp.nextFollowUp?`<span>Valid until ${_p5FmtDate(opp.nextFollowUp)}</span>`:''}
          ${opp?`<span>Rep: ${(window.REPS||[]).find(r=>r.id===opp.repId)?.name||'Unassigned'}</span>`:''}
        </div>
      </div>
    </div>

    <div class="est-body">
      <div class="est-section-head">Scope of Work</div>
      <table class="est-line-table">
        <thead><tr><th>Item / Description</th><th style="text-align:center;width:60px">Qty</th><th style="width:120px">Unit Price</th><th style="width:120px">Total</th></tr></thead>
        <tbody>${lineRows}</tbody>
      </table>
      <div class="est-totals-col">
        <div class="est-total-row"><span>Subtotal</span><span>${_p5Money(subtotal)}</span></div>
        <div class="est-total-row"><span>Tax (0%)</span><span>${_p5Money(tax)}</span></div>
        <div class="est-total-row"><strong>Total</strong><strong>${_p5Money(total)}</strong></div>
      </div>

      <div class="est-section-head" style="margin-top:28px">Payment Terms</div>
      <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-bottom:20px">
        <div style="background:var(--gw-bark-25);border:1px solid var(--gw-border);border-radius:8px;padding:12px 14px">
          <div style="font-size:10px;text-transform:uppercase;letter-spacing:.07em;color:var(--gw-text-muted);font-weight:700;margin-bottom:4px">Deposit (30%)</div>
          <div style="font-size:16px;font-weight:800;color:var(--gw-action)">${_p5Money(deposit)}</div>
          <div style="font-size:11px;color:var(--gw-text-muted)">Due at signing</div>
        </div>
        <div style="background:var(--gw-bark-25);border:1px solid var(--gw-border);border-radius:8px;padding:12px 14px">
          <div style="font-size:10px;text-transform:uppercase;letter-spacing:.07em;color:var(--gw-text-muted);font-weight:700;margin-bottom:4px">Progress</div>
          <div style="font-size:16px;font-weight:800;color:var(--gw-action)">50%</div>
          <div style="font-size:11px;color:var(--gw-text-muted)">Mid-project</div>
        </div>
        <div style="background:var(--gw-bark-25);border:1px solid var(--gw-border);border-radius:8px;padding:12px 14px">
          <div style="font-size:10px;text-transform:uppercase;letter-spacing:.07em;color:var(--gw-text-muted);font-weight:700;margin-bottom:4px">Final</div>
          <div style="font-size:16px;font-weight:800;color:var(--gw-action)">20%</div>
          <div style="font-size:11px;color:var(--gw-text-muted)">On completion</div>
        </div>
      </div>

      ${opp&&opp.notes&&opp.notes.length?`
      <div class="est-section-head">Notes</div>
      <div class="est-notes-area">${escapeHtml((opp.notes||[]).slice(-1)[0]?.body||'No notes')}</div>`:''}

      <div class="est-action-bar">
        <button class="est-btn est-btn--send" onclick="_estSendToClient('${opp?opp.id:''}')">
          <svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="1" y="3" width="14" height="10" rx="1.5"/><path d="M1 6l7 4 7-4"/></svg>
          Send to Client
        </button>
        ${status==='sent'?`<button class="est-btn est-btn--approve" onclick="_estMarkApproved('${opp?opp.id:''}')">✓ Mark Approved</button>`:''}
        ${status==='sent'?`<button class="est-btn est-btn--decline" onclick="_estMarkDeclined('${opp?opp.id:''}')">✗ Mark Declined</button>`:''}
        ${(status==='accepted'||status==='approved')?`<button class="est-btn est-btn--schedule" onclick="_estScheduleVisit('${opp?opp.id:''}')">
          <svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="1" y="3" width="14" height="12" rx="1.5"/><path d="M5 1v4M11 1v4M1 7h14"/></svg>
          Schedule Visit
        </button>`:''}
        <button class="est-btn est-btn--secondary" onclick="showToast('PDF download coming soon','info')">
          <svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 1h8a1 1 0 011 1v12a1 1 0 01-1 1H4a1 1 0 01-1-1V2a1 1 0 011-1z"/><path d="M5 5h6M5 8h6M5 11h4"/></svg>
          Download PDF
        </button>
        ${opp?`<button class="est-btn est-btn--secondary" onclick="show('pipeline','${opp.id}')">View Lead →</button>`:''}
      </div>

      ${opp ? `
      <div class="est-section-head" style="margin-top:28px">Approvals</div>
      <div id="est-approval-panel-${opp.id}" style="margin-bottom:8px"></div>` : ''}
    </div>
  </div>`;

  // Attach command-bar scroll behavior
  setTimeout(()=>{
    const bar = document.getElementById('rpCommandBar');
    if(!bar) return;
    window.addEventListener('scroll',()=>{ bar.classList.toggle('is-pinned',window.scrollY>60); },{passive:true});
  },100);

  // Wire approval panel if engine loaded
  if (opp && typeof window.gwApproval === 'object') {
    const panelEl = document.getElementById(`est-approval-panel-${opp.id}`);
    if (panelEl) window.gwApproval.renderPanel(panelEl, 'estimate', opp.id, `EST-${String(opp.id).slice(-4).toUpperCase()} — ${opp.client||'Client'}`);
  }

  // Estimate action handlers
  window._estSendToClient = function(oppId) {
    const o = oppId ? state.opportunities.find(x=>x.id===oppId) : null;
    if (o) {
      o.estimateStatus = 'sent';
      state.opportunities = state.opportunities.map(x=>x.id===oppId?o:x);
      saveState();
      if (typeof window.gwWorkflow === 'object') window.gwWorkflow.communicationSent({ entityType:'estimate', entityId:oppId, entityLabel:`EST for ${o.client||'Client'}`, type:'estimate_sent', method:'email' });
      if (typeof window.gwAudit === 'function') window.gwAudit({ type:'estimate_sent', entityType:'estimate', entityId:oppId, entityLabel:`EST for ${o.client||'Client'}` });
    }
    showToast('Estimate sent via email', 'success');
    if (oppId) estimateDetail(oppId);
  };
  window._estMarkApproved = function(oppId) {
    const o = oppId ? state.opportunities.find(x=>x.id===oppId) : null;
    if (o) {
      o.estimateStatus = 'accepted';
      state.opportunities = state.opportunities.map(x=>x.id===oppId?o:x);
      saveState();
      if (typeof window.gwWorkflow === 'object') window.gwWorkflow.estimateApproved({ entityId:oppId, entityLabel:`EST for ${o.client||'Client'}`, client:o.client, jobValue:o.jobValue });
      if (typeof window.gwAudit === 'function') window.gwAudit({ type:'estimate_approved', entityType:'estimate', entityId:oppId, entityLabel:`EST for ${o.client||'Client'}`, meta:{ jobValue:o.jobValue } });
    }
    showToast('Estimate approved — ready to invoice', 'success');
    if (oppId) estimateDetail(oppId);
  };
  window._estMarkDeclined = function(oppId) {
    const o = oppId ? state.opportunities.find(x=>x.id===oppId) : null;
    if (o) {
      o.estimateStatus = 'declined';
      state.opportunities = state.opportunities.map(x=>x.id===oppId?o:x);
      saveState();
      if (typeof window.gwAudit === 'function') window.gwAudit({ type:'estimate_declined', entityType:'estimate', entityId:oppId, entityLabel:`EST for ${o.client||'Client'}` });
    }
    showToast('Estimate marked declined', 'error');
    if (oppId) estimateDetail(oppId);
  };
  window._estScheduleVisit = function(oppId) {
    const o = oppId ? state.opportunities.find(x=>x.id===oppId) : null;
    // Pre-populate the new visit modal with estimate data
    if (!window._sbState.loaded) {
      _sbLoadData().then(()=> _sbOpenNewVisitFromEst(o));
    } else {
      _sbOpenNewVisitFromEst(o);
    }
    show('scheduleBoard');
    setTimeout(()=> _sbOpenNewVisitFromEst(o), 300);
  };
}
window.estimateDetail = estimateDetail;
window._sbOpenNewVisitFromEst = function(opp) {
  if (!opp) { _sbOpenNewVisit(null, null); return; }
  const preDate = null; // Let user pick
  _sbOpenNewVisit(preDate);
  // Pre-fill after modal opens
  setTimeout(()=>{
    const clientEl = document.getElementById('snv-client');
    const addrEl   = document.getElementById('snv-addr');
    const notesEl  = document.getElementById('snv-notes');
    if (clientEl) clientEl.value = opp.client||'';
    if (addrEl)   addrEl.value   = opp.address||'';
    if (notesEl)  notesEl.value  = `From estimate: ${opp.project||opp.serviceLine||''}`;
  }, 100);
};

// ── INVOICE DETAIL ────────────────────────────────────────────────────────
function invoiceDetail(id){
  const opp        = id ? state.opportunities.find(o=>o.id===id) : null;
  const invNum     = 'INV-' + String(opp ? opp.id : '0001').slice(-4).toUpperCase();
  const clientName = opp ? (opp.client||'Client') : 'Sample Client';
  const jobVal     = opp ? Number(opp.jobValue||0) : 5400;
  const deposit    = Math.round(jobVal * 0.30);
  const totalDue   = jobVal;
  const isPaid     = opp ? opp.status==='Sold / Activation' : false;
  const paidAmt    = isPaid ? totalDue : deposit;
  const balance    = totalDue - paidAmt;
  const status     = isPaid ? 'paid' : (balance > 0 ? 'partial' : 'sent');
  const badgeClass = {draft:'inv-badge--draft',sent:'inv-badge--sent',partial:'inv-badge--partial',paid:'inv-badge--paid',overdue:'inv-badge--overdue'}[status]||'inv-badge--draft';
  const badgeLabel = {draft:'Draft',sent:'Sent',partial:'Partial',paid:'Paid',overdue:'Overdue'}[status]||status;
  const backTo     = opp ? `show('pipeline','${opp.id}')` : "show('financialHub')";
  const backLabel  = opp ? 'Lead' : 'Financial Hub';
  const repName    = opp ? ((window.REPS||[]).find(r=>r.id===opp.repId)?.name||'Unassigned') : 'Rep';

  const payments = isPaid
    ? [{ date: opp?.closedDate||new Date().toISOString(), method:'Check', amount:totalDue, note:'Payment in full' }]
    : [{ date: new Date(Date.now()-7*86400000).toISOString(), method:'Credit Card', amount:deposit, note:'Deposit' }];

  view.innerHTML = `
  <div class="rp-shell">
    <div class="rp-command" id="rpCommandBar">
      <button class="rp-command-back" onclick="${backTo}">
        <svg width="13" height="13" viewBox="0 0 14 14" fill="none"><path d="M9 11L4 7l5-4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>
        ${backLabel}
      </button>
      <div class="rp-command-identity">
        <div class="rp-command-avatar">${_p5Initials(clientName)}</div>
        <span class="rp-command-name">${escapeHtml(clientName)}</span>
        <div class="rp-command-meta">
          <span class="inv-badge ${badgeClass}" style="font-size:10px;padding:2px 8px">${badgeLabel}</span>
          <span style="font-size:12px;font-weight:700;color:var(--gw-action)">${_p5Money(totalDue)}</span>
        </div>
      </div>
      <div class="rp-command-actions">
        ${status!=='paid'?`<button class="rp-btn rp-btn--primary" style="padding:6px 13px;font-size:12.5px;background:var(--gw-pine-500)" onclick="showToast('Payment recorded','success')">Record Payment</button>`:''}
      </div>
    </div>

    <div style="background:var(--gw-surface);border-bottom:1px solid var(--gw-border);padding:0 24px">
      <div class="inv-header-band" style="border-bottom:none;padding-left:0;padding-right:0">
        <div class="inv-number">${invNum}</div>
        <div class="inv-title">Invoice — ${escapeHtml(clientName)}</div>
        <div class="inv-meta-row">
          <span class="inv-badge ${badgeClass}">${badgeLabel}</span>
          <span>Issued ${_p5FmtDate(opp?opp.createdAt:new Date().toISOString())}</span>
          <span>Due ${_p5FmtDate(opp?opp.nextFollowUp:new Date(Date.now()+30*86400000).toISOString())}</span>
          <span>Rep: ${escapeHtml(repName)}</span>
        </div>
      </div>
    </div>

    <div class="inv-body">
      <div class="inv-parties-grid">
        <div class="inv-party-block">
          <div class="inv-party-label">Bill To</div>
          <div class="inv-party-name">${escapeHtml(clientName)}</div>
          ${opp&&opp.address?`<div class="inv-party-detail">${escapeHtml(opp.address)}</div>`:''}
          ${opp&&opp.email?`<div class="inv-party-detail">${escapeHtml(opp.email)}</div>`:''}
          ${opp&&opp.phone?`<div class="inv-party-detail">${escapeHtml(opp.phone)}</div>`:''}
        </div>
        <div class="inv-party-block">
          <div class="inv-party-label">From</div>
          <div class="inv-party-name">Groundwork</div>
          <div class="inv-party-detail">${escapeHtml(repName)}</div>
          <div class="inv-party-detail">Invoice #${invNum}</div>
        </div>
      </div>

      <div class="inv-section-head">Line Items</div>
      <table class="inv-line-table">
        <thead><tr><th>Description</th><th style="text-align:center;width:60px">Qty</th><th style="width:130px">Unit Price</th><th style="width:130px">Total</th></tr></thead>
        <tbody>
          <tr><td><div style="font-weight:600">${escapeHtml(opp?.serviceLine||opp?.project||'Professional Services')}</div></td><td style="text-align:center">1</td><td>${_p5Money(jobVal)}</td><td>${_p5Money(jobVal)}</td></tr>
        </tbody>
      </table>
      <div class="inv-totals-col">
        <div class="inv-total-row"><span>Subtotal</span><span>${_p5Money(jobVal)}</span></div>
        <div class="inv-total-row"><span>Tax (0%)</span><span>$0.00</span></div>
        <div class="inv-total-row inv-total-row--grand"><strong>Total Due</strong><strong>${_p5Money(totalDue)}</strong></div>
        <div class="inv-total-row"><span>Amount Paid</span><span style="color:var(--gw-pine-600)">${_p5Money(paidAmt)}</span></div>
        <div class="inv-total-row inv-total-row--balance ${balance<=0?'is-paid':'is-due'}">
          <strong>Balance ${balance<=0?'(Paid)':'Due'}</strong>
          <strong>${_p5Money(Math.abs(balance))}</strong>
        </div>
      </div>

      ${payments.length?`
      <div class="inv-section-head" style="margin-top:28px">Payment History</div>
      <div class="inv-payment-history">
        ${payments.map(p=>`
        <div class="inv-payment-row">
          <div class="inv-payment-row-left">
            <svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="var(--gw-pine-600)" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M2 4l6 6 6-6" transform="rotate(180 8 8)"/><rect x="1" y="4" width="14" height="9" rx="1.5"/></svg>
            ${_p5FmtDate(p.date)} · ${escapeHtml(p.method)}
            ${p.note?`<span style="font-size:11px;color:var(--gw-text-muted)">— ${escapeHtml(p.note)}</span>`:''}
          </div>
          <div class="inv-payment-row-amount">${_p5Money(p.amount)}</div>
        </div>`).join('')}
      </div>`:''}

      <div class="inv-action-bar">
        ${status!=='paid'?`<button class="inv-btn inv-btn--record" onclick="_invRecordPayment('${opp?opp.id:''}')">
          <svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M2 4l6 6 6-6" transform="rotate(180 8 8)"/><rect x="1" y="4" width="14" height="9" rx="1.5"/></svg>
          Record Payment
        </button>`:''}
        <button class="inv-btn inv-btn--send" onclick="_invSend('${opp?opp.id:''}')">
          <svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="1" y="3" width="14" height="10" rx="1.5"/><path d="M1 6l7 4 7-4"/></svg>
          Send Invoice
        </button>
        <button class="inv-btn inv-btn--secondary" onclick="showToast('PDF download coming soon','info')">
          Download PDF
        </button>
        ${opp?`<button class="inv-btn inv-btn--secondary" onclick="show('pipeline','${opp.id}')">View Lead →</button>`:''}
      </div>

      ${opp ? `
      <div class="inv-section-head" style="margin-top:28px">Approvals</div>
      <div id="inv-approval-panel-${opp.id}" style="margin-bottom:8px"></div>` : ''}
    </div>
  </div>`;

  setTimeout(()=>{
    const bar = document.getElementById('rpCommandBar');
    if(!bar) return;
    window.addEventListener('scroll',()=>{ bar.classList.toggle('is-pinned',window.scrollY>60); },{passive:true});
  },100);

  // Wire approval panel
  if (opp && typeof window.gwApproval === 'object') {
    const panelEl = document.getElementById(`inv-approval-panel-${opp.id}`);
    if (panelEl) window.gwApproval.renderPanel(panelEl, 'invoice', opp.id, `INV-${String(opp.id).slice(-4).toUpperCase()} — ${opp.client||'Client'}`);
  }

  // Invoice action handlers
  window._invSend = function(oppId) {
    const o = oppId ? state.opportunities.find(x=>x.id===oppId) : null;
    if (o && typeof window.gwWorkflow === 'object') window.gwWorkflow.communicationSent({ entityType:'invoice', entityId:oppId, entityLabel:`INV for ${o?.client||'Client'}`, type:'invoice_sent', method:'email' });
    if (o && typeof window.gwAudit === 'function') window.gwAudit({ type:'invoice_sent', entityType:'invoice', entityId:oppId, entityLabel:`INV for ${o.client||'Client'}` });
    showToast('Invoice sent via email', 'success');
  };
  window._invRecordPayment = function(oppId) {
    const o = oppId ? state.opportunities.find(x=>x.id===oppId) : null;
    if (o) {
      // Mark as paid
      const prevStatus = o.status;
      o.status = 'Sold / Activation';
      state.opportunities = state.opportunities.map(x=>x.id===oppId?o:x);
      saveState();
      if (typeof window.gwWorkflow === 'object') window.gwWorkflow.depositReceived({ entityType:'invoice', entityId:oppId, entityLabel:`INV for ${o.client||'Client'}`, client:o.client, amount:Number(o.jobValue||0), prevStatus });
      if (typeof window.gwAudit === 'function') window.gwAudit({ type:'payment_recorded', entityType:'invoice', entityId:oppId, entityLabel:`INV for ${o.client||'Client'}`, meta:{ amount:o.jobValue } });
      showToast('Payment recorded — invoice marked paid', 'success');
      invoiceDetail(oppId);
    } else {
      showToast('Payment recorded', 'success');
    }
  };
}
window.invoiceDetail = invoiceDetail;

// ── ACCOUNT STATEMENT ─────────────────────────────────────────────────────
function accountStatement(clientId){
  // Find client opportunities
  const clientOpps = (state.opportunities||[]).filter(o=>{
    if(clientId) return o.id===clientId || (o.clientId&&o.clientId===clientId);
    return true;
  }).slice(0,20);

  const totalContract = clientOpps.reduce((a,o)=>a+Number(o.jobValue||0),0);
  const totalPaid     = clientOpps.filter(o=>o.status==='Sold / Activation').reduce((a,o)=>a+Number(o.jobValue||0),0);
  const totalDue      = totalContract - totalPaid;
  const clientName    = clientId ? (clientOpps[0]?.client||'Client') : 'All Clients';

  // Build table rows from opps
  const rows = clientOpps.length ? clientOpps.map(o=>{
    const st = o.status==='Sold / Activation' ? 'paid' :
               (o.status==='Closed Lost' ? 'declined' :
               (o.jobValue&&Number(o.jobValue)>0 ? 'invoiced' : 'draft'));
    const bdgClass = {paid:'stmt-badge--paid',draft:'stmt-badge--draft',invoiced:'stmt-badge--sent',declined:'stmt-badge--overdue',approved:'stmt-badge--approved'}[st]||'stmt-badge--draft';
    const bdgLabel = {paid:'Paid',draft:'Draft',invoiced:'Invoiced',declined:'Declined',approved:'Approved'}[st]||'Draft';
    return `<tr>
      <td><span class="stmt-doc-link" onclick="show('estimates','${o.id}')">${escapeHtml(o.serviceLine||o.project||'Opportunity')}</span></td>
      <td>${escapeHtml(o.client||'—')}</td>
      <td>${_p5FmtDate(o.createdAt)}</td>
      <td>${_p5Money(o.jobValue)}</td>
      <td>${o.status==='Sold / Activation'?_p5Money(o.jobValue):'$0.00'}</td>
      <td>${o.status!=='Sold / Activation'&&o.jobValue?_p5Money(o.jobValue):'$0.00'}</td>
      <td><span class="stmt-badge ${bdgClass}">${bdgLabel}</span></td>
    </tr>`;
  }).join('') : `<tr><td colspan="7" style="text-align:center;padding:32px;color:var(--gw-text-subtle);font-style:italic">No documents found</td></tr>`;

  view.innerHTML = `
  <div class="stmt-shell">
    <div style="display:flex;align-items:center;gap:10px;margin-bottom:20px">
      <button class="rp-command-back" onclick="show('financialHub')" style="display:inline-flex;align-items:center;gap:5px;padding:6px 12px;border-radius:6px;background:var(--gw-surface);border:1px solid var(--gw-border);font-size:12px;font-weight:600;cursor:pointer;color:var(--gw-text-muted)">
        <svg width="12" height="12" viewBox="0 0 14 14" fill="none"><path d="M9 11L4 7l5-4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>
        Financial Hub
      </button>
    </div>
    <div class="stmt-header">
      <div class="stmt-client-info">
        <div class="stmt-client-name">${escapeHtml(clientName)}</div>
        <div class="stmt-client-meta">Account Statement · as of ${_p5FmtDate(new Date().toISOString())}</div>
      </div>
      <div class="stmt-summary-cards">
        <div class="stmt-sum-card">
          <div class="stmt-sum-card-val">${_p5Money(totalContract)}</div>
          <div class="stmt-sum-card-label">Total Contracted</div>
        </div>
        <div class="stmt-sum-card">
          <div class="stmt-sum-card-val stmt-sum-card-val--paid">${_p5Money(totalPaid)}</div>
          <div class="stmt-sum-card-label">Total Paid</div>
        </div>
        <div class="stmt-sum-card">
          <div class="stmt-sum-card-val ${totalDue>0?'stmt-sum-card-val--due':''}">${_p5Money(totalDue)}</div>
          <div class="stmt-sum-card-label">Outstanding</div>
        </div>
        <div class="stmt-sum-card">
          <div class="stmt-sum-card-val">${clientOpps.length}</div>
          <div class="stmt-sum-card-label">Jobs</div>
        </div>
      </div>
    </div>

    <div class="stmt-filter-bar">
      <button class="stmt-filter-btn active" onclick="window._stmtFilter='all';document.querySelectorAll('.stmt-filter-btn').forEach(b=>b.classList.remove('active'));this.classList.add('active')">All</button>
      <button class="stmt-filter-btn" onclick="window._stmtFilter='open';document.querySelectorAll('.stmt-filter-btn').forEach(b=>b.classList.remove('active'));this.classList.add('active')">Open</button>
      <button class="stmt-filter-btn" onclick="window._stmtFilter='paid';document.querySelectorAll('.stmt-filter-btn').forEach(b=>b.classList.remove('active'));this.classList.add('active')">Paid</button>
      <button class="stmt-filter-btn" onclick="window._stmtFilter='overdue';document.querySelectorAll('.stmt-filter-btn').forEach(b=>b.classList.remove('active'));this.classList.add('active')">Overdue</button>
    </div>

    <div class="stmt-table-wrap">
      <table class="stmt-table">
        <thead><tr>
          <th>Job / Document</th><th>Client</th><th>Date</th>
          <th>Contract</th><th>Paid</th><th>Balance</th><th>Status</th>
        </tr></thead>
        <tbody>${rows}</tbody>
        <tfoot><tr class="stmt-tfoot-row">
          <td colspan="3"><strong>Totals</strong></td>
          <td><strong>${_p5Money(totalContract)}</strong></td>
          <td><strong style="color:var(--gw-pine-600)">${_p5Money(totalPaid)}</strong></td>
          <td><strong style="color:${totalDue>0?'var(--gw-clay-600)':'var(--gw-pine-600)'}">${_p5Money(totalDue)}</strong></td>
          <td></td>
        </tr></tfoot>
      </table>
    </div>
  </div>`;
}
window.accountStatement = accountStatement;

// ── COMMUNICATIONS BOARD ──────────────────────────────────────────────────
function communicationsBoard(){
  const allComms = (state.communications||[]).sort((a,b)=>new Date(b.ts)-new Date(a.ts));
  const TYPE_ICON = {
    sms:      `<svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M2 2h12a1 1 0 011 1v8a1 1 0 01-1 1H5l-3 3V3a1 1 0 011-1z"/></svg>`,
    email:    `<svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="1" y="3" width="14" height="10" rx="1.5"/><path d="M1 6l7 4 7-4"/></svg>`,
    call:     `<svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 2a1 1 0 011-1h2l1 3-1.5 1.5a9 9 0 004 4L11 8l3 1v2a1 1 0 01-1 1C6 12 4 5 3 3.5V2z"/></svg>`,
    note:     `<svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 1h8a1 1 0 011 1v10l-3 3H4a1 1 0 01-1-1V2a1 1 0 011-1z"/><path d="M5 5h6M5 8h4"/></svg>`,
    proposal: `<svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 1h8a1 1 0 011 1v12a1 1 0 01-1 1H4a1 1 0 01-1-1V2a1 1 0 011-1z"/><path d="M5 5h6M5 8h6M5 11h4"/></svg>`
  };
  const fmtDate = d=>{ try{ return new Date(d).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}); }catch(e){ return ''; } };

  const cards = allComms.length ? allComms.map(m=>{
    const opp = state.opportunities.find(o=>o.id===m.oppId);
    const clientName = opp ? (opp.client||'Unknown') : 'Unknown Client';
    const preview = (m.subject||m.body||'(no content)').slice(0,120);
    const iconCls = `comms-card-icon comms-card-icon--${m.type||'note'}`;
    return `
    <div class="comms-card" onclick="window._leadTab='comms';show('pipeline','${m.oppId}')">
      <div class="comms-card-head">
        <div class="${iconCls}">${TYPE_ICON[m.type]||TYPE_ICON.note}</div>
        <div class="comms-card-meta">
          <div class="comms-card-client">${escapeHtml(clientName)}</div>
          <div class="comms-card-sub">${opp?escapeHtml(opp.status||''):'Opportunity not found'}</div>
        </div>
        <div class="comms-card-time">${fmtDate(m.ts)}</div>
      </div>
      <div class="comms-card-preview">${escapeHtml(preview)}</div>
      <div class="comms-card-footer">
        <span class="comms-card-type-badge">${(m.type||'note').toUpperCase()}</span>
        <span class="comms-card-dir">${m.direction==='out'?'↑ Sent':'↓ Received'}</span>
      </div>
    </div>`;
  }).join('') : `
    <div class="comms-empty">
      <div class="comms-empty-icon">
        <svg width="18" height="18" viewBox="0 0 16 16" fill="none" stroke="var(--gw-text-muted)" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M2 2h12a1 1 0 011 1v8a1 1 0 01-1 1H5l-3 3V3a1 1 0 011-1z"/></svg>
      </div>
      <div style="font-weight:700;font-size:14px;color:var(--gw-text);margin-bottom:6px">No communications yet</div>
      <div>Communications will appear here as you log calls, SMS, and emails from lead records.</div>
    </div>`;

  // Type filter counts
  const counts = ['all','sms','email','call','note','proposal'].reduce((a,t)=>({...a,[t]:t==='all'?allComms.length:allComms.filter(m=>m.type===t).length}),{});

  view.innerHTML = `
  <div class="comms-shell">
    <div class="comms-header">
      <div>
        <div class="comms-title">Communications</div>
        <div style="font-size:13px;color:var(--gw-text-muted);margin-top:2px">${allComms.length} total message${allComms.length!==1?'s':''}</div>
      </div>
      <div class="comms-actions">
        <button class="comms-btn comms-btn--secondary" onclick="show('pipeline')">
          <svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M2 4h3v8H2zM6.5 2h3v12h-3zM11 6h3v6h-3z"/></svg>
          Pipeline
        </button>
      </div>
    </div>

    <div class="comms-filter-bar">
      <input class="comms-search" type="text" placeholder="Search communications…" oninput="window._commsSearch=this.value.toLowerCase();window._commsRender&&window._commsRender()">
      ${['all','sms','email','call','note','proposal'].map(t=>`
        <button class="comms-type-tab${t==='all'?' active':''}" data-type="${t}"
          onclick="document.querySelectorAll('.comms-type-tab').forEach(b=>b.classList.remove('active'));this.classList.add('active');window._commsType='${t}';window._commsRender&&window._commsRender()">
          ${t.charAt(0).toUpperCase()+t.slice(1)}${counts[t]>0?` <span style="opacity:.7">(${counts[t]})</span>`:''}
        </button>`).join('')}
    </div>

    <div class="comms-grid" id="commsGrid">
      ${cards}
    </div>
  </div>`;

  // Live filter
  window._commsType   = 'all';
  window._commsSearch = '';
  window._commsRender = function(){
    const filtered = allComms.filter(m=>{
      const typeOk = window._commsType==='all' || m.type===window._commsType;
      const srch   = window._commsSearch;
      if(!srch) return typeOk;
      const opp    = state.opportunities.find(o=>o.id===m.oppId);
      const hay    = ((opp?.client||'')+(m.subject||'')+(m.body||'')).toLowerCase();
      return typeOk && hay.includes(srch);
    });
    const grid = document.getElementById('commsGrid');
    if(!grid) return;
    if(!filtered.length){
      grid.innerHTML = `<div class="comms-empty"><div>No results match your filters</div></div>`;
      return;
    }
    grid.innerHTML = filtered.map(m=>{
      const opp = state.opportunities.find(o=>o.id===m.oppId);
      const clientName = opp ? (opp.client||'Unknown') : 'Unknown Client';
      const preview = (m.subject||m.body||'(no content)').slice(0,120);
      const iconCls = `comms-card-icon comms-card-icon--${m.type||'note'}`;
      const fmtD = d=>{ try{ return new Date(d).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}); }catch(e){ return ''; } };
      return `
      <div class="comms-card" onclick="window._leadTab='comms';show('pipeline','${m.oppId}')">
        <div class="comms-card-head">
          <div class="${iconCls}">${TYPE_ICON[m.type]||TYPE_ICON.note}</div>
          <div class="comms-card-meta">
            <div class="comms-card-client">${escapeHtml(clientName)}</div>
            <div class="comms-card-sub">${opp?escapeHtml(opp.status||''):''}</div>
          </div>
          <div class="comms-card-time">${fmtD(m.ts)}</div>
        </div>
        <div class="comms-card-preview">${escapeHtml(preview)}</div>
        <div class="comms-card-footer">
          <span class="comms-card-type-badge">${(m.type||'note').toUpperCase()}</span>
          <span class="comms-card-dir">${m.direction==='out'?'↑ Sent':'↓ Received'}</span>
        </div>
      </div>`;
    }).join('');
  };
}
window.communicationsBoard = communicationsBoard;

// ── AUTOMATION MANAGER ────────────────────────────────────────────────────
function automationManager(){
  const defaultRules = [
    {
      id:'auto-1', active:true,
      name:'New Lead Welcome SMS',
      desc:'Sends a welcome SMS to the client within 5 minutes of a new lead being created.',
      trigger:'New Lead Created', action:'Send SMS', delay:'5 min',
      runCount:47, lastRun: new Date(Date.now()-3600000).toISOString()
    },
    {
      id:'auto-2', active:true,
      name:'Follow-Up Reminder',
      desc:'Notifies the assigned rep when a follow-up date passes without contact logged.',
      trigger:'Follow-up Overdue', action:'Notify Rep', delay:'1 day',
      runCount:23, lastRun: new Date(Date.now()-86400000).toISOString()
    },
    {
      id:'auto-3', active:false,
      name:'Estimate Approval Email',
      desc:'Sends a thank-you email when an estimate is marked Approved.',
      trigger:'Estimate Approved', action:'Send Email', delay:'Immediate',
      runCount:12, lastRun: new Date(Date.now()-5*86400000).toISOString()
    },
    {
      id:'auto-4', active:false,
      name:'Deposit Received Confirmation',
      desc:'Sends a receipt confirmation when a deposit payment is recorded.',
      trigger:'Payment Recorded (Deposit)', action:'Send Email + SMS', delay:'Immediate',
      runCount:8, lastRun: new Date(Date.now()-10*86400000).toISOString()
    },
    {
      id:'auto-5', active:true,
      name:'Job Completion Survey',
      desc:'Sends a satisfaction survey 24 hours after a job is marked Sold / Activation.',
      trigger:'Status → Sold/Activation', action:'Send Survey Email', delay:'24 hrs',
      runCount:31, lastRun: new Date(Date.now()-2*86400000).toISOString()
    },
    {
      id:'auto-6', active:false,
      name:'Invoice Overdue Alert',
      desc:'Sends a payment reminder when an invoice is 7 days past due.',
      trigger:'Invoice Overdue (7 days)', action:'Send Email', delay:'7 days',
      runCount:5, lastRun: new Date(Date.now()-15*86400000).toISOString()
    }
  ];

  const fmtDate = d=>{ try{ return new Date(d).toLocaleDateString(undefined,{month:'short',day:'numeric'}); }catch(e){ return ''; } };
  const activeRules = defaultRules.filter(r=>r.active);

  const ruleCards = defaultRules.map(r=>`
    <div class="auto-rule-card auto-rule-card--${r.active?'active':'inactive'}" id="auto-card-${r.id}">
      <div class="auto-rule-toggle">
        <div class="auto-toggle-wrap" onclick="window._autoToggle('${r.id}',this)">
          <div class="auto-toggle-track${r.active?' on':''}">
            <div class="auto-toggle-knob"></div>
          </div>
        </div>
      </div>
      <div class="auto-rule-body">
        <div class="auto-rule-name">${escapeHtml(r.name)}</div>
        <div class="auto-rule-desc">${escapeHtml(r.desc)}</div>
        <div class="auto-rule-chips">
          <span class="auto-rule-chip auto-rule-chip--trigger">${gwIcon('lightning',11)} ${escapeHtml(r.trigger)}</span>
          <span class="auto-rule-chip auto-rule-chip--action">${gwIcon('arrow_right',11)} ${escapeHtml(r.action)}</span>
          <span class="auto-rule-chip auto-rule-chip--delay">${gwIcon('clock',11)} ${escapeHtml(r.delay)}</span>
          <span class="auto-rule-chip">${r.runCount} runs · last ${fmtDate(r.lastRun)}</span>
        </div>
      </div>
      <div class="auto-rule-actions">
        <button class="auto-rule-btn" onclick="showToast('Edit automation coming soon','info')">Edit</button>
        <button class="auto-rule-btn" onclick="showToast('Automation history coming soon','info')">History</button>
      </div>
    </div>`).join('');

  view.innerHTML = `
  <div class="auto-shell">
    <div class="auto-header">
      <div>
        <div class="auto-title">Automation Manager</div>
        <div class="auto-title-sub">${activeRules.length} of ${defaultRules.length} automations active</div>
      </div>
      <div style="display:flex;gap:8px">
        <button class="auto-btn auto-btn--secondary" onclick="showToast('Automation templates coming soon','info')">Browse Templates</button>
        <button class="auto-btn auto-btn--primary" onclick="showToast('New automation builder coming soon','info')">
          <svg width="13" height="13" viewBox="0 0 14 14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M7 1v12M1 7h12"/></svg>
          New Automation
        </button>
      </div>
    </div>

    <div class="auto-tab-bar">
      <button class="auto-tab active" onclick="document.querySelectorAll('.auto-tab').forEach(b=>b.classList.remove('active'));this.classList.add('active')">All Rules</button>
      <button class="auto-tab" onclick="document.querySelectorAll('.auto-tab').forEach(b=>b.classList.remove('active'));this.classList.add('active')">Active (${activeRules.length})</button>
      <button class="auto-tab" onclick="document.querySelectorAll('.auto-tab').forEach(b=>b.classList.remove('active'));this.classList.add('active')">Inactive (${defaultRules.length-activeRules.length})</button>
      <button class="auto-tab" onclick="document.querySelectorAll('.auto-tab').forEach(b=>b.classList.remove('active'));this.classList.add('active')">Run History</button>
    </div>

    <div id="autoRulesContainer">
      ${ruleCards}
    </div>
  </div>`;

  // Toggle handler
  window._autoToggle = function(ruleId, wrap){
    const track = wrap.querySelector('.auto-toggle-track');
    const card  = document.getElementById('auto-card-'+ruleId);
    if(!track||!card) return;
    const wasOn = track.classList.contains('on');
    track.classList.toggle('on', !wasOn);
    card.className = `auto-rule-card auto-rule-card--${!wasOn?'active':'inactive'}`;
    showToast(`Automation ${!wasOn?'enabled':'disabled'}`, !wasOn?'success':'info');
  };
}
window.automationManager = automationManager;

// ── FINANCIAL HUB ─────────────────────────────────────────────────────────
function financialHub(){
  const opps = state.opportunities || [];

  // KPIs
  const totalPipeline  = opps.reduce((a,o)=>a+Number(o.jobValue||0),0);
  const totalSold      = opps.filter(o=>o.status==='Sold / Activation').reduce((a,o)=>a+Number(o.jobValue||0),0);
  const totalOpen      = opps.filter(o=>!['Sold / Activation','Closed Lost'].includes(o.status)).reduce((a,o)=>a+Number(o.jobValue||0),0);
  const estimatesOpen  = opps.filter(o=>!['Sold / Activation','Closed Lost'].includes(o.status)&&Number(o.jobValue||0)>0).length;

  // Recent deals (last 5 sold)
  const recentSold = opps.filter(o=>o.status==='Sold / Activation')
    .sort((a,b)=>new Date(b.closedDate||b.createdAt)-new Date(a.closedDate||a.createdAt))
    .slice(0,5);

  // Open estimates (top 5 by value)
  const openEstimates = opps.filter(o=>!['Sold / Activation','Closed Lost'].includes(o.status)&&Number(o.jobValue||0)>0)
    .sort((a,b)=>Number(b.jobValue)-Number(a.jobValue))
    .slice(0,5);

  // Outstanding (any open opp with a value)
  const outstanding = opps.filter(o=>o.status!=='Sold / Activation'&&o.status!=='Closed Lost'&&Number(o.jobValue||0)>0)
    .sort((a,b)=>Number(b.jobValue)-Number(a.jobValue)).slice(0,5);

  const soldRows = recentSold.length
    ? recentSold.map(o=>`<tr>
        <td><span class="fhub-link" onclick="show('pipeline','${o.id}')">${escapeHtml(o.client||'—')}</span></td>
        <td>${escapeHtml(o.serviceLine||o.project||'—')}</td>
        <td style="text-align:right;font-weight:700;color:var(--gw-pine-600)">${_p5Money(o.jobValue)}</td>
        <td>${_p5FmtDate(o.closedDate||o.createdAt)}</td>
      </tr>`).join('')
    : `<tr><td colspan="4" style="text-align:center;padding:20px;color:var(--gw-text-subtle);font-style:italic">No closed deals yet</td></tr>`;

  const estRows = openEstimates.length
    ? openEstimates.map(o=>`<tr>
        <td><span class="fhub-link" onclick="show('estimates','${o.id}')">${escapeHtml(o.client||'—')}</span></td>
        <td>${escapeHtml(o.status||'—')}</td>
        <td style="text-align:right;font-weight:700;color:var(--gw-action)">${_p5Money(o.jobValue)}</td>
        <td><button class="fhub-link" onclick="show('estimates','${o.id}')" style="background:none;border:none;font-size:inherit;font-weight:700;color:var(--gw-action);cursor:pointer">View →</button></td>
      </tr>`).join('')
    : `<tr><td colspan="4" style="text-align:center;padding:20px;color:var(--gw-text-subtle);font-style:italic">No open estimates</td></tr>`;

  view.innerHTML = `
  <div class="fhub-shell">
    <div class="fhub-header">
      <div class="fhub-title">Financial Hub</div>
      <div class="fhub-subtitle">Overview of pipeline value, estimates, invoices, and payments</div>
    </div>

    <!-- Quick Navigation Cards -->
    <div class="fhub-quick-nav">
      <div class="fhub-nav-card" onclick="accountStatement()">
        <div class="fhub-nav-card-icon">
          <svg width="18" height="18" viewBox="0 0 16 16" fill="none" stroke="var(--gw-pine-600)" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 1h8a1 1 0 011 1v12a1 1 0 01-1 1H4a1 1 0 01-1-1V2a1 1 0 011-1z"/><path d="M5 5h6M5 8h6M5 11h4"/></svg>
        </div>
        <div class="fhub-nav-card-label">Account Statements</div>
        <div class="fhub-nav-card-sub">View all client docs</div>
      </div>
      <div class="fhub-nav-card" onclick="show('communications')">
        <div class="fhub-nav-card-icon" style="background:var(--gw-teal-100)">
          <svg width="18" height="18" viewBox="0 0 16 16" fill="none" stroke="var(--gw-teal-600)" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M2 2h12a1 1 0 011 1v8a1 1 0 01-1 1H5l-3 3V3a1 1 0 011-1z"/></svg>
        </div>
        <div class="fhub-nav-card-label">Communications</div>
        <div class="fhub-nav-card-sub">All client messages</div>
      </div>
      <div class="fhub-nav-card" onclick="show('automations')">
        <div class="fhub-nav-card-icon" style="background:var(--gw-sand-100)">
          <svg width="18" height="18" viewBox="0 0 16 16" fill="none" stroke="var(--gw-sand-700)" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="8" cy="8" r="5"/><path d="M8 5v3l2 1.5"/></svg>
        </div>
        <div class="fhub-nav-card-label">Automations</div>
        <div class="fhub-nav-card-sub">Manage triggers</div>
      </div>
      <div class="fhub-nav-card" onclick="show('revenueAdmin')">
        <div class="fhub-nav-card-icon" style="background:var(--gw-clay-100)">
          <svg width="18" height="18" viewBox="0 0 16 16" fill="none" stroke="var(--gw-clay-700)" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M2 11l4-4 3 3 5-6"/><circle cx="8" cy="8" r="7"/></svg>
        </div>
        <div class="fhub-nav-card-label">Revenue Analytics</div>
        <div class="fhub-nav-card-sub">Full financial data</div>
      </div>
    </div>

    <!-- KPI Row -->
    <div class="fhub-kpi-row">
      <div class="fhub-kpi-card">
        <div class="fhub-kpi-label">Total Pipeline</div>
        <div class="fhub-kpi-val">${_p5Money(totalPipeline)}</div>
        <div class="fhub-kpi-delta">${opps.length} opportunities</div>
      </div>
      <div class="fhub-kpi-card">
        <div class="fhub-kpi-label">Closed / Collected</div>
        <div class="fhub-kpi-val fhub-kpi-val--positive">${_p5Money(totalSold)}</div>
        <div class="fhub-kpi-delta fhub-kpi-delta--up">${opps.filter(o=>o.status==='Sold / Activation').length} sold</div>
      </div>
      <div class="fhub-kpi-card">
        <div class="fhub-kpi-label">Open Value</div>
        <div class="fhub-kpi-val fhub-kpi-val--warning">${_p5Money(totalOpen)}</div>
        <div class="fhub-kpi-delta">${estimatesOpen} open jobs</div>
      </div>
      <div class="fhub-kpi-card">
        <div class="fhub-kpi-label">Conversion Rate</div>
        <div class="fhub-kpi-val">${opps.length>0?Math.round((opps.filter(o=>o.status==='Sold / Activation').length/opps.length)*100):0}%</div>
        <div class="fhub-kpi-delta">Close rate</div>
      </div>
    </div>

    <!-- Panels — full tables on desktop, compact cards on mobile -->
    ${window.innerWidth <= 768 ? `
    <div class="fhub-mobile-panels">
      <div class="fhub-mobile-section-head">Recent Closed Deals <button class="fhub-mobile-see-all" onclick="show('pipeline')">See all</button></div>
      ${recentSold.length ? recentSold.map(o=>`
        <div class="fhub-mobile-row" onclick="show('pipeline','${o.id}')">
          <span class="fhub-mobile-row-name">${escapeHtml(o.client||'—')}</span>
          <span class="fhub-mobile-row-val" style="color:var(--gw-pine,#4D8A86)">${_p5Money(o.jobValue)}</span>
        </div>`).join('') : `<div class="fhub-mobile-empty">No closed deals yet</div>`}
      <div class="fhub-mobile-section-head" style="margin-top:14px">Open Estimates <button class="fhub-mobile-see-all" onclick="show('estimates')">See all</button></div>
      ${openEstimates.length ? openEstimates.map(o=>`
        <div class="fhub-mobile-row" onclick="show('estimates','${o.id}')">
          <span class="fhub-mobile-row-name">${escapeHtml(o.client||'—')}</span>
          <span class="fhub-mobile-row-val">${_p5Money(o.jobValue)}</span>
        </div>`).join('') : `<div class="fhub-mobile-empty">No open estimates</div>`}
    </div>` : `
    <div class="fhub-section-grid">
      <div class="fhub-panel">
        <div class="fhub-panel-head">
          <div class="fhub-panel-title">Recent Closed Deals</div>
          <span class="fhub-panel-link" onclick="show('pipeline')">All Pipeline →</span>
        </div>
        <div class="fhub-panel-body">
          <table class="fhub-table">
            <thead><tr><th>Client</th><th>Job</th><th style="text-align:right">Value</th><th>Closed</th></tr></thead>
            <tbody>${soldRows}</tbody>
          </table>
        </div>
      </div>
      <div class="fhub-panel">
        <div class="fhub-panel-head">
          <div class="fhub-panel-title">Open Estimates</div>
          <span class="fhub-panel-link" onclick="show('pipeline')">All Estimates →</span>
        </div>
        <div class="fhub-panel-body">
          <table class="fhub-table">
            <thead><tr><th>Client</th><th>Stage</th><th style="text-align:right">Value</th><th></th></tr></thead>
            <tbody>${estRows}</tbody>
          </table>
        </div>
      </div>
    </div>`}

    <!-- Outstanding Balances — hidden on mobile, replaced by quick link cards -->
    ${window.innerWidth > 768 ? `
    <div class="fhub-panel" style="margin-bottom:24px">
      <div class="fhub-panel-head">
        <div class="fhub-panel-title">Outstanding — Needs Attention</div>
        <span class="fhub-panel-link" onclick="accountStatement()">Full Statement →</span>
      </div>
      <div class="fhub-panel-body">
        <table class="fhub-table">
          <thead><tr><th>Client</th><th>Job Type</th><th>Stage</th><th style="text-align:right">Value</th><th>Follow-Up</th></tr></thead>
          <tbody>
            ${outstanding.length ? outstanding.map(o=>`<tr>
              <td><span class="fhub-link" onclick="show('pipeline','${o.id}')">${escapeHtml(o.client||'—')}</span></td>
              <td>${escapeHtml(o.serviceLine||o.project||'—')}</td>
              <td>${escapeHtml(o.status||'—')}</td>
              <td style="text-align:right;font-weight:700;color:var(--gw-action)">${_p5Money(o.jobValue)}</td>
              <td style="color:${o.nextFollowUp&&o.nextFollowUp<window.todayISO()?'var(--gw-clay-600)':'var(--gw-text-muted)'}">${_p5FmtDate(o.nextFollowUp)}</td>
            </tr>`).join('')
            : `<tr><td colspan="5" style="text-align:center;padding:20px;color:var(--gw-text-subtle);font-style:italic">No outstanding items</td></tr>`}
          </tbody>
        </table>
      </div>
    </div>` : `
    <div class="fhub-mobile-links">
      <button class="fhub-mobile-link-btn" onclick="show('pipeline')">View Full Pipeline →</button>
      <button class="fhub-mobile-link-btn" onclick="accountStatement()">Account Statements →</button>
      <button class="fhub-mobile-link-btn" onclick="show('invoices')">Invoices →</button>
    </div>`}
  </div>`;
}
window.financialHub = financialHub;

// ─── PHASE 6: OPERATIONS HUB SCREENS ────────────────────────────────────────

// ── Shared helpers ────────────────────────────────────────────────────────────
function _p6WOStatusClass(s) {
  return { scheduled:'wo-status--scheduled', 'in-progress':'wo-status--inprogress',
    completed:'wo-status--completed', cancelled:'wo-status--cancelled',
    hold:'wo-status--hold', 'on-hold':'wo-status--onhold' }[s] || 'wo-status--scheduled';
}
function _p6WOStatusLabel(s) {
  const _T = (typeof window._t === 'function') ? window._t : (x => x);
  return { scheduled:_T('Scheduled'),'in-progress':_T('In Progress'),completed:_T('Completed'),
    cancelled:_T('Cancelled'), hold:_T('Hold — awaiting acceptance'), 'on-hold':_T('On Hold') }[s] || s || _T('Scheduled');
}
// Traffic-light dot for schedule cards: yellow = hold (pre-acceptance),
// green = confirmed/scheduled, red = cancelled/declined.
function _p6WOTrafficDot(s) {
  const color = s === 'hold' ? '#EAB308' : (s === 'cancelled' ? '#DC2626' : (s === 'completed' ? '#16A34A' : (s === 'in-progress' ? '#2563EB' : '#22C55E')));
  const title = s === 'hold' ? 'HOLD — waiting for the client to accept the estimate' : (s === 'cancelled' ? 'Cancelled / declined' : 'Confirmed');
  return `<span class="sb-traffic-dot" title="${title}" style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${color};flex:0 0 auto;${s==='hold' ? 'box-shadow:0 0 0 3px rgba(234,179,8,.25);animation:sbHoldPulse 1.8s ease-in-out infinite' : ''}"></span>`;
}
window._p6WOTrafficDot = _p6WOTrafficDot;
function _p6AssetLabel(s) {
  return { active:'Active', idle:'Idle', maintenance:'In Maintenance',
    retired:'Retired', rented:'Rented Out', pending:'Pending',
    'out-of-service':'Out of Service' }[s] || s || 'Active';
}
function _p6InvtLabel(s) {
  return { ok:'In Stock','low-stock':'Low Stock','out-of-stock':'Out of Stock',
    reorder:'Reorder Now', discontinued:'Discontinued',
    'on-order':'On Order', reserved:'Reserved' }[s] || s || 'In Stock';
}
function _p6ReadinessLabel(s) {
  return { ready:'Ready','not-ready':'Not Ready','partial':'Partial Ready',
    loading:'Loading','en-route':'En Route','on-site':'On Site',
    'wrapping-up':'Wrapping Up',completed:'Completed',
    cancelled:'Cancelled',delayed:'Delayed' }[s] || s || 'Ready';
}
function _p6FreqLabel(f) {
  return { weekly:'Weekly', biweekly:'Bi-Weekly', monthly:'Monthly',
    bimonthly:'Bi-Monthly', quarterly:'Quarterly',
    semiannual:'Semi-Annual', annual:'Annual' }[f] || f || '—';
}
function _p6WONum(wo) {
  return wo.woNumber || ('WO-' + String(wo.id || '').slice(-5).padStart(5,'0'));
}
function _p6AssetCat(c) {
  return { vehicle:'Vehicle', trailer:'Trailer', equipment:'Equipment',
    tool:'Tool', tech:'Technology', other:'Other' }[c] || c || '—';
}

// ── 1. Operations Hub landing ─────────────────────────────────────────────────
function opsHub() {
  const R = window.GW && window.GW.record;
  const wos    = state.workOrders     || [];
  const assets = state.assets         || [];
  const inv    = state.inventory      || [];
  const plans  = state.recurringPlans || [];
  const maint  = state.maintenance    || [];

  const openWOs      = wos.filter(w => w.status === 'scheduled' || w.status === 'in-progress').length;
  const inProgressWO = wos.filter(w => w.status === 'in-progress').length;
  const dueToday     = wos.filter(w => w.date && w.date.slice(0,10) === new Date().toISOString().slice(0,10)).length;
  const lowInv       = inv.filter(i => Number(i.onHand||0) <= Number(i.reorderAt||0)).length;
  const overdueMaint = maint.filter(m => !m.completedDate && m.dueDate && m.dueDate < new Date().toISOString().slice(0,10)).length;
  const activePlans  = plans.filter(p => p.status === 'active').length;
  const idleAssets   = assets.filter(a => a.status === 'idle').length;

  const statsHtml = R ? R.OpsStatusBar([
    { val: openWOs,      label: 'Open WOs',        accent: 'action',   filter: 'workOrderList' },
    { val: inProgressWO, label: 'In Progress',      accent: 'accent3',  filter: 'dispatchBoard' },
    { val: dueToday,     label: 'Due Today',        accent: 'accent2',  filter: 'scheduleBoard' },
    { val: activePlans,  label: 'Active Plans',     accent: 'emerald',  filter: 'recurringServices' },
    { val: lowInv,       label: 'Low Inventory',    accent: 'amber',    filter: 'inventoryList', delta: lowInv > 0 ? '!' : '' },
    { val: overdueMaint, label: 'Overdue Maint.',   accent: 'red',      filter: 'maintenanceQueue', delta: overdueMaint > 0 ? '!' : '' },
    { val: idleAssets,   label: 'Idle Assets',      accent: 'text-muted', filter: 'assetList' },
  ]) : '';

  const recentWOs = wos.slice(-5).reverse().map(wo => `
    <div class="wo-row" onclick="show('workOrderDetail','${wo.id}')" style="cursor:pointer">
      <span class="wo-number">${_p6WONum(wo)}</span>
      <span class="wo-client">${escapeHtml(wo.clientName||wo.oppId||'—')}</span>
      <span class="wo-type">${escapeHtml(wo.type||'Service')}</span>
      <span><span class="ops-ready-badge ${_p6WOStatusClass(wo.status)}">${_p6WOStatusLabel(wo.status)}</span></span>
      <span class="wo-date">${wo.date ? _p5FmtDate(wo.date) : '—'}</span>
    </div>`).join('') || '<p style="padding:16px;color:var(--gw-text-muted);font-style:italic">No work orders yet. <button class="rp-btn-sm" onclick="show(\'workOrderList\')">Create First WO</button></p>';

  const duePlans = plans.filter(p => p.status === 'active').slice(0,5).map(p => `
    <div class="recur-row" onclick="show('recurringServices')" style="cursor:pointer">
      <span class="recur-client">${escapeHtml(p.clientName||p.clientId||'—')}</span>
      <span class="recur-freq">${_p6FreqLabel(p.freq)}</span>
      <span class="recur-next">${p.nextVisit ? _p5FmtDate(p.nextVisit) : '—'}</span>
      <span class="recur-crew">${escapeHtml(p.crew||'Unassigned')}</span>
    </div>`).join('') || '<p style="padding:12px 0;color:var(--gw-text-muted);font-style:italic">No active recurring plans.</p>';

  view.innerHTML = `
  <div class="ops-hub-wrap">
    <header class="rp-header">
      <div class="rp-header-left">
        <h1 class="rp-title">Operations Hub</h1>
        <p class="rp-subtitle">Scheduling · Dispatch · Work Orders · Assets · Inventory</p>
      </div>
      <div class="rp-header-actions">
        <button class="rp-btn" onclick="show('scheduleBoard')">
          <svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="2" y="3" width="12" height="11" rx="1.5"/><path d="M5 1v3M11 1v3M2 7h12"/></svg>
          Schedule
        </button>
        <button class="rp-btn" onclick="show('dispatchBoard')">
          <svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="8" cy="8" r="6"/><path d="M8 4v4l3 2"/></svg>
          Dispatch
        </button>
        <button class="rp-btn rp-btn--primary" onclick="show('workOrderList')">
          <svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 1h8a1 1 0 011 1v12a1 1 0 01-1 1H4a1 1 0 01-1-1V2a1 1 0 011-1z"/><path d="M5 5h6M5 8h6M5 11h3"/></svg>
          + Work Order
        </button>
      </div>
    </header>

    <div style="max-width:1200px;margin:0 auto;padding:16px 24px 0">${statsHtml}</div>

    <div class="ops-hub-grid" style="max-width:1200px;margin:0 auto;padding:20px 24px;display:grid;grid-template-columns:1fr 1fr;gap:20px">

      <!-- Work Orders panel -->
      <div class="rp-card" style="grid-column:1/-1">
        <div class="rp-card-head">
          <span class="rp-card-title">Recent Work Orders</span>
          <button class="rp-btn-sm" onclick="show('workOrderList')">View All</button>
        </div>
        <div class="wo-list-shell" style="padding:0">
          ${recentWOs}
        </div>
      </div>

      <!-- Recurring plans panel -->
      <div class="rp-card">
        <div class="rp-card-head">
          <span class="rp-card-title">Active Recurring Plans</span>
          <button class="rp-btn-sm" onclick="show('recurringServices')">View All</button>
        </div>
        <div style="padding:4px 0">
          <div style="display:grid;grid-template-columns:1fr auto auto auto;gap:8px;padding:4px 0 8px;border-bottom:1px solid var(--gw-border)">
            <span style="font-size:10px;font-weight:700;color:var(--gw-text-muted);text-transform:uppercase;letter-spacing:.05em">Client</span>
            <span style="font-size:10px;font-weight:700;color:var(--gw-text-muted);text-transform:uppercase;letter-spacing:.05em">Freq</span>
            <span style="font-size:10px;font-weight:700;color:var(--gw-text-muted);text-transform:uppercase;letter-spacing:.05em">Next Visit</span>
            <span style="font-size:10px;font-weight:700;color:var(--gw-text-muted);text-transform:uppercase;letter-spacing:.05em">Crew</span>
          </div>
          ${duePlans}
        </div>
      </div>

      <!-- Quick links panel -->
      <div class="rp-card">
        <div class="rp-card-head">
          <span class="rp-card-title">Operations Quick Links</span>
        </div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:8px 0">
          ${[
            ['scheduleBoard',     'Schedule Board',    'M2 4h12v2H2zM2 8h12v2H2zM2 12h8v2H2z'],
            ['dispatchBoard',     'Dispatch Board',    'M8 2a6 6 0 100 12A6 6 0 008 2zM8 6v4l2.5 1.5'],
            ['recurringServices', 'Recurring Services','M3 8a5 5 0 0110 0M8 5v3l2 1'],
            ['workOrderList',     'Work Orders',       'M4 1h8a1 1 0 011 1v12a1 1 0 01-1 1H4a1 1 0 01-1-1V2a1 1 0 011-1zM5 5h6M5 8h6M5 11h3'],
            ['assetList',         'Assets',            'M2 12V6l6-4 6 4v6l-6 4-6-4z'],
            ['maintenanceQueue',  'Maintenance',       'M8 2a6 6 0 100 12M8 5v3l2 1.5'],
            ['inventoryList',     'Inventory',         'M2 4h12v10H2zM5 4V2h6v2M6 8h4M6 11h2'],
            ['timeTracker',       'Time Tracker',      'M8 4v4l2.5 1.5M8 1a7 7 0 100 14A7 7 0 008 1z'],
          ].map(([view, label, path]) => `
            <button class="rp-btn" style="justify-content:flex-start;gap:8px" onclick="show('${view}')">
              <svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.7"><path d="${path}"/></svg>
              <span style="font-size:12px">${label}</span>
            </button>`).join('')}
        </div>
      </div>

    </div>
  </div>`;
}
window.opsHub = opsHub;

// ── 2. Schedule Board ─────────────────────────────────────────────────────────
// ── Schedule Board State ──────────────────────────────────────────────────────
window._sbState = window._sbState || {
  viewMode: 'week',        // 'week' | 'month' | 'crew'
  weekOffset: 0,
  monthOffset: 0,
  hiddenCrews: new Set(),
  crews: [],
  workOrders: [],
  loaded: false,
  crewLanes: true,         // show crew-lane rows in week view
};

async function _sbLoadData() {
  try {
    // Field roles only see their assigned crew — pass rep_id to filter server-side
    const _sbRep = window._d1SessionRep || (window.getCurrentRep ? window.getCurrentRep() : null);
    const _sbFieldRoles = window._GW_FIELD_ROLES || ['foreman','laborer','field_supervisor'];
    const _sbIsField = _sbRep && _sbFieldRoles.includes(_sbRep.role);
    const _woUrl = _sbIsField
      ? `/api/work-orders?limit=500&rep_id=${encodeURIComponent(_sbRep.id)}`
      : '/api/work-orders?limit=500';
    const [cr, wo] = await Promise.all([
      fetch('/api/crews', {credentials:'include'}).then(r=>r.json()),
      fetch(_woUrl, {credentials:'include'}).then(r=>r.json()),
    ]);
    if (cr.ok) {
      // Field roles: only show their own crew(s) in the crew filter bar
      if (_sbIsField && _sbRep) {
        window._sbState.crews = (cr.data || []).filter(crew =>
          crew.members && crew.members.some(m => m.id === _sbRep.id || m.rep_id === _sbRep.id)
        );
        // If no crew memberships found, show all crews anyway (graceful fallback)
        if (window._sbState.crews.length === 0) window._sbState.crews = cr.data || [];
      } else {
        window._sbState.crews = cr.data || [];
      }
    }
    if (wo.ok)  window._sbState.workOrders = wo.data  || [];
    window._sbState.loaded = true;
  } catch(e) {
    console.warn('[scheduleBoard] API load failed, using localStorage fallback', e);
    // Fallback: convert localStorage workOrders to D1 shape
    window._sbState.workOrders = (state.workOrders||[]).map(w=>({
      id:w.id, wo_number:w.woNumber||w.id,
      client_name:w.clientName||'', type:w.type||'Service',
      status:w.status||'scheduled', readiness:w.readiness||'ready',
      scheduled_date:w.date||null, scheduled_time:w.time||null,
      notes:w.notes||'', crew_id:null, crew_name:w.crew||'',
      crew_color:'#94a3b8', checklist:w.checklist||[], materials:w.materials||[],
    }));
    window._sbState.loaded = true;
  }
}

function _sbGetWeekDays(offset) {
  const today = new Date();
  const sunday = new Date(today);
  sunday.setDate(today.getDate() - today.getDay() + offset*7); // snap to Sunday
  return Array.from({length:7}, (_,i) => {
    const d = new Date(sunday); d.setDate(sunday.getDate()+i); return d;
  });
}

function _sbGetMonthDays(offset) {
  const now = new Date();
  const y = now.getFullYear(), m = now.getMonth() + offset;
  const first = new Date(y, m, 1);
  const last  = new Date(y, m+1, 0);
  return { first, last, month: first.toLocaleDateString('en-US',{month:'long',year:'numeric'}) };
}

function _sbCrewPill(crew) {
  if (!crew) return '';
  const c = crew.crew_color || crew.color || '#94a3b8';
  return `<span class="sb-crew-pill" style="background:${c}20;color:${c};border-color:${c}40">${escapeHtml(crew.crew_name||crew.name||'')}</span>`;
}

function _sbJobCard(wo, crews, draggable) {
  const crew = crews.find(c=>c.id===wo.crew_id);
  const crewColor = wo.crew_color || (crew?.color) || '#94a3b8';
  const statusCls = _p6WOStatusClass(wo.status);
  const timeStr = wo.scheduled_time ? wo.scheduled_time.slice(0,5) : '';
  const endStr  = wo.scheduled_end_time ? ' – '+wo.scheduled_end_time.slice(0,5) : '';
  const hrs = wo.duration_hours ? `${wo.duration_hours}h` : '';
  return `
    <div class="sb-job-card ${statusCls}" style="border-left:3px solid ${crewColor}"
        ${draggable ? `draggable="true" ondragstart="_sbDragStart(event,'${wo.id}')" ondragend="this.style.opacity=''"` : ''}
        onclick="_sbOpenVisitModal('${wo.id}')">
      <div class="sb-card-top">
        <span class="sb-card-drag-handle" title="Drag to reschedule">
          <svg width="10" height="14" viewBox="0 0 10 14" fill="currentColor" opacity=".45">
            <circle cx="3" cy="2" r="1.3"/><circle cx="7" cy="2" r="1.3"/>
            <circle cx="3" cy="7" r="1.3"/><circle cx="7" cy="7" r="1.3"/>
            <circle cx="3" cy="12" r="1.3"/><circle cx="7" cy="12" r="1.3"/>
          </svg>
        </span>
        ${_p6WOTrafficDot(wo.status)}
        <span class="sb-card-num">${wo.wo_number||wo.id}</span>
        ${timeStr ? `<span class="sb-card-time">${timeStr}${endStr}</span>` : ''}
      </div>
      <div class="sb-card-client">${escapeHtml(wo.client_name||wo.title||'Job')}</div>
      ${crew||wo.crew_name ? `<div class="sb-card-crew" style="color:${crewColor}">${escapeHtml(wo.crew_name||crew?.name||'')}</div>` : ''}
      <div class="sb-card-meta">
        <span class="sb-card-type">${escapeHtml(wo.type||'Service')}</span>
        ${hrs ? `<span class="sb-card-hrs">${hrs}</span>` : ''}
      </div>
      <span class="sb-card-status ops-ready-badge ${statusCls}">${_p6WOStatusLabel(wo.status)}</span>
    </div>`;
}

async function scheduleBoard() {
  const sb = window._sbState;

  // Show loading skeleton
  view.innerHTML = `<div class="sched-shell"><div style="padding:40px;text-align:center;color:var(--gw-text-muted)">
    <div class="sb-spinner"></div><p style="margin-top:12px">${(typeof window._t==='function')?window._t('Loading schedule…'):'Loading schedule…'}</p></div></div>`;

  if (!sb.loaded) await _sbLoadData();
  _sbRender();
}

function _sbRender() {
  const sb = window._sbState;
  const today = new Date().toISOString().slice(0,10);
  const allCrews = sb.crews;
  const allWOs   = sb.workOrders;

  // Crew filter bar (toggle visibility per crew)
  const crewFilterBar = `
    <div class="sb-crew-bar">
      <div class="sb-crew-bar-chips">
        ${allCrews.length ? allCrews.map(cr=>{
          const active = !sb.hiddenCrews.has(cr.id);
          return `<button class="sb-crew-toggle${active?' active':''}" style="--crew-color:${cr.color}"
            onclick="_sbToggleCrew('${cr.id}')" title="${escapeHtml(cr.name)}">
            <span class="sb-crew-dot" style="background:${cr.color}"></span>
            ${escapeHtml(cr.name)}
            ${cr.members?.length ? `<span class="sb-crew-count">${cr.members.length}</span>` : ''}
          </button>`;
        }).join('') : `<span style="font-size:12px;color:var(--gw-text-muted)">No crews yet.</span>`}
      </div>
      <div class="sb-crew-bar-actions">
        ${sb.viewMode==='week' ? `<button class="sb-crew-lane-btn${sb.crewLanes?' active':''}" onclick="_sbToggleCrewLanes()" title="Toggle crew-lane rows">
          <svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="1" y="2" width="14" height="3" rx="1"/><rect x="1" y="7" width="14" height="3" rx="1"/><rect x="1" y="12" width="14" height="3" rx="1"/></svg>
          Crew Lanes
        </button>` : ''}
        <button class="sb-crew-manage-btn" onclick="show('userManagement','crews')">
          <svg width="12" height="12" viewBox="0 0 16 16" fill="currentColor"><path d="M8 4a1 1 0 011 1v2h2a1 1 0 010 2H9v2a1 1 0 01-2 0V9H5a1 1 0 010-2h2V5a1 1 0 011-1z"/></svg>
          Manage Crews
        </button>
      </div>
    </div>`;

  // Filter WOs by visible crews
  const visibleWOs = allWOs.filter(wo => {
    if (!wo.crew_id) return true;
    return !sb.hiddenCrews.has(wo.crew_id);
  });

  let gridHtml = '';
  let headerLabel = '';

  const _sbT = (typeof window._t === 'function') ? window._t : (x => x);
  if (sb.viewMode === 'week') {
    const days = _sbGetWeekDays(sb.weekOffset);
    const wdNames = [_sbT('Sun'),_sbT('Mon'),_sbT('Tue'),_sbT('Wed'),_sbT('Thu'),_sbT('Fri'),_sbT('Sat')];
    headerLabel = `${days[0].toLocaleDateString('en-US',{month:'short',day:'numeric'})} – ${days[6].toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}`;

    if (sb.crewLanes && allCrews.length) {
      // ── Crew-Lane week view ──────────────────────────────────────────────────
      // ONE unified grid: header row + one row per crew. All cells share column
      // widths and row heights automatically because they are in the same grid.

      // Unassigned + each visible crew
      const laneCrews = [
        { id:'__unassigned__', name:'Unassigned', color:'#94a3b8' },
        ...allCrews.filter(c=>!sb.hiddenCrews.has(c.id))
      ];

      // Header cells (corner + 7 day heads)
      const headerCells = `
        <div class="sb-lane-corner"></div>
        ${days.map(d=>{
          const iso = d.toISOString().slice(0,10);
          const isToday = iso===today;
          return `<div class="sb-lane-day-head${isToday?' today':''}">
            <span class="sb-day-name">${wdNames[d.getDay()]}</span>
            <span class="sb-day-date">${d.getDate()}</span>
          </div>`;
        }).join('')}`;

      // One label + 7 cells per crew row — all flat inside the single grid
      const crewCells = laneCrews.map(cr=>{
        const isUnassigned = cr.id==='__unassigned__';
        const dayCells = days.map(d=>{
          const iso = d.toISOString().slice(0,10);
          const isToday = iso===today;
          const jobs = isUnassigned
            ? visibleWOs.filter(w => (!w.crew_id) && w.scheduled_date?.slice(0,10)===iso)
            : visibleWOs.filter(w => w.crew_id===cr.id && w.scheduled_date?.slice(0,10)===iso);
          return `<div class="sb-lane-cell${isToday?' today':''}"
              data-date="${iso}" data-crew="${cr.id}"
              ondragover="event.preventDefault();this.classList.add('drag-over')"
              ondragleave="this.classList.remove('drag-over')"
              ondrop="_sbDropOnCell(event,'${iso}','${cr.id}')">
            ${jobs.map(wo=>_sbJobCard(wo,allCrews,true)).join('')}
            <button class="sb-lane-add-btn" onclick="_sbOpenNewVisit('${iso}','${isUnassigned?'':cr.id}')">+</button>
          </div>`;
        }).join('');
        return `
          <div class="sb-lane-label" style="border-left:3px solid ${cr.color}">
            <span class="sb-lane-crew-dot" style="background:${cr.color}"></span>
            <span class="sb-lane-crew-name">${escapeHtml(cr.name)}</span>
          </div>
          ${dayCells}`;
      }).join('');

      gridHtml = `<div class="sb-lane-wrap"><div class="sb-lane-grid">${headerCells}${crewCells}</div></div>`;

    } else {
      // ── Standard column week view ────────────────────────────────────────────
      const cols = days.map(d => {
        const iso = d.toISOString().slice(0,10);
        const isToday = iso === today;
        const jobs = visibleWOs.filter(w => w.scheduled_date && w.scheduled_date.slice(0,10) === iso);
        return `
          <div class="sb-day-col${isToday?' sb-day-col--today':''}"
              data-date="${iso}"
              ondragover="event.preventDefault();this.querySelector('.sb-day-body').classList.add('drag-over')"
              ondragleave="this.querySelector('.sb-day-body').classList.remove('drag-over')"
              ondrop="_sbDropOnCell(event,'${iso}',null)">
            <div class="sb-day-head">
              <span class="sb-day-name">${wdNames[d.getDay()]}</span>
              <span class="sb-day-date">${d.getDate()}</span>
              ${jobs.length ? `<span class="sb-day-count">${jobs.length}</span>` : ''}
            </div>
            <div class="sb-day-body">
              ${jobs.map(wo => _sbJobCard(wo, allCrews, true)).join('') || '<div class="sb-empty-day">No jobs</div>'}
              <button class="sb-add-btn" onclick="_sbOpenNewVisit('${iso}',null)">+</button>
            </div>
          </div>`;
      });
      gridHtml = `<div class="sb-week-grid">${cols.join('')}</div>`;
    }

  } else {
    // ── Month view ─────────────────────────────────────────────────────────────
    const { first, last, month } = _sbGetMonthDays(sb.monthOffset);
    headerLabel = month;
    const startDow = first.getDay();
    const totalDays = last.getDate();
    let cells = '';
    for (let i=0;i<startDow;i++) cells += `<div class="sb-month-cell sb-month-cell--blank"></div>`;
    for (let d=1;d<=totalDays;d++) {
      const iso = `${first.getFullYear()}-${String(first.getMonth()+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
      const isToday = iso === today;
      const jobs = visibleWOs.filter(w => w.scheduled_date && w.scheduled_date.slice(0,10) === iso);
      const dots = jobs.slice(0,5).map(wo => {
        // Traffic-light month dots: yellow = hold, red = cancelled, otherwise crew color
        const dotColor = wo.status === 'hold' ? '#EAB308' : (wo.status === 'cancelled' ? '#DC2626' : (wo.crew_color || allCrews.find(c=>c.id===wo.crew_id)?.color || '#94a3b8'));
        return `<span class="sb-month-dot${wo.status==='hold' ? ' sb-month-dot--hold' : ''}" style="background:${dotColor}" title="${escapeHtml(wo.client_name||wo.wo_number)}${wo.status==='hold' ? ' — HOLD (awaiting acceptance)' : ''}"></span>`;
      }).join('');
      cells += `
        <div class="sb-month-cell${isToday?' sb-month-cell--today':''}"
            data-date="${iso}"
            ondragover="event.preventDefault();this.classList.add('drag-over')"
            ondragleave="this.classList.remove('drag-over')"
            ondrop="_sbDropOnCell(event,'${iso}',null)"
            onclick="_sbOpenNewVisit('${iso}',null)">
          <div class="sb-month-num">${d}</div>
          ${jobs.length ? `<div class="sb-month-dots">${dots}${jobs.length>5?`<span class="sb-month-more">+${jobs.length-5}</span>`:''}</div>` : ''}
          ${jobs.slice(0,3).map(wo=>{
            const crewColor = wo.status === 'hold' ? '#EAB308' : (wo.crew_color || allCrews.find(c=>c.id===wo.crew_id)?.color || '#94a3b8');
            return `<div class="sb-month-chip${wo.status==='hold' ? ' sb-month-chip--hold' : ''}" style="border-left:2px solid ${crewColor}" onclick="event.stopPropagation();_sbOpenVisitModal('${wo.id}')">
              ${_p6WOTrafficDot(wo.status)} ${escapeHtml((wo.client_name||wo.title||'Job').slice(0,20))}
            </div>`;
          }).join('')}
          ${jobs.length>3 ? `<div class="sb-month-more-link">+${jobs.length-3} more</div>` : ''}
        </div>`;
    }
    const _sbT2 = (typeof window._t === 'function') ? window._t : (x => x);
    const dowHeaders = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(n=>`<div class="sb-month-dow">${_sbT2(n)}</div>`).join('');
    gridHtml = `<div class="sb-month-grid">${dowHeaders}${cells}</div>`;
  }

  // Stats bar
  const totalScheduled  = visibleWOs.filter(w=>w.status==='scheduled').length;
  const totalHolds      = visibleWOs.filter(w=>w.status==='hold').length;
  const totalInProgress = visibleWOs.filter(w=>w.status==='in-progress').length;
  const totalCompleted  = visibleWOs.filter(w=>w.status==='completed').length;

  // ── Mobile layout (≤768px): day-list view ────────────────────────────────
  if (window.innerWidth <= 768) {
    _sbRenderMobile(sb, visibleWOs, allCrews, allWOs, totalScheduled, totalInProgress, totalCompleted, headerLabel, gridHtml, crewFilterBar);
    return;
  }

  view.innerHTML = `
  <div class="sched-shell">
    <div class="gwp-shell" style="padding-bottom:0">
      <header class="gwp-header" style="margin-bottom:14px">
        <div class="gwp-header-left">
          <h1 class="gwp-title">Schedule</h1>
          <div class="sb-nav-controls">
            <button class="sb-nav-btn" onclick="_sbNav(-1)">‹</button>
            <span class="sb-period-label">${headerLabel}</span>
            <button class="sb-nav-btn" onclick="_sbNav(1)">›</button>
            <button class="gwp-chip" onclick="_sbGoToday()">Today</button>
          </div>
        </div>
        <div class="gwp-header-actions">
          <div class="sb-view-toggle">
            <button class="sb-view-btn${sb.viewMode==='week'?' active':''}" onclick="_sbSetView('week')">Week</button>
            <button class="sb-view-btn${sb.viewMode==='month'?' active':''}" onclick="_sbSetView('month')">Month</button>
          </div>
          <button class="gwp-btn-ghost" onclick="show('dispatchBoard')">Dispatch</button>
          <button class="gwp-btn-primary" onclick="_sbOpenNewVisit(null,null)">+ Work Order</button>
        </div>
      </header>

      <div class="gwp-kpi-row${totalHolds ? ' gwp-kpi-row--5' : ''}" style="margin-bottom:14px">
        <div class="gwp-kpi-card gwp-kpi-card--blue">
          <div class="gwp-kpi-icon gwp-kpi-icon--blue"><svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="2" y="3" width="12" height="11" rx="1.5"/><path d="M2 6.5h12M5.5 1.5v3M10.5 1.5v3"/></svg></div>
          <div class="gwp-kpi-body"><div class="gwp-kpi-value">${totalScheduled}</div><div class="gwp-kpi-label">Scheduled</div></div>
        </div>
        ${totalHolds ? `<div class="gwp-kpi-card gwp-kpi-card--yellow" title="Jobs held on the calendar — waiting for the client to accept the estimate">
          <div class="gwp-kpi-icon gwp-kpi-icon--yellow"><span style="width:10px;height:10px;border-radius:50%;background:#EAB308;display:inline-block"></span></div>
          <div class="gwp-kpi-body"><div class="gwp-kpi-value">${totalHolds}</div><div class="gwp-kpi-label">Holds</div><div class="gwp-kpi-sub">awaiting acceptance</div></div>
        </div>` : ''}
        <div class="gwp-kpi-card">
          <div class="gwp-kpi-icon gwp-kpi-icon--purple"><svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="8" cy="8" r="7"/><path d="M8 4v4l3 2"/></svg></div>
          <div class="gwp-kpi-body"><div class="gwp-kpi-value">${totalInProgress}</div><div class="gwp-kpi-label">In Progress</div></div>
        </div>
        <div class="gwp-kpi-card gwp-kpi-card--green">
          <div class="gwp-kpi-icon gwp-kpi-icon--green"><svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M2 8l4 4 8-8"/></svg></div>
          <div class="gwp-kpi-body"><div class="gwp-kpi-value">${totalCompleted}</div><div class="gwp-kpi-label">Completed</div></div>
        </div>
        <div class="gwp-kpi-card gwp-kpi-card--muted">
          <div class="gwp-kpi-icon gwp-kpi-icon--muted"><svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="5.5" cy="5" r="2.5"/><circle cx="11" cy="6" r="2"/><path d="M1.5 13.5c0-2.2 1.8-4 4-4s4 1.8 4 4M9.5 13.5c0-1.9 1.3-3.2 3-3.2 1.2 0 2.2.6 2.7 1.6"/></svg></div>
          <div class="gwp-kpi-body"><div class="gwp-kpi-value">${allCrews.length}</div><div class="gwp-kpi-label">Crews</div></div>
        </div>
      </div>
    </div>

    ${crewFilterBar}

    <div class="sb-grid-wrap">
      ${gridHtml}
    </div>
  </div>`;
}

window.scheduleBoard = scheduleBoard;
window._sbNav = function(dir) {
  const sb = window._sbState;
  if (sb.viewMode==='week') sb.weekOffset += dir; else sb.monthOffset += dir;
  // reset selected day to first day of new week when navigating
  if (sb.viewMode === 'week') {
    const days = _sbGetWeekDays(sb.weekOffset);
    sb.mobileSelectedDay = days[0].toISOString().slice(0,10);
  }
  _sbRender();
};
window._sbGoToday = function() {
  window._sbState.weekOffset = 0; window._sbState.monthOffset = 0;
  window._sbState.mobileSelectedDay = new Date().toISOString().slice(0,10);
  _sbRender();
};
window._sbSetView = function(v) { window._sbState.viewMode = v; _sbRender(); };
window._sbToggleCrew = function(id) {
  const sb = window._sbState;
  if (sb.hiddenCrews.has(id)) sb.hiddenCrews.delete(id); else sb.hiddenCrews.add(id);
  _sbRender();
};
window._sbRefresh = async function() {
  window._sbState.loaded = false;
  await _sbLoadData();
  _sbRender();
};
window._sbSelectDay = function(iso) {
  window._sbState.mobileSelectedDay = iso;
  _sbRender();
};

// ── Mobile schedule render ────────────────────────────────────────────────────
function _sbRenderMobile(sb, visibleWOs, allCrews, allWOs, totalScheduled, totalInProgress, totalCompleted, headerLabel, _gridHtml, _crewFilterBar) {
  const today = new Date().toISOString().slice(0,10);
  const _mT = (typeof window._t === 'function') ? window._t : (x => x);
  const wdNames = [_mT('Sun'),_mT('Mon'),_mT('Tue'),_mT('Wed'),_mT('Thu'),_mT('Fri'),_mT('Sat')];
  const wdShort = ['S','M','T','W','T','F','S'];

  // Month view on mobile — use a compact grid
  if (sb.viewMode === 'month') {
    const { first, last, month } = _sbGetMonthDays(sb.monthOffset);
    const startDow = first.getDay();
    const totalDays = last.getDate();
    let cells = '';
    for (let i=0;i<startDow;i++) cells += `<div class="sbm-month-blank"></div>`;
    for (let d=1;d<=totalDays;d++) {
      const iso = `${first.getFullYear()}-${String(first.getMonth()+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
      const isToday = iso === today;
      const isSelected = iso === (sb.mobileSelectedDay || today);
      const jobs = visibleWOs.filter(w => w.scheduled_date?.slice(0,10) === iso);
      cells += `<button class="sbm-month-day${isToday?' is-today':''}${isSelected?' is-selected':''}" onclick="_sbSelectDay('${iso}')">
        <span class="sbm-month-num">${d}</span>
        ${jobs.length ? `<span class="sbm-month-dot-row">${jobs.slice(0,3).map(wo=>{
          const c = wo.crew_color || allCrews.find(cr=>cr.id===wo.crew_id)?.color || '#94a3b8';
          return `<span style="width:5px;height:5px;border-radius:50%;background:${c};display:inline-block"></span>`;
        }).join('')}${jobs.length>3?`<span style="font-size:8px;color:var(--gw-text-muted)">+</span>`:''}</span>` : ''}
      </button>`;
    }
    const dowHeaders = wdShort.map(n=>`<div class="sbm-month-dow">${n}</div>`).join('');

    // Day detail panel for selected day
    const selDay = sb.mobileSelectedDay || today;
    const selJobs = visibleWOs.filter(w => w.scheduled_date?.slice(0,10) === selDay);
    const selDate = new Date(selDay + 'T12:00:00');
    const selLabel = selDate.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'});

    view.innerHTML = `
    <div class="sched-shell sbm-shell">
      <!-- Compact header -->
      <div class="sbm-header">
        <div class="sbm-header-row1">
          <div class="sbm-title-nav">
            <button class="sbm-nav-btn" onclick="_sbNav(-1)">‹</button>
            <span class="sbm-period">${month}</span>
            <button class="sbm-nav-btn" onclick="_sbNav(1)">›</button>
          </div>
          <div class="sbm-header-actions">
            <button class="sbm-today-btn" onclick="_sbGoToday()">Today</button>
            <button class="sbm-new-btn" onclick="_sbOpenNewVisit(null,null)">+ New</button>
          </div>
        </div>
        <div class="sbm-view-strip">
          <button class="sbm-view-btn" onclick="_sbSetView('week')">Week</button>
          <button class="sbm-view-btn active" onclick="_sbSetView('month')">Month</button>
          <button class="sbm-view-btn" onclick="show('dispatchBoard')">Dispatch</button>
        </div>
      </div>

      <!-- Month grid -->
      <div class="sbm-month-grid">
        ${dowHeaders}
        ${cells}
      </div>

      <!-- Selected day jobs -->
      <div class="sbm-day-panel">
        <div class="sbm-day-panel-head">
          <span class="sbm-day-panel-label">${selLabel}</span>
          <button class="sbm-add-day-btn" onclick="_sbOpenNewVisit('${selDay}',null)">+ Add</button>
        </div>
        ${selJobs.length
          ? selJobs.map(wo => _sbMobileJobCard(wo, allCrews)).join('')
          : `<div class="sbm-empty">No jobs scheduled</div>`
        }
      </div>

      <!-- Crew chips scroll -->
      <div class="sbm-crew-strip">
        ${allCrews.map(cr=>{
          const active = !sb.hiddenCrews.has(cr.id);
          return `<button class="sbm-crew-chip${active?' active':''}" style="--cc:${cr.color}" onclick="_sbToggleCrew('${cr.id}')">
            <span class="sbm-crew-dot" style="background:${cr.color}"></span>${escapeHtml(cr.name)}
          </button>`;
        }).join('')}
      </div>
    </div>`;
    return;
  }

  // ── Week view on mobile: day-strip + single-day list ──────────────────────
  const days = _sbGetWeekDays(sb.weekOffset);
  headerLabel = `${days[0].toLocaleDateString('en-US',{month:'short',day:'numeric'})} – ${days[6].toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}`;

  // Determine selected day
  if (!sb.mobileSelectedDay) {
    // Auto-select today if in current week, else first day
    const todayInWeek = days.find(d=>d.toISOString().slice(0,10)===today);
    sb.mobileSelectedDay = todayInWeek ? today : days[0].toISOString().slice(0,10);
  }
  // Ensure selected day is in current week
  const weekIsos = days.map(d=>d.toISOString().slice(0,10));
  if (!weekIsos.includes(sb.mobileSelectedDay)) {
    sb.mobileSelectedDay = weekIsos[0];
  }

  // Day strip: 7 tappable day chips
  const dayStrip = days.map(d => {
    const iso = d.toISOString().slice(0,10);
    const isToday = iso === today;
    const isSelected = iso === sb.mobileSelectedDay;
    const jobCount = visibleWOs.filter(w=>w.scheduled_date?.slice(0,10)===iso).length;
    return `<button class="sbm-day-chip${isToday?' is-today':''}${isSelected?' is-selected':''}" onclick="_sbSelectDay('${iso}')">
      <span class="sbm-chip-wd">${wdShort[d.getDay()]}</span>
      <span class="sbm-chip-date">${d.getDate()}</span>
      ${jobCount ? `<span class="sbm-chip-dot"></span>` : '<span class="sbm-chip-dot sbm-chip-dot--empty"></span>'}
    </button>`;
  }).join('');

  // Jobs for selected day
  const selDay = sb.mobileSelectedDay;
  const selJobs = visibleWOs.filter(w=>w.scheduled_date?.slice(0,10)===selDay);
  const selDate = new Date(selDay + 'T12:00:00');
  const selLabel = selDate.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'});

  // Crew lanes for selected day (if enabled)
  let dayContent = '';
  if (sb.crewLanes && allCrews.length) {
    const laneCrews = [
      { id:'__unassigned__', name:'Unassigned', color:'#94a3b8' },
      ...allCrews.filter(c=>!sb.hiddenCrews.has(c.id))
    ];
    dayContent = laneCrews.map(cr => {
      const isUnassigned = cr.id==='__unassigned__';
      const crewJobs = isUnassigned
        ? selJobs.filter(w=>!w.crew_id)
        : selJobs.filter(w=>w.crew_id===cr.id);
      if (!crewJobs.length && isUnassigned) return ''; // hide empty unassigned lane
      return `<div class="sbm-crew-lane">
        <div class="sbm-crew-lane-head" style="border-left:3px solid ${cr.color}">
          <span class="sbm-crew-lane-dot" style="background:${cr.color}"></span>
          <span class="sbm-crew-lane-name">${escapeHtml(cr.name)}</span>
          <span class="sbm-crew-lane-count">${crewJobs.length} job${crewJobs.length!==1?'s':''}</span>
          <button class="sbm-add-lane-btn" onclick="_sbOpenNewVisit('${selDay}','${isUnassigned?'':cr.id}')">+</button>
        </div>
        ${crewJobs.map(wo=>_sbMobileJobCard(wo,allCrews)).join('') || `<div class="sbm-lane-empty">No jobs</div>`}
      </div>`;
    }).join('');
  } else {
    dayContent = selJobs.length
      ? selJobs.map(wo=>_sbMobileJobCard(wo,allCrews)).join('')
      : `<div class="sbm-empty">No jobs scheduled for this day</div>`;
  }

  // Stat summary — compact single row
  const statSummary = `<div class="sbm-stat-row">
    <span class="sbm-stat-pill">${totalScheduled} scheduled</span>
    ${totalInProgress ? `<span class="sbm-stat-pill sbm-stat-pill--blue">${totalInProgress} in progress</span>` : ''}
    ${totalCompleted ? `<span class="sbm-stat-pill sbm-stat-pill--green">${totalCompleted} done</span>` : ''}
    <span class="sbm-stat-pill sbm-stat-pill--muted">${allCrews.length} crew${allCrews.length!==1?'s':''}</span>
  </div>`;

  view.innerHTML = `
  <div class="sched-shell sbm-shell">
    <!-- Compact mobile header -->
    <div class="sbm-header">
      <div class="sbm-header-row1">
        <div class="sbm-title-nav">
          <h1 class="sbm-title">Schedule</h1>
          <button class="sbm-nav-btn" onclick="_sbNav(-1)">‹</button>
          <span class="sbm-period">${headerLabel}</span>
          <button class="sbm-nav-btn" onclick="_sbNav(1)">›</button>
        </div>
        <div class="sbm-header-actions">
          <button class="sbm-today-btn" onclick="_sbGoToday()">Today</button>
          <button class="sbm-new-btn" onclick="_sbOpenNewVisit(null,null)">+ New</button>
        </div>
      </div>

      <!-- View mode strip -->
      <div class="sbm-view-strip">
        <button class="sbm-view-btn active" onclick="_sbSetView('week')">Week</button>
        <button class="sbm-view-btn" onclick="_sbSetView('month')">Month</button>
        <button class="sbm-view-btn" onclick="_sbToggleCrewLanes()" style="${sb.crewLanes?'background:var(--gw-pine-500,#2D7A55);color:#fff;':''}">
          <svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2"><rect x="1" y="2" width="14" height="3" rx="1"/><rect x="1" y="7" width="14" height="3" rx="1"/><rect x="1" y="12" width="14" height="3" rx="1"/></svg>
          Lanes
        </button>
        <button class="sbm-view-btn" onclick="show('dispatchBoard')">Dispatch</button>
      </div>
    </div>

    <!-- Stat summary strip -->
    ${statSummary}

    <!-- Crew filter chips (horizontal scroll) -->
    <div class="sbm-crew-strip">
      ${allCrews.map(cr=>{
        const active = !sb.hiddenCrews.has(cr.id);
        return `<button class="sbm-crew-chip${active?' active':''}" style="--cc:${cr.color}" onclick="_sbToggleCrew('${cr.id}')">
          <span class="sbm-crew-dot" style="background:${cr.color}"></span>${escapeHtml(cr.name)}
          ${cr.members?.length ? `<span class="sbm-crew-cnt">${cr.members.length}</span>` : ''}
        </button>`;
      }).join('')}
      <button class="sbm-crew-chip sbm-crew-chip--manage" onclick="show('userManagement','crews')">+ Manage</button>
    </div>

    <!-- Day selector strip -->
    <div class="sbm-day-strip">
      ${dayStrip}
    </div>

    <!-- Selected day label + add button -->
    <div class="sbm-day-header">
      <span class="sbm-day-label">${selLabel}</span>
      <button class="sbm-add-day-btn" onclick="_sbOpenNewVisit('${selDay}',null)">+ Work Order</button>
    </div>

    <!-- Day content: job cards / crew lanes -->
    <div class="sbm-day-content">
      ${dayContent || `<div class="sbm-empty">No jobs scheduled for this day</div>`}
    </div>

    <!-- Bottom padding for nav bar -->
    <div style="height:80px"></div>
  </div>`;
}

// Mobile job card — more touch-friendly than the desktop card
function _sbMobileJobCard(wo, crews) {
  const crew = crews.find(c=>c.id===wo.crew_id);
  const crewColor = wo.crew_color || (crew?.color) || '#94a3b8';
  const statusCls = _p6WOStatusClass(wo.status);
  const timeStr = wo.scheduled_time ? wo.scheduled_time.slice(0,5) : '';
  const endStr  = wo.scheduled_end_time ? ' – '+wo.scheduled_end_time.slice(0,5) : '';
  return `
  <div class="sbm-job-card ${statusCls}" style="border-left:4px solid ${crewColor}" onclick="_sbOpenVisitModal('${wo.id}')">
    <div class="sbm-job-top">
      ${_p6WOTrafficDot(wo.status)}
      <span class="sbm-job-num">${wo.wo_number||wo.id}</span>
      ${timeStr ? `<span class="sbm-job-time">${timeStr}${endStr}</span>` : ''}
      <span class="sbm-job-status ops-ready-badge ${statusCls}">${_p6WOStatusLabel(wo.status)}</span>
    </div>
    <div class="sbm-job-client">${escapeHtml(wo.client_name||wo.title||'Job')}</div>
    <div class="sbm-job-meta">
      ${crew||wo.crew_name ? `<span style="color:${crewColor};font-weight:600;font-size:12px">${escapeHtml(wo.crew_name||crew?.name||'')}</span>` : ''}
      <span class="sbm-job-type">${escapeHtml(wo.type||'Service')}</span>
      ${wo.duration_hours ? `<span class="sbm-job-dur">${wo.duration_hours}h</span>` : ''}
    </div>
  </div>`;
}

window._sbToggleCrewLanes = function() {
  window._sbState.crewLanes = !window._sbState.crewLanes;
  _sbRender();
};

// ── Drag & Drop ───────────────────────────────────────────────────────────────
// Handle mousedown on drag handle — only starts a real HTML5 drag if the user
// actually moves the mouse (>4px), otherwise it's a click and falls through to
// the card's onclick handler normally.
window._sbDragStart = function(e, woId) {
  e.dataTransfer.setData('text/plain', woId);
  e.dataTransfer.effectAllowed = 'move';
  e.currentTarget.style.opacity = '0.45';
};

window._sbDropOnCell = async function(e, iso, crewId) {
  e.preventDefault();
  document.querySelectorAll('.drag-over').forEach(el=>el.classList.remove('drag-over'));
  const woId = e.dataTransfer.getData('text/plain');
  if (!woId) return;
  // Optimistically update local state
  const wo = window._sbState.workOrders.find(w=>w.id===woId);
  if (!wo) return;
  const oldDate = wo.scheduled_date;
  const oldCrew = wo.crew_id;
  wo.scheduled_date = iso;
  if (crewId && crewId !== '__unassigned__') wo.crew_id = crewId;
  else if (crewId === '__unassigned__') wo.crew_id = null;
  _sbRender();
  // Persist
  try {
    const body = { scheduled_date: iso };
    if (crewId !== null) body.crew_id = crewId === '__unassigned__' ? null : crewId;
    await fetch(`/api/work-orders/${woId}/reschedule`, {
      method:'PATCH', headers:{'Content-Type':'application/json'},
      body: JSON.stringify(body)
    });
    // If crew changed, update via PUT
    if (crewId !== null && crewId !== oldCrew) {
      await fetch(`/api/work-orders/${woId}`, {
        method:'PUT', headers:{'Content-Type':'application/json'},
        body: JSON.stringify({ crew_id: crewId === '__unassigned__' ? null : crewId })
      });
    }
    showToast('Job rescheduled','success');
  } catch(err) {
    // Rollback
    wo.scheduled_date = oldDate;
    wo.crew_id = oldCrew;
    _sbRender();
    showToast('Reschedule failed','error');
  }
};

// ── Duplicate Job ─────────────────────────────────────────────────────────────
window._sbDuplicateJob = async function(woId) {
  const wo = window._sbState.workOrders.find(w=>w.id===woId);
  if (!wo) return;
  // Default: next day
  let nextDate = null;
  if (wo.scheduled_date) {
    const d = new Date(wo.scheduled_date + 'T12:00:00');
    d.setDate(d.getDate() + 1);
    nextDate = d.toISOString().slice(0,10);
  }
  const userDate = prompt('Duplicate to date (YYYY-MM-DD):', nextDate || '');
  if (!userDate) return;
  try {
    const r = await fetch(`/api/work-orders/${woId}/duplicate`, {
      method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ scheduled_date: userDate })
    });
    const d = await r.json();
    if (!d.ok) throw new Error(d.error);
    showToast(`Duplicated → ${d.wo_number}`,'success');
    await _sbRefresh();
  } catch(err) { showToast('Duplicate failed: '+err.message,'error'); }
};

// ── Visit / Work Order Modal ──────────────────────────────────────────────────
window._sbOpenVisitModal = async function(woId) {
  // Remove any stale modal first
  const _existing = document.getElementById('sb-visit-modal');
  if (_existing) _existing.remove();

  let wo = null;
  try {
    const r = await fetch(`/api/work-orders/${woId}`, { credentials: 'include' });
    if (r.ok) {
      const d = await r.json();
      if (d.ok) wo = d.data;
    }
  } catch(e) { console.warn('[_sbOpenVisitModal] fetch error:', e); }
  // Fallback to localStorage
  if (!wo) wo = (state.workOrders||[]).find(w=>w.id===woId);
  if (!wo) {
    // Also check _sbState.workOrders
    wo = (window._sbState?.workOrders||[]).find(w=>w.id===woId);
  }
  if (!wo) { showToast('Work order not found','error'); return; }

  // Normalize JSON columns that may arrive as strings from localStorage fallback
  if (typeof wo.checklist  === 'string') try { wo.checklist  = JSON.parse(wo.checklist);  } catch(e) { wo.checklist  = []; }
  if (typeof wo.materials  === 'string') try { wo.materials  = JSON.parse(wo.materials);  } catch(e) { wo.materials  = []; }
  if (typeof wo.timeline   === 'string') try { wo.timeline   = JSON.parse(wo.timeline);   } catch(e) { wo.timeline   = []; }
  if (typeof wo.before_photos==='string')try{wo.before_photos=JSON.parse(wo.before_photos);}catch(e){wo.before_photos=[];}
  if (typeof wo.after_photos==='string') try{wo.after_photos =JSON.parse(wo.after_photos); }catch(e){wo.after_photos =[];}
  if (typeof wo.attachments==='string')  try{wo.attachments  =JSON.parse(wo.attachments);  }catch(e){wo.attachments  =[];}
  if (typeof wo.equipment  === 'string') try { wo.equipment  = JSON.parse(wo.equipment);  } catch(e) { wo.equipment  = []; }
  if (!Array.isArray(wo.checklist))   wo.checklist   = [];
  if (!Array.isArray(wo.materials))   wo.materials   = [];
  if (!Array.isArray(wo.equipment))   wo.equipment   = [];
  if (!Array.isArray(wo.before_photos))wo.before_photos=[];
  if (!Array.isArray(wo.after_photos)) wo.after_photos =[];
  if (!Array.isArray(wo.attachments))  wo.attachments  =[];
  if (!Array.isArray(wo.employees))    wo.employees    =[];

  const crews   = window._sbState.crews || [];
  const allReps = window._gwAllReps || [];

  const crewOptions = crews.map(c=>`<option value="${c.id}"${wo.crew_id===c.id?' selected':''}>${escapeHtml(c.name)}</option>`).join('');
  const assignedEmpIds = new Set((wo.employees||[]).map(e=>e.rep_id||e));
  const empChips = (wo.employees||[]).map(e=>`
    <span class="sb-emp-chip" data-rep-id="${e.rep_id||e}">
      <span class="sb-emp-dot" style="background:${allReps.find(r=>r.id===(e.rep_id||e))?.color||'#6366f1'}"></span>
      ${escapeHtml(e.name||e.rep_id||e)}
      <button onclick="_sbRemoveEmployee('${e.rep_id||e}')" title="Remove">×</button>
    </span>`).join('');

  const checklistHtml = (wo.checklist||[]).map((item,i)=>`
    <div class="sb-check-item">
      <button class="sb-check-box${item.done?' done':''}" onclick="_sbToggleCheck(${i})">
        ${item.done?'<svg width="10" height="10" viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M2 6l3 3 5-5"/></svg>':''}
      </button>
      <span class="sb-check-label${item.done?' done':''}">${escapeHtml(item.text||'')}</span>
      <button class="sb-check-del" onclick="_sbRemoveCheck(${i})">×</button>
    </div>`).join('');

  const beforePhotos = (wo.before_photos||[]);
  const afterPhotos  = (wo.after_photos||[]);

  const photosHtml = (label, photos, field) => `
    <div class="sb-photo-group">
      <div class="sb-photo-label">${label}</div>
      <div class="sb-photo-row" id="sb-photos-${field}">
        ${photos.map((url,pi)=>`<div class="sb-photo-thumb" data-pi="${pi}" data-field="${field}"><img src="${escapeHtml(url)}" alt="photo"><button onclick="_sbRemovePhoto(this.closest('.sb-photo-thumb').dataset.field,this.closest('.sb-photo-thumb').dataset.pi)">×</button></div>`).join('')}
        <label class="sb-photo-add" title="Add photo">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 5v14M5 12h14"/></svg>
          <input type="file" accept="image/*" style="display:none" onchange="_sbUploadPhoto(event,'${field}')">
        </label>
      </div>
    </div>`;

  // Work tracking
  const budgetedHrs = wo.duration_hours || 0;
  const actualHrs   = wo.actual_hours   || 0;

  const modal = document.createElement('div');
  modal.id = 'sb-visit-modal';
  modal.className = 'sb-modal-overlay';
  try { modal.innerHTML = `
    <div class="sb-modal-panel">
      <div class="sb-modal-header">
        <div class="sb-modal-title-block">
          <span class="sb-modal-wo-num">${wo.wo_number||wo.id}</span>
          <span class="ops-ready-badge ${_p6WOStatusClass(wo.status)}" id="sb-status-badge">${_p6WOStatusLabel(wo.status)}</span>
        </div>
        <div class="sb-modal-header-meta">
          <span>${wo.scheduled_date ? _p5FmtDate(wo.scheduled_date) : 'No date'}</span>
          ${wo.scheduled_time ? `<span> · ${wo.scheduled_time}</span>` : ''}
        </div>
        <button class="sb-modal-close" onclick="_sbCloseModal()">×</button>
      </div>

      <div class="sb-modal-body">
        <!-- Left Col -->
        <div class="sb-modal-left">
          <!-- Visit Info -->
          <section class="sb-modal-section">
            <h3 class="sb-modal-section-title">Visit Details</h3>
            <div class="sb-modal-date-row">
              <label class="sb-modal-field">
                <span>Date</span>
                <input class="rp-input" id="sbm-date" type="date" value="${wo.scheduled_date||''}">
              </label>
              <label class="sb-modal-field">
                <span>Time</span>
                <input class="rp-input" id="sbm-time" type="time" value="${wo.scheduled_time||''}">
              </label>
              <label class="sb-modal-field">
                <span>Status</span>
                <select class="rp-input" id="sbm-status">
                  ${['hold','scheduled','in-progress','completed','on-hold','cancelled'].map(s=>
                    `<option value="${s}"${wo.status===s?' selected':''}>${_p6WOStatusLabel(s)}</option>`).join('')}
                </select>
              </label>
            </div>

            <div class="sb-modal-field" style="margin-top:8px">
              <span>Visit Notes (visible to crew)</span>
              <textarea class="rp-input" id="sbm-notes" rows="3" placeholder="Scope, special instructions…">${escapeHtml(wo.notes||'')}</textarea>
            </div>
          </section>

          <!-- Completion Details -->
          <section class="sb-modal-section">
            <h3 class="sb-modal-section-title">Completion Details</h3>
            <div class="sb-line-items" id="sbm-line-items">
              ${(wo.materials||[]).length ? wo.materials.map((m,i)=>`
                <div class="sb-line-row">
                  <input class="rp-input" value="${escapeHtml(m.name||'')}" placeholder="Item / Service" style="flex:2">
                  <input class="rp-input" value="${m.qty||1}" type="number" min="0" style="width:60px" placeholder="Qty">
                  <input class="rp-input" value="${m.unit||''}" placeholder="Unit" style="width:70px">
                  <input class="rp-input" value="${m.cost||0}" type="number" min="0" placeholder="Rate" style="width:80px">
                  <button class="rp-btn-sm rp-btn-sm--danger" onclick="_sbRemoveLine(${i})">×</button>
                </div>`).join('') : ''}
            </div>
            <div style="display:flex;gap:8px;margin-top:8px">
              <button class="rp-btn-sm" onclick="_sbAddLine()">+ Add Line</button>
              <button class="rp-btn-sm" onclick="_sbAddPackage()">Add Package</button>
            </div>
            <div class="sb-total-row">
              <span>Total</span>
              <span id="sbm-total">$${((wo.amount_est||0)).toFixed(2)}</span>
            </div>
            <div class="sb-modal-field" style="margin-top:8px">
              <span>Completion Notes</span>
              <textarea class="rp-input" id="sbm-completion-notes" rows="2" placeholder="What was done, any issues…">${escapeHtml(wo.completion_notes||'')}</textarea>
            </div>
          </section>

          <!-- Checklist -->
          <section class="sb-modal-section">
            <div class="sb-modal-section-head">
              <h3 class="sb-modal-section-title">Checklist</h3>
              <button class="rp-btn-sm" onclick="_sbAddCheck()">+ Item</button>
            </div>
            <div id="sbm-checklist">${checklistHtml||'<p class="sb-empty-note">No items. Add checklist items above.</p>'}</div>
          </section>
        </div>

        <!-- Right Col -->
        <div class="sb-modal-right">
          <!-- Crew Assignment -->
          <section class="sb-modal-section">
            <h3 class="sb-modal-section-title">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 00-3-3.87M16 3.13a4 4 0 010 7.75"/></svg>
              Crew
            </h3>
            <label class="sb-modal-field">
              <span>Assigned Crew</span>
              <select class="rp-input" id="sbm-crew" onchange="_sbCrewChanged()">
                <option value="">— Unassigned —</option>
                ${crewOptions}
              </select>
            </label>
            <div class="sb-modal-field" style="margin-top:8px">
              <span>Employees on this visit</span>
              <div class="sb-emp-chips" id="sbm-emp-chips">${empChips||'<span class="sb-empty-note">None assigned.</span>'}</div>
              <div class="sb-emp-add-row">
                <select class="rp-input" id="sbm-add-emp-select" style="flex:1">
                  <option value="">+ Add employee…</option>
                  ${allReps.filter(r=>r.active!==false&&r.active!==0).map(r=>
                    `<option value="${r.id}"${assignedEmpIds.has(r.id)?' disabled':''}>
                      ${escapeHtml(r.name)} (${r.role||'rep'})
                    </option>`).join('')}
                </select>
                <button class="rp-btn-sm" onclick="_sbAddEmployee()">Add</button>
              </div>
            </div>
          </section>

          <!-- Materials & Equipment (crew-visible) -->
          <section class="sb-modal-section">
            <div class="sb-modal-section-head">
              <h3 class="sb-modal-section-title">
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 7H4a2 2 0 00-2 2v10a2 2 0 002 2h16a2 2 0 002-2V9a2 2 0 00-2-2z"/><path d="M16 21V5a2 2 0 00-2-2h-4a2 2 0 00-2 2v16"/></svg>
                Materials &amp; Equipment
              </h3>
              <button class="rp-btn-sm" onclick="_sbAddCrewItem()">+ Item</button>
            </div>
            <div id="sbm-equip-list" style="display:flex;flex-direction:column;gap:6px;margin-bottom:8px">
              ${(wo.equipment||[]).length ? wo.equipment.map((eq,i)=>`
                <div class="sb-equip-row" data-idx="${i}" style="display:flex;align-items:center;gap:6px;padding:6px 8px;background:var(--gw-surface-3);border-radius:6px">
                  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14.7 6.3a1 1 0 000 1.4l1.6 1.6a1 1 0 001.4 0l3.77-3.77a6 6 0 01-7.94 7.94l-6.91 6.91a2.12 2.12 0 01-3-3l6.91-6.91a6 6 0 017.94-7.94l-3.76 3.76z"/></svg>
                  <span style="flex:1;font-size:13px">${escapeHtml(typeof eq==='string'?eq:eq.name||'')}</span>
                  <button class="sb-check-del" onclick="_sbRemoveEquipItem(${i})">×</button>
                </div>`).join('') : '<p class="sb-empty-note">No equipment assigned.</p>'}
            </div>
            <div style="display:flex;gap:6px">
              <input class="rp-input" id="sbm-equip-input" placeholder="Truck, skid steer, mower…" style="flex:1">
              <button class="rp-btn-sm" onclick="_sbAddCrewItem()">Add</button>
            </div>
          </section>

          <!-- Photos -->
          <section class="sb-modal-section">
            <h3 class="sb-modal-section-title">Before &amp; After Photos</h3>
            ${photosHtml('Before', beforePhotos, 'before_photos')}
            ${photosHtml('After',  afterPhotos,  'after_photos')}
          </section>

          <!-- Work Tracking -->
          <section class="sb-modal-section">
            <h3 class="sb-modal-section-title">Work Tracking</h3>
            <div class="sb-work-track">
              <div class="sb-work-stat">
                <span class="sb-work-num">${budgetedHrs}h</span>
                <span class="sb-work-lbl">Budgeted</span>
              </div>
              <div class="sb-work-stat">
                <span class="sb-work-num sb-work-num--blue">${actualHrs}h</span>
                <span class="sb-work-lbl">Actual</span>
              </div>
            </div>
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px">
              <label class="sb-modal-field">
                <span>Budgeted Hours <em style="font-size:10px;font-weight:400;opacity:.6">(total man-hrs)</em></span>
                <input class="rp-input" id="sbm-duration" type="number" min="0" step="0.5" value="${budgetedHrs||''}">
              </label>
              <label class="sb-modal-field">
                <span>Scheduled End</span>
                <input class="rp-input" id="sbm-end-time" type="time" value="${wo.scheduled_end_time||''}">
              </label>
            </div>
          </section>

          <!-- Customer / Property -->
          <section class="sb-modal-section">
            <h3 class="sb-modal-section-title">Customer</h3>
            ${wo.client_id || wo.client_name ? `
              <div>
                <button class="sb-client-link" data-cid="${escapeHtml(wo.client_id||'')}" data-cname="${escapeHtml(wo.client_name||'').replace(/"/g,'&quot;')}" onclick="_sbGoToCustomer(this.dataset.cid,this.dataset.cname);_sbCloseModal()" title="Open customer details">
                  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>
                  <strong>${escapeHtml(wo.client_name||'—')}</strong>
                </button>
              </div>` : `<div><strong>—</strong></div>`}
            ${wo.property_addr ? `
              <div style="margin-top:6px">
                <a class="sb-addr-link" href="https://maps.google.com/?q=${encodeURIComponent(wo.property_addr)}" target="_blank" rel="noopener" title="Open in Google Maps">
                  <svg width="11" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z"/></svg>
                  ${escapeHtml(wo.property_addr)}
                </a>
              </div>` : ''}
            ${wo.amount_est ? `<div style="font-size:12px;margin-top:6px">Estimate: <strong>$${Number(wo.amount_est).toFixed(2)}</strong></div>` : ''}
          </section>

          <!-- Attachments (photos + PDFs) -->
          <section class="sb-modal-section">
            <h3 class="sb-modal-section-title">Attachments</h3>
            <div id="sbm-attachments-list" style="display:flex;flex-direction:column;gap:6px;margin-bottom:10px">
              ${(wo.attachments||[]).map((a,i)=>`
                <div class="sb-attach-row" data-idx="${i}">
                  <span class="sb-attach-icon">${a.type==='pdf'?gwIcon('document',14):gwIcon('image',14)}</span>
                  <span class="sb-attach-name" style="flex:1;font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escapeHtml(a.name||'File')}</span>
                  <a href="${escapeHtml(a.url||'#')}" target="_blank" class="rp-btn-sm" style="padding:2px 8px;font-size:11px">View</a>
                  <button class="sb-check-del" onclick="_sbRemoveAttachment(${i})">×</button>
                </div>`).join('') || '<p class="sb-empty-note">No attachments yet.</p>'}
            </div>
            <label class="sb-attach-upload-btn">
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>
              Upload Photo or PDF
              <input type="file" accept="image/*,.pdf" multiple style="display:none" onchange="_sbUploadAttachment(event)">
            </label>
          </section>
        </div>
      </div>

      <!-- Action Bar -->
      <div class="sb-modal-actions">
        <div class="sb-modal-actions-left">
          <button class="sb-action-btn sb-action-skip" onclick="_sbSkipVisit('${wo.id}')">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M5 12h14M12 5l7 7-7 7"/></svg>
            Skip
          </button>
          <button class="sb-action-btn" style="gap:5px" onclick="_sbDuplicateJob('${wo.id}')">
            <svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="5" y="5" width="9" height="9" rx="1.5"/><path d="M3 11V3a1 1 0 011-1h8"/></svg>
            Duplicate
          </button>
          <button class="sb-action-btn sb-action-wo" onclick="show('workOrderDetail','${wo.id}');_sbCloseModal()">
            Work Order
          </button>
          ${wo.opp_id ? `<button class="sb-action-btn sb-action-upsell" onclick="_sbUpsell('${wo.opp_id}')">Up-sell</button>` : ''}
        </div>
        <div class="sb-modal-actions-right">
          <button class="sb-action-btn sb-action-delete" onclick="_sbDeleteVisit('${wo.id}')">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14H6L5 6"/><path d="M10 11v6M14 11v6"/></svg>
            Delete
          </button>
          <button class="rp-btn" onclick="_sbSaveVisit('${wo.id}',false)">Save</button>
          <button class="rp-btn rp-btn--primary" id="sb-complete-btn" onclick="_sbCompleteVisit('${wo.id}','${wo.type||'Service'}')">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 6L9 17l-5-5"/></svg>
            Complete
          </button>
        </div>
      </div>
    </div>`; } catch(renderErr) {
    console.error('[_sbOpenVisitModal] render error:', renderErr, wo);
    showToast('Error opening job — see console for details','error');
    return;
  }

  // Close on backdrop click
  modal.addEventListener('click', function(e) { if (e.target === modal) _sbCloseModal(); });

  document.body.appendChild(modal);

  // Store current WO for handlers
  window._sbCurrentWO = JSON.parse(JSON.stringify(wo));
  window._sbCurrentWOId = wo.id;
};

window._sbCloseModal = function() {
  const m = document.getElementById('sb-visit-modal');
  if (m) m.remove();
  window._sbCurrentWO = null;
};

window._sbSaveVisit = async function(woId, andComplete) {
  // Collect equipment list
  const equipItems = [...document.querySelectorAll('#sbm-equip-list .sb-equip-row')].map(row => {
    return row.querySelector('span')?.textContent?.trim() || '';
  }).filter(Boolean);
  const wo = window._sbCurrentWO || {};
  const body = {
    scheduled_date: document.getElementById('sbm-date')?.value || null,
    scheduled_time: document.getElementById('sbm-time')?.value || null,
    scheduled_end_time: document.getElementById('sbm-end-time')?.value || null,
    status:         document.getElementById('sbm-status')?.value || 'scheduled',
    notes:          document.getElementById('sbm-notes')?.value  || '',
    completion_notes: document.getElementById('sbm-completion-notes')?.value || '',
    crew_id:        document.getElementById('sbm-crew')?.value   || null,
    duration_hours: parseFloat(document.getElementById('sbm-duration')?.value||'0') || null,
    equipment:      equipItems,
    employee_ids:   [...document.querySelectorAll('#sbm-emp-chips .sb-emp-chip')].map(el=>el.dataset.repId).filter(Boolean),
    before_photos:  wo.before_photos || [],
    after_photos:   wo.after_photos  || [],
    attachments:    wo.attachments   || [],
  };
  if (andComplete) body.status = 'completed';
  try {
    const r = await fetch(`/api/work-orders/${woId}`, {
      method:'PUT', credentials:'include', headers:{'Content-Type':'application/json'}, body:JSON.stringify(body)
    });
    const d = await r.json();
    if (!d.ok) throw new Error(d.error);
    showToast(andComplete ? 'Visit completed! Invoice flow next.' : 'Visit saved', 'success');
    _sbCloseModal();
    await _sbRefresh();
    if (andComplete) {
      // Could trigger invoice creation flow here
      setTimeout(()=>showToast('Ready to invoice — use Work Orders > Create Invoice','info'),1500);
    }
  } catch(e) {
    showToast('Save failed: '+e.message,'error');
  }
};

window._sbDeleteVisit = async function(woId) {
  if (!confirm('Delete this work order? This cannot be undone.')) return;
  try {
    await fetch(`/api/work-orders/${woId}`,{method:'DELETE', credentials:'include'});
    showToast('Work order deleted','success');
    _sbCloseModal();
    await _sbRefresh();
  } catch(e) { showToast('Delete failed','error'); }
};

window._sbSkipVisit = function(woId) {
  // Prompt for skip reason via inline modal
  const existing = document.getElementById('sb-skip-reason-modal');
  if (existing) existing.remove();
  const dlg = document.createElement('div');
  dlg.id = 'sb-skip-reason-modal';
  dlg.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:center;justify-content:center';
  dlg.innerHTML = `
    <div style="background:var(--gw-surface-1,#fff);border-radius:12px;padding:28px;width:min(420px,90vw);box-shadow:0 8px 40px rgba(0,0,0,.25)">
      <h3 style="margin:0 0 6px;font-size:16px;font-weight:700">Skip this visit?</h3>
      <p style="font-size:13px;color:var(--gw-text-muted);margin-bottom:16px">Please enter a reason for skipping (required).</p>
      <textarea id="sb-skip-reason-input" class="rp-input" rows="3" placeholder="e.g. Customer requested reschedule, weather, gate locked…" style="width:100%;resize:vertical"></textarea>
      <div style="display:flex;justify-content:flex-end;gap:10px;margin-top:16px">
        <button class="rp-btn" onclick="document.getElementById('sb-skip-reason-modal').remove()">Cancel</button>
        <button class="rp-btn" style="background:#f97316;color:#fff;border-color:#f97316" onclick="_sbConfirmSkip('${woId}')">Skip Visit</button>
      </div>
    </div>`;
  document.body.appendChild(dlg);
};

window._sbConfirmSkip = async function(woId) {
  const reason = document.getElementById('sb-skip-reason-input')?.value?.trim();
  if (!reason) { showToast('Please enter a skip reason','error'); return; }
  document.getElementById('sb-skip-reason-modal')?.remove();
  try {
    await fetch(`/api/work-orders/${woId}`,{
      method:'PUT',credentials:'include',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify({status:'cancelled', completion_notes: 'SKIPPED: ' + reason})
    });
    showToast('Visit skipped','success');
    _sbCloseModal();
    await _sbRefresh();
  } catch(e) { showToast('Failed to skip visit','error'); }
};

window._sbCompleteVisit = async function(woId, woType) {
  // For non-recurring single-service jobs, require after photos
  const isRecurring = (woType||'').toLowerCase().includes('recurring') || (woType||'').toLowerCase().includes('maintenance');
  const afterPhotos = window._sbCurrentWO?.after_photos || [];
  if (!isRecurring && afterPhotos.length === 0) {
    showToast('Please add at least one after photo before marking complete','error');
    // Scroll to photos section
    const photoSection = document.querySelector('#sb-photos-after_photos');
    if (photoSection) photoSection.scrollIntoView({behavior:'smooth',block:'center'});
    // Highlight the section
    const section = photoSection?.closest('.sb-modal-section');
    if (section) {
      section.style.outline = '2px solid var(--gw-danger,#dc2626)';
      section.style.borderRadius = '8px';
      setTimeout(()=>{ section.style.outline=''; }, 2500);
    }
    return;
  }
  await _sbSaveVisit(woId, true);
};

window._sbCrewChanged = function() {
  const crewId = document.getElementById('sbm-crew')?.value;
  const crews = window._sbState.crews||[];
  const crew = crews.find(c=>c.id===crewId);
  if (!crew?.members?.length) return;
  // Auto-suggest crew members
  const chipsEl = document.getElementById('sbm-emp-chips');
  const selectEl = document.getElementById('sbm-add-emp-select');
  crew.members.forEach(m=>{
    const existing = chipsEl?.querySelector(`[data-rep-id="${m.repId}"]`);
    if (!existing) {
      const allReps = window._gwAllReps||[];
      const rep = allReps.find(r=>r.id===m.repId)||{id:m.repId,name:m.name||m.repId};
      const chip = document.createElement('span');
      chip.className='sb-emp-chip'; chip.dataset.repId=m.repId;
      chip.innerHTML=`<span class="sb-emp-dot" style="background:${rep.color||'#6366f1'}"></span>
        ${escapeHtml(rep.name||m.repId)}
        <button onclick="_sbRemoveEmployee('${m.repId}')">×</button>`;
      const placeholder = chipsEl?.querySelector('.sb-empty-note');
      if (placeholder) placeholder.remove();
      chipsEl?.appendChild(chip);
    }
  });
};

window._sbAddEmployee = function() {
  const sel = document.getElementById('sbm-add-emp-select');
  if (!sel || !sel.value) return;
  const repId = sel.value;
  const allReps = window._gwAllReps||[];
  const rep = allReps.find(r=>r.id===repId)||{id:repId,name:repId};
  const chipsEl = document.getElementById('sbm-emp-chips');
  const existing = chipsEl?.querySelector(`[data-rep-id="${repId}"]`);
  if (existing) { showToast('Already added','info'); return; }
  const placeholder = chipsEl?.querySelector('.sb-empty-note');
  if (placeholder) placeholder.remove();
  const chip = document.createElement('span');
  chip.className='sb-emp-chip'; chip.dataset.repId=repId;
  chip.innerHTML=`<span class="sb-emp-dot" style="background:${rep.color||'#6366f1'}"></span>
    ${escapeHtml(rep.name||repId)}
    <button onclick="_sbRemoveEmployee('${repId}')">×</button>`;
  chipsEl?.appendChild(chip);
  // Disable in select
  const opt = sel.querySelector(`option[value="${repId}"]`);
  if (opt) opt.disabled=true;
  sel.value='';
};

window._sbRemoveEmployee = function(repId) {
  const chip = document.querySelector(`#sbm-emp-chips [data-rep-id="${repId}"]`);
  if (chip) chip.remove();
  const opt = document.querySelector(`#sbm-add-emp-select option[value="${repId}"]`);
  if (opt) opt.disabled=false;
};

// Equipment item helpers for the edit modal
window._sbAddCrewItem = function() {
  const inp = document.getElementById('sbm-equip-input');
  if (!inp?.value?.trim()) return;
  const val = inp.value.trim();
  const list = document.getElementById('sbm-equip-list');
  const empty = list?.querySelector('.sb-empty-note');
  if (empty) empty.remove();
  const idx = list?.querySelectorAll('.sb-equip-row').length || 0;
  const row = document.createElement('div');
  row.className = 'sb-equip-row';
  row.dataset.idx = idx;
  row.style.cssText = 'display:flex;align-items:center;gap:6px;padding:6px 8px;background:var(--gw-surface-3);border-radius:6px';
  row.innerHTML = `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14.7 6.3a1 1 0 000 1.4l1.6 1.6a1 1 0 001.4 0l3.77-3.77a6 6 0 01-7.94 7.94l-6.91 6.91a2.12 2.12 0 01-3-3l6.91-6.91a6 6 0 017.94-7.94l-3.76 3.76z"/></svg>
    <span style="flex:1;font-size:13px">${escapeHtml(val)}</span>
    <button class="sb-check-del" onclick="this.closest('.sb-equip-row').remove()">×</button>`;
  list?.appendChild(row);
  inp.value = '';
};
window._sbRemoveEquipItem = function(idx) {
  const rows = document.querySelectorAll('#sbm-equip-list .sb-equip-row');
  if (rows[idx]) rows[idx].remove();
};

window._sbToggleCheck = function(idx) {
  const wo = window._sbCurrentWO;
  if (!wo) return;
  if (wo.checklist[idx]) wo.checklist[idx].done = !wo.checklist[idx].done;
  const box = document.querySelectorAll('#sbm-checklist .sb-check-box')[idx];
  const lbl = document.querySelectorAll('#sbm-checklist .sb-check-label')[idx];
  if (box) { box.classList.toggle('done',wo.checklist[idx].done); box.innerHTML=wo.checklist[idx].done?'<svg width="10" height="10" viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M2 6l3 3 5-5"/></svg>':''; }
  if (lbl) lbl.classList.toggle('done',wo.checklist[idx].done);
};
window._sbRemoveCheck = function(idx) {
  const wo = window._sbCurrentWO; if (!wo) return;
  wo.checklist.splice(idx,1);
  const el = document.querySelectorAll('#sbm-checklist .sb-check-item')[idx];
  if (el) el.remove();
};
window._sbAddCheck = function() {
  const text = prompt('Checklist item:'); if (!text) return;
  const wo = window._sbCurrentWO; if (!wo) return;
  wo.checklist.push({text,done:false});
  const container = document.getElementById('sbm-checklist');
  const placeholder = container?.querySelector('.sb-empty-note');
  if (placeholder) placeholder.remove();
  const idx = wo.checklist.length-1;
  const div=document.createElement('div'); div.className='sb-check-item';
  div.innerHTML=`<button class="sb-check-box" onclick="_sbToggleCheck(${idx})"></button>
    <span class="sb-check-label">${escapeHtml(text)}</span>
    <button class="sb-check-del" onclick="_sbRemoveCheck(${idx})">×</button>`;
  container?.appendChild(div);
};

window._sbAddLine = function() {
  const container = document.getElementById('sbm-line-items');
  if (!container) return;
  const wo = window._sbCurrentWO;
  if (!wo.materials) wo.materials=[];
  const idx = wo.materials.length;
  wo.materials.push({name:'',qty:1,unit:'ea',cost:0});
  const div=document.createElement('div'); div.className='sb-line-row';
  div.innerHTML=`<input class="rp-input" placeholder="Item / Service" style="flex:2">
    <input class="rp-input" value="1" type="number" min="0" style="width:60px" placeholder="Qty">
    <input class="rp-input" placeholder="Unit" style="width:70px">
    <input class="rp-input" value="0" type="number" min="0" placeholder="Rate" style="width:80px">
    <button class="rp-btn-sm rp-btn-sm--danger" onclick="_sbRemoveLine(${idx})">×</button>`;
  container.appendChild(div);
};
window._sbAddPackage = function() { showToast('Package library coming soon','info'); };
window._sbRemoveLine = function(idx) {
  const rows=document.querySelectorAll('#sbm-line-items .sb-line-row');
  if (rows[idx]) rows[idx].remove();
};
window._sbUploadPhoto = function(evt, field) {
  const file = evt.target?.files?.[0]; if (!file) return;
  const reader=new FileReader();
  reader.onload=e=>{
    const url=e.target.result;
    const wo=window._sbCurrentWO; if (!wo) return;
    if (!wo[field]) wo[field]=[];
    wo[field].push(url);
    const container=document.getElementById(`sb-photos-${field}`);
    const addBtn=container?.querySelector('.sb-photo-add');
    const thumb=document.createElement('div'); thumb.className='sb-photo-thumb';
    thumb.innerHTML=`<img src="${url}" alt="photo"><button onclick="_sbRemovePhoto('${field}','${url}')">×</button>`;
    if(addBtn) container.insertBefore(thumb,addBtn); else container?.appendChild(thumb);
  };
  reader.readAsDataURL(file);
};
window._sbRemovePhoto = function(field, idxOrUrl) {
  const wo=window._sbCurrentWO; if(!wo) return;
  const idx = parseInt(idxOrUrl, 10);
  if (!isNaN(idx)) {
    // index-based removal (new path)
    (wo[field]||[]).splice(idx, 1);
    const container=document.getElementById(`sb-photos-${field}`);
    if (container) {
      const thumbs = container.querySelectorAll('.sb-photo-thumb');
      if (thumbs[idx]) thumbs[idx].remove();
      // Re-index remaining thumbs
      container.querySelectorAll('.sb-photo-thumb').forEach((el,i) => el.dataset.pi = i);
    }
  } else {
    // legacy url-based removal
    wo[field]=(wo[field]||[]).filter(u=>u!==idxOrUrl);
    const container=document.getElementById(`sb-photos-${field}`);
    container?.querySelectorAll('.sb-photo-thumb').forEach(el=>{
      if(el.querySelector('img')?.src===idxOrUrl) el.remove();
    });
  }
};

// ── Attachment helpers (photos + PDFs) ────────────────────────────────────────
window._sbUploadAttachment = function(evt) {
  const files = Array.from(evt.target?.files || []);
  if (!files.length) return;
  const wo = window._sbCurrentWO; if (!wo) return;
  if (!wo.attachments) wo.attachments = [];
  const list = document.getElementById('sbm-attachments-list');
  const emptyNote = list?.querySelector('.sb-empty-note');
  files.forEach(file => {
    const reader = new FileReader();
    reader.onload = e => {
      const url = e.target.result;
      const isPdf = file.type === 'application/pdf';
      const attach = { name: file.name, url, type: isPdf ? 'pdf' : 'image' };
      wo.attachments.push(attach);
      const idx = wo.attachments.length - 1;
      if (emptyNote) emptyNote.remove();
      const row = document.createElement('div');
      row.className = 'sb-attach-row';
      row.dataset.idx = idx;
      row.innerHTML = `
        <span class="sb-attach-icon">${isPdf ? gwIcon('document',14) : gwIcon('image',14)}</span>
        <span class="sb-attach-name" style="flex:1;font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escapeHtml(file.name)}</span>
        <a href="${url}" target="_blank" class="rp-btn-sm" style="padding:2px 8px;font-size:11px">View</a>
        <button class="sb-check-del" onclick="_sbRemoveAttachment(${idx})">×</button>`;
      list?.appendChild(row);
    };
    reader.readAsDataURL(file);
  });
};

window._sbRemoveAttachment = function(idx) {
  const wo = window._sbCurrentWO; if (!wo) return;
  wo.attachments = (wo.attachments || []).filter((_,i) => i !== idx);
  const row = document.querySelector(`#sbm-attachments-list [data-idx="${idx}"]`);
  if (row) row.remove();
  if (!wo.attachments.length) {
    const list = document.getElementById('sbm-attachments-list');
    if (list && !list.querySelector('.sb-attach-row')) {
      list.innerHTML = '<p class="sb-empty-note">No attachments yet.</p>';
    }
  }
};

